typedef struct State {
    int state_id;
    struct State *next;
} State;

State *create_state_list(int *states, int num_states, State *fsa, int last_state) {
    size_t new_list_size;
    State *new_list, *current;

    new_list_size = sizeof(State) * (num_states + 1);

    if (new_list_size > (size_t)INT_MAX) {
        return NULL;
    }

    new_list = (State *) malloc(new_list_size);
    if (new_list == NULL) {
        return NULL;
    }

    for (int i = 0; i < num_states; i++) {
        new_list[i].state_id = states[i];
        new_list[i].next = &new_list[i + 1];
    }

    new_list[num_states].state_id = last_state;
    new_list[num_states].next = NULL;

    if (fsa != NULL) {
        current = fsa;
        for (int i = 0; i <= num_states; i++) {
            while (current->next != NULL) {
                if (current->state_id == new_list[i].state_id) {
                    current->next = &new_list[i];
                    break;
                }
                current = current->next;
            }
        }
    }

    return new_list;
}
