#include <string.h> // for strcpy and strlen

char* my_strdup(char** strs, size_t num_strs) {
    size_t total_len = 0;
    size_t i;

    if (!strs || num_strs == 0) {
        return NULL;
    }

    for (i = 0; i < num_strs; i++) {
        total_len += strlen(strs[i]) + 1; // +1 for null character
    }

    char* result = malloc(total_len);
    if (!result) {
        return NULL;
    }

    size_t current_pos = 0;
    for (i = 0; i < num_strs; i++) {
        strcpy(result + current_pos, strs[i]);
        current_pos += strlen(strs[i]) + 1;
    }

    return result;
}
