typedef struct {
    char key[100];
    int value;
} ResourceItem;

typedef struct {
    int num_items;
    ResourceItem *items;
} ResourceBundle;

int load_resource_bundle(const char *path, ResourceBundle **bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    fscanf(file, "%d", &((*bundle)->num_items));
    (*bundle)->items = malloc(sizeof(ResourceItem) * (*bundle)->num_items);

    for (int i = 0; i < (*bundle)->num_items; i++) {
        fscanf(file, "%s %d", (*bundle)->items[i].key, &((*bundle)->items[i].value));
    }

    fclose(file);

    if (feof(file)) {
        perror("Reached end of file prematurely");
        free((*bundle)->items);
        (*bundle) = NULL;
        return 1;
    }

    return 0;
}

void free_resource_bundle(ResourceBundle *bundle) {
    free(bundle->items);
    free(bundle);
}
