#include <stdlib.h> // for malloc and size_t

typedef struct Node {
    int key;
    size_t offset;
    struct Node *left, *right;
} Node;

Node* insert_offset(Node** root, size_t offset) {
    if (*root == NULL) {
        *root = malloc(sizeof(Node));
        if (*root == NULL) {
            return NULL;
        }
        (*root)->key = 0;
        (*root)->offset = offset;
        (*root)->left = NULL;
        (*root)->right = NULL;
        return *root;
    }

    if ((*root)->offset > offset) {
        (*root)->left = insert_offset(&((*root)->left), offset);
    } else {
        (*root)->right = insert_offset(&((*root)->right), offset);
    }

    return *root;
}
