ErrorCode dns_resolve_hostname(const char *hostname, u_char *ip_address, size_t *ip_address_length) {
    struct addrinfo hints, *res;
    int error;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error != 0) {
        herror("getaddrinfo");
        return FAIL;
    }

    if (ip_address != NULL && ip_address_length != NULL) {
        *ip_address_length = res->ai_family == AF_INET ? sizeof(struct in_addr) : sizeof(struct in6_addr);
        memcpy(ip_address, res->ai_addr, *ip_address_length);
    }

    freeaddrinfo(res);
    return OK;
}

ErrorCode dns_resolve_hostname_with_limit(const char *hostname, u_char *ip_address, size_t *ip_address_length, int time_limit_ms) {
    struct addrinfo hints, *res;
    int error, prev_error;
    clock_t start_time;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    error = getaddrinfo(hostname, NULL, &hints, &res);
    if (error != 0) {
        herror("getaddrinfo");
        return FAIL;
    }

    start_time = clock();
    prev_error = error;

    do {
        if (ip_address != NULL && ip_address_length != NULL) {
            *ip_address_length = res->ai_family == AF_INET ? sizeof(struct in_addr) : sizeof(struct in6_addr);
            memcpy(ip_address, res->ai_addr, *ip_address_length);
        }

        freeaddrinfo(res);

        if (time_limit_ms > 0 && (clock() - start_time) > time_limit_ms) {
            error = NO_RECOVERY;
            break;
        }

        error = getaddrinfo(hostname, NULL, &hints, &res);
    } while (error != 0 && (error != EAI_AGAIN || prev_error != EAI_AGAIN));

    if (error == EAI_AGAIN && prev_error == EAI_AGAIN) {
        return TRY_AGAIN;
    }

    if (error != 0) {
        herror("getaddrinfo");
        return FAIL;
    }

    freeaddrinfo(res);
    return OK;
}
