udp_file_t *udp_fopen(char const * filename, char const * mode) {
    udp_file_t *fd;
    int sockfd, new_sockfd, len;
    struct sockaddr_in server_addr;
    struct stat statinfo;

    fd = malloc(sizeof(udp_file_t));
    if (fd == NULL) {
        perror("Error allocating memory for udp_file_t\n");
        return NULL;
    }

    fd->filename = strdup(filename);

    fd->sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (fd->sockfd < 0) {
        perror("Error creating socket\n");
        free(fd->filename);
        free(fd);
        return NULL;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    len = sizeof(server_addr);

    if (connect(fd->sockfd, (struct sockaddr *)&server_addr, len) < 0) {
        perror("Error connecting to server\n");
        close(fd->sockfd);
        free(fd->filename);
        free(fd);
        return NULL;
    }

    fd->file = fopen(filename, mode);
    if (fd->file == NULL) {
        perror("Error opening file\n");
        close(fd->sockfd);
        free(fd->filename);
        free(fd);
        return NULL;
    }

    fstat(fileno(fd->file), &statinfo);

    fd->data = malloc(statinfo.st_size);
    if (fd->data == NULL) {
        perror("Error allocating memory for data\n");
        fclose(fd->file);
        free(fd->filename);
        close(fd->sockfd);
        free(fd);
        return NULL;
    }

    len = recvfrom(fd->sockfd, fd->data, statinfo.st_size, 0, NULL, NULL);
    if (len < 0) {
        perror("Error receiving file\n");
        free(fd->data);
        fclose(fd->file);
        free(fd->filename);
        close(fd->sockfd);
        free(fd);
        return NULL;
    }

    fd->datalen = statinfo.st_size;

    return fd;
}

void udp_fclose(udp_file_t * fd) {
    free(fd->filename);
    free(fd->data);
    fclose(fd->file);
    close(fd->sockfd);
    free(fd);
}
