} device_data;

static void print_status(device_data *device_data, int sample_number) {
	char squelch_mode_str[10];

	switch (device_data->squelch_mode) {
		case 0:
			strcpy(squelch_mode_str, SQUELCH_MODE_OFF);
			break;
		case 1:
			strcpy(squelch_mode_str, SQUELCH_MODE_ON);
			break;
		default:
			strcpy(squelch_mode_str, "Unknown");
			break;
	}

	printf("%d : %s (%d), rssi = %d dB\n", sample_number, squelch_mode_str, device_data->squelch_mode, device_data->rssi);
}

static int get_signal_and_squelch(device_data *device_data) {
	int ret;
	int buffer[2];

	ret = read(0, buffer, sizeof(buffer));
	if (ret < 0) {
		perror("Error reading from device");
		return ret;
	}

	device_data->rssi = buffer[0];
	device_data->squelch_mode = buffer[1];

	return 0;
}

void device_status_function(void *device_data_ptr) {
	device_data *device_data = (device_data *) device_data_ptr;
	int sample_number = 0;
	int status_change = 1;

	while (1) {
		get_signal_and_squelch(device_data);

		if (status_change || (sample_number % 100 == 0)) {
			print_status(device_data, sample_number);
			status_change = 0;
		}

		sample_number++;
		usleep(100000);
	}
}
