#define MAX_LINE_LENGTH 1024

typedef struct {
    char *line;
    size_t length;
} line_t;

bool is_comment(const char *line) {
    return (line[0] == '#');
}

line_t read_line(FILE *file) {
    line_t line;
    char buffer[MAX_LINE_LENGTH];
    size_t len = 0;

    while (fgets(buffer, MAX_LINE_LENGTH, file) != NULL) {
        if (is_comment(buffer)) continue;

        line.length = strlen(buffer);
        line.line = malloc(line.length + 1);
        strcpy(line.line, buffer);

        if (line[0] == '\'' && isalnum(line[1])) {
            size_t i = 1;
            while (line[i] && isalnum(line[i])) i++;
            line.length += i - 1;
            line.line[line.length] = '\0';
            continue;
        }

        break;
    }

    return line;
}

size_t process_file(const char *filename, size_t *num_strings, size_t *num_string_counts) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return 0;
    }

    size_t num_lines = 0;
    line_t current_line;
    bool in_string = false;
    size_t string_count = 0;

    while ((current_line = read_line(file)).length > 0) {
        num_lines++;

        if (current_line.line[0] == '!') {
            sscanf(current_line.line, "!%ld", &string_count);
            *num_string_counts += string_count;
        }

        if (in_string) {
            if (current_line.length < 2 || current_line.line[current_line.length - 1] != '\'') {
                free(current_line.line);
                continue;
            }
            *num_strings += 1;
            free(current_line.line);
            in_string = false;
        }

        if (current_line.line[0] == '\'') {
            in_string = true;
            continue;
        }
    }

    if (in_string) {
        free(current_line.line);
        *num_strings += 1;
    }

    fclose(file);

    *num_strings += (*num_strings > 0 ? *num_string_counts : 0);

    return num_lines;
}
