#include <stdlib.h>
#include <stdio.h>

typedef struct pool_tag {
    size_t size;
    void *start;
    void *end;
    struct pool_tag *next;
} pool_t;

pool_t *pool = NULL;

void init_pool(size_t array_size, size_t element_size) {
    size_t num_elements = array_size;
    size_t total_size = num_elements * element_size;

    if (pool) {
        free_pool();
    }

    pool = (pool_t *)calloc(1, sizeof(pool_t) + total_size);
    if (!pool) {
        perror("calloc failed");
        return;
    }

    pool->size = total_size;
    pool->start = (char *)pool + sizeof(pool_t);
    pool->end = (char *)pool + total_size;
    pool->next = NULL;
}

void *alloc_array(size_t num_elements) {
    size_t element_size = sizeof(void *);
    void *array_ptr = NULL;
    size_t new_size = num_elements * element_size;

    if (pool->end - (char *)pool < new_size) {
        init_pool(num_elements, element_size);
    }

    array_ptr = (void *)((char *)pool->start + pool->size - new_size);
    pool->size -= new_size;

    return array_ptr;
}

void *alloc_element(size_t element_size) {
    void *element_ptr = NULL;

    if ((char *)pool->end - (char *)pool < element_size) {
        init_pool(1, element_size);
    }

    element_ptr = (void *)((char *)pool->start + pool->size);
    pool->size += element_size;

    return element_ptr;
}

void free_pool() {
    if (pool) {
        free(pool);
        pool = NULL;
    }
}
