void ethernet_device_init(struct net_device **dev) {
    /* Allocate memory for the device structure. */
    *dev = calloc(1, sizeof(struct net_device));
    if (!*dev) {
        printk(KERN_ERR "Failed to allocate memory for net_device.\n");
        return;
    }

    /* Initialize the device structure. */
    (*dev)->destructor = free_netdev;
    (*dev)->netdev_ops = NULL;

    /* Fill in device structure with ethernet-generic values. */
    ether_setup(*dev);

    /* Set all fields to zero. */
