    memset((*dev)->dev_addr, 0, ETH_ALEN);
    memset((*dev)->mac_addr, 0, ETH_ALEN);
    memset((*dev)->data, 0, sizeof((*dev)->data));
    memset((*dev)->stats, 0, sizeof((*dev)->stats));

    /* Register the device with the ethernet driver. */
    if (register_netdev(*dev) < 0) {
        free_netdev(*dev);
