// Global state variables
volatile uint8_t tx_buffer[1024]; // Replace with the actual packet size
volatile uint16_t tx_len = 0;
volatile uint16_t checksum = 0;
volatile uint8_t awaiting_ack = 0;

void transmit_packet(uint8_t *packet, uint16_t length) {
    uint8_t i;
    uint16_t temp_checksum;

    // Transmit each byte of the packet
    for (i = 0; i < length; i++) {
        serial_putc(SERIAL_PORT, packet[i]);
        tx_buffer[tx_len++] = packet[i];
    }

    // Calculate checksum
    temp_checksum = 0;
    for (i = 0; i < length; i++) {
        temp_checksum += tx_buffer[i];
    }
    checksum = ~temp_checksum & 0xFF; // 1's complement

    // Send checksum
    serial_putc(SERIAL_PORT, checksum);

    // Set global variable to indicate that an acknowledgement is awaited
    awaiting_ack = 1;
