cl_command_queue create_command_queue(cl_context context, cl_device_id device_id) {
    cl_command_queue command_queue = NULL;
    cl_int error_code;

    cl_context_properties properties[] = {CL_CONTEXT_PLATFORM, NULL, CL_CONTEXT_DEVICE_TYPE, CL_DEVICE_TYPE_DEFAULT, NULL};
    cl_context new_context = clCreateContextFromType(context, CL_DEVICE_TYPE_DEFAULT, NULL, NULL, properties, &error_code);
    if (error_code != CL_SUCCESS) {
        fprintf(stderr, "Error: Failed to create a new context. %s\n", clGetErrorString(error_code));
        return NULL;
    }

    command_queue = clCreateCommandQueue(new_context, device_id, 0, &error_code);
    if (error_code != CL_SUCCESS) {
        fprintf(stderr, "Error: Failed to create a command queue for the device. %s\n", clGetErrorString(error_code));
        clFlushBuffer(new_context, NULL, 0, NULL, NULL);
        clFinish(new_context);
        clReleaseContext(new_context);
        return NULL;
    }

    error_code = clGetContextInfo(context, CL_CONTEXT_DEVICES, sizeof(cl_device_id), &device_id, NULL, NULL);
    if (error_code != CL_SUCCESS) {
        fprintf(stderr, "Error: Failed to retrieve devices for the context. %s\n", clGetErrorString(error_code));
        clReleaseCommandQueue(command_queue);
        clReleaseContext(new_context);
        return NULL;
    }

    return command_queue;
}
