#include <stdlib.h>
#include <stdio.h> // for assert

typedef struct my_allocator {
    size_t size;
    void *ptr;
    size_t (*fn_realloc)(void*, size_t);
} my_allocator_t;

void *my_allocator_alloc(my_allocator_t *allocator, size_t size) {
    if (!allocator || !allocator->fn_realloc) {
        fprintf(stderr, "Invalid allocator object.\n");
        return NULL;
    }

    if (size == 0) {
        fprintf(stderr, "Requested size is zero.\n");
        return NULL;
    }

    void *result = allocator->fn_realloc(NULL, size);
    if (!result) {
        fprintf(stderr, "Allocation failed.\n");
        return NULL;
    }

    allocator->size = size;
    allocator->ptr = result;

    return result;
}

void my_allocator_free(my_allocator_t *allocator) {
    if (!allocator || !allocator->fn_realloc) {
        fprintf(stderr, "Invalid allocator object.\n");
        return;
    }

    if (allocator->ptr) {
        allocator->fn_realloc(allocator->ptr, 0);
        allocator->ptr = NULL;
        allocator->size = 0;
    }
}

void *my_allocator_realloc(my_allocator_t *allocator, void *ptr, size_t size) {
    if (!allocator || !allocator->fn_realloc) {
        fprintf(stderr, "Invalid allocator object.\n");
        return NULL;
    }

    if (size == 0) {
        my_allocator_free(allocator);
        return NULL;
    }

    if (allocator->ptr == ptr) {
        return my_allocator_alloc(allocator, size);
    }

    if (size > allocator->size) {
        size_t new_size = sizeof(my_allocator_t) + size;
        void *new_ptr = my_allocator_alloc(allocator, new_size);
        if (!new_ptr) {
            return NULL;
        }

        if (allocator->ptr) {
            memcpy(new_ptr, allocator->ptr, allocator->size);
        }

        my_allocator_free(allocator);
        allocator->ptr = new_ptr;
        allocator->size = size;
    }

    return ptr;
}
```

