char *IntToStr(int num) {
    static char str[32];
    int i = 0, sign = 1;

    if (num < 0) {
        sign = -1;
        num = -num;
    }

    while (num > 0) {
        str[i++] = num % 10 + '0';
        num /= 10;
    }

    if (sign < 0) str[i++] = '-';
    str[i] = '\0';

