int search_files_pattern(char *pattern, char **filenames, int *nr_files) {
    int file_count = 0;
    int max_files = 128;
    char **files = calloc(max_files, sizeof(char *));
    glob_t glob_result;

    if (!files) {
        perror("calloc");
        return -1;
    }

    if (strchr(pattern, '*')) {
        strcpy(files[file_count], pattern);

        if (glob(files[file_count], 0, NULL, &glob_result) == 0) {
            *nr_files = glob_result.gl_pathc;
            for (int i = 0; i < *nr_files; i++) {
                if (mp_path_exists(glob_result.gl_pathv[i])) {
                    filenames[file_count++] = strdup(glob_result.gl_pathv[i]);
                }
            }
            globfree(&glob_result);
        }
    } else {
        filenames[file_count++] = strdup(pattern);
        if (mp_path_exists(filenames[file_count - 1])) {
            (*nr_files)++;
        }
    }

    while (file_count < max_files && *nr_files < max_files) {
        char temp_filename[1024];
        int len = snprintf(temp_filename, sizeof(temp_filename), "%s%d", pattern, file_count);
        if (len >= sizeof(temp_filename)) {
            free(files);
            return -1;
        }

        if (mp_path_exists(temp_filename)) {
            filenames[file_count++] = strdup(temp_filename);
            (*nr_files)++;
        }
    }

    free(files);
    return *nr_files;
}
