    if ((directory = dirname(file_path)) == NULL) {
        return strdup("."); // return current directory if file_path is absolute
    }

    size_t dir_len = strlen(directory);

    char * dir_path = malloc(dir_len + 1); // +1 for '\0'
    strcpy(dir_path, directory);

