typedef struct {
    MYSQL_STMT *stmt;
    int num_cols;
} prepared_stmt;

void bind_params(prepared_stmt *stmt, int argc, ...) {
    va_list args;
    int i;

    va_start(args, argc);

    for (i = 0; i < argc; i++) {
        MYSQL_BIND bind;
        bind.buffer_type = MYSQL_TYPE_LONG;
        bind.buffer = malloc(sizeof(long));
        bind.length = 0;
        bind.is_null = 0;

        if (mysql_stmt_bind_param(stmt->stmt, i + 1, &bind, sizeof(bind)) != 0) {
            fprintf(stderr, "[MySQL] Error: Could not bind parameter %d\n", i + 1);
            return;
        }

        bind.length = va_arg(args, long);
    }

    va_end(args);
}

int execute_prepared_stmt(MYSQL *mysql, const char *sql, ...) {
    prepared_stmt stmt;
    int argc;
    int ret;

    if (mysql_stmt_prepare(mysql, sql, strlen(sql)) != 0) {
        fprintf(stderr, "[MySQL] Error: Could not prepare statement\n");
        return 0;
    }

    stmt.stmt = mysql_stmt_store_result(mysql);
    argc = mysql_stmt_param_count(stmt.stmt);

    if (argc > 0) {
        stmt.num_cols = mysql_stmt_field_count(stmt.stmt);
        bind_params(&stmt, argc, __VA_ARGS__);
    }

    ret = mysql_stmt_execute(stmt.stmt);

    if (ret != 0 && stmt.num_cols > 0) {
        my_ulonglong rows_affected;
        my_ulonglong data_length;

        if (mysql_stmt_data_length(stmt.stmt, &data_length) != 0) {
            fprintf(stderr, "[MySQL] Error: Could not get data length\n");
            return 0;
        }

        if (mysql_stmt_store_result(stmt.stmt) != NULL) {
            if (mysql_stmt_fetch(stmt.stmt) != 0) {
                int i;
                for (i = 0; i < stmt.num_cols; i++) {
                    MYSQL_RES *result = mysql_store_result(stmt.stmt);
                    MYSQL_ROW row = mysql_fetch_row(result);
                    printf("%s", row[i] ? row[i] : "NULL");
                    if (i < stmt.num_cols - 1)
                        printf("%s", mysql_result_data(stmt.stmt)[i + 1] == '\0' ? "  " : "|");
                }
                mysql_free_result(result);
            }

            mysql_store_result(stmt.stmt);
        }

        mysql_stmt_close(stmt.stmt);
        mysql_stmt_free_result(stmt.stmt);

        if (mysql_stmt_affected_rows(stmt.stmt, &rows_affected) != 0) {
            printf(" %ld rows affected\n", (long) rows_affected);
        }
    }

    mysql_stmt_close(stmt.stmt);

    return ret == 0 ? 1 : 0;
}
