        close(fd);
        return -1; // File path is a directory
    }

    int len = strlen(filePath) + strlen(fileName) + 2; // +2 for '/' and '\0'
    char* newPath = new char[len];
    strcpy(newPath, filePath);
    strcat(newPath, "/");
    strcat(newPath, fileName);

    if (mkdir(newPath, 0777) < 0) {
        perror("mkdir");
        delete[] newPath;
        close(fd);
        return -1;
    }

    strcpy(newPath + strlen(newPath), fileEntry.fileName);
    int ret = link(filePath, newPath);
    if (ret < 0) {
        perror("link");
        rmdir(newPath);
        delete[] newPath;
        close(fd);
        return -1;
    }

    delete[] newPath;
    close(fd);
    return 0;
}
