int parseFileNames(const char *buffer, size_t size, FileInfo fileInfo[]) {
    size_t i = 0, j = 0;
    int index = 0;

    while (i < size) {
        if (buffer[i] == '\n') {
            if (j > 0) {
                fileInfo[index].length = j;
                strncpy(fileInfo[index].fileName, buffer + index, j);
                index++;
                j = 0;
