        if (j >= MAX_FILENAME_LENGTH - 1) {
            i++;
            continue;
        }
        buffer[j++] = buffer[i];
        i++;
    }

    if (j > 0) {
        fileInfo[index].length = j;
        strncpy(fileInfo[index].fileName, buffer + i - j, j);
        index++;
    }

    return index;
}
