int socket_init(const char *protocol, const char *path, const char *name)
{
	int sockfd = -1;
	int yes = 1;
	int optVal = 1;

	if ((sockfd = socket(AF_UNSPEC, SOCK_STREAM, 0)) < 0) {
		perror("socket()");
		return -1;
	}

	if (setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(int)) < 0) {
		perror("setsockopt()");
		close(sockfd);
		return -1;
	}

	struct sockaddr_in serv_addr;
	memset(&serv_addr, 0, sizeof(serv_addr));
	serv_addr.sin_family = AF_INET;
	serv_addr.sin_port = htons(atoi(name));
	inet_pton(AF_INET, path, &serv_addr.sin_addr);

	if (connect(sockfd, (struct sockaddr *) &serv_addr, sizeof(serv_addr)) < 0) {
		perror("connect()");
		close(sockfd);
		return -1;
	}

	if (setsockopt(sockfd, SOL_SOCKET, SO_SNDTIMEO, &timeout, sizeof(timeout)) < 0) {
		perror("setsockopt()");
		close(sockfd);
		return -1;
	}

	if (setsockopt(sockfd, SOL_SOCKET, SO_RCVTIMEO, &timeout, sizeof(timeout)) < 0) {
		perror("setsockopt()");
		close(sockfd);
		return -1;
	}

	if (setsockopt(sockfd, IPPROTO_TCP, TCP_NODELAY, &optVal, sizeof(int)) < 0) {
		perror("setsockopt()");
		close(sockfd);
		return -1;
	}

	return sockfd;
