#define UPDATE_DELAY 10000000 // 10ms

void progress_bar(int percent) {
    int progress_bar_length = MAX_PROGRESS_BAR_LENGTH;
    int progress = percent / 100.0 * progress_bar_length;
    int start_pos = 0;
    int end_pos = progress;

    initscr();
    raw();
    noecho();
    keypad(stdscr, TRUE);
    curs_set(0);

    int y = LINES / 2;
    int x = COLS / 2 - MAX_PROGRESS_BAR_LENGTH / 2;

    int max = MAX_PROGRESS_BAR_LENGTH;
    int speed = 0;

    int prev_percent = 0;

    while (percent < 100) {
        if (percent > prev_percent) {
            if (end_pos < progress_bar_length) {
                end_pos++;
            }
            if (speed == 0) {
                mvprintw(y, x, "[%s]", "");
                refresh();
                usleep(UPDATE_DELAY);
                noecho();
                clrtoeol();
                mvprintw(y, x, "[%s]", "");
                int len = end_pos - start_pos;
                memmove(stdscr->subwin[0]->buf + x, len, stdscr->subwin[0]->buf + x + start_pos, len);
                wrefresh(stdscr->subwin[0]);
                start_pos = end_pos;
                prev_percent = percent;
            }
        }

        percent += 1;
        usleep(10000);
    }

    mvprintw(y, x, "[%s]", "==========");
    refresh();
    getch();
    endwin();
}
