#include <stdlib.h> // for realloc()
#include <string.h> // for memmove()

void remove_trailing_crlf_and_append_newline(char **str) {
    size_t len = strlen(*str);
    if (len > 0 && ((*str)[len - 1] == '\n' || *str[len - 1] == '\r')) {
        *str = realloc(*str, len - 1); // free last char
        if (*str == NULL) {
            fprintf(stderr, "Failed to reallocate memory.\n");
            exit(EXIT_FAILURE);
        }
        memmove(*str + len - 1, *str, len); // move back string
    }
    if (len == 0 || (*str)[len - 1] != '\n') {
        *str = realloc(*str, len + 1); // allocate new char for newline
        if (*str == NULL) {
            fprintf(stderr, "Failed to reallocate memory.\n");
            exit(EXIT_FAILURE);
        }
        (*str)[len] = '\n';
    }
}
