char *copy_string_with_comma(const char *input) {
    size_t input_length = strlen(input);
    char *output = malloc(input_length + 2); // +2 for quotation marks

    *output = '"';
    for (size_t i = 0; i < input_length; i++) {
        *(output + i + 1) = input[i];
        if (input[i] == ',') {
            *(output + i + 1) = ',';
            *(output + i + 2) = ',';
            i++; // move to next character after comma
            input_length++; // update input length
        }
    }
    *(output + input_length + 1) = '"';
    *(output + input_length + 2) = '\0';

    return output;
}
