typedef void (*CallbackFunction)(const char * file_path);

void traverse_directory(const char * dir_path, CallbackFunction callback, int recursive) {
    DIR * dir;
    struct dirent * entry;
    struct stat file_stat;

    if (!(dir = opendir(dir_path))) {
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        char file_path[1024];
        snprintf(file_path, sizeof(file_path), "%s/%s", dir_path, entry->d_name);
        if (stat(file_path, &file_stat) < 0) {
            continue;
        }

        if (S_ISDIR(file_stat.st_mode)) {
            if (recursive) {
                traverse_directory(file_path, callback, recursive);
            }
        } else {
            callback(file_path);
        }
    }

    closedir(dir);
}

void callback_example(const char * file_path) {
    printf("Processing file: %s\n", file_path);
}

int main() {
    traverse_directory("./", callback_example, 1);
    return 0;
