typedef struct Blob {
    int x, y;
    int lifetime;
    struct Blob *next;
} Blob;

Blob *create_blob(int x, int y) {
    Blob *new_blob = (Blob *) malloc(sizeof(Blob));
    new_blob->x = x;
    new_blob->y = y;
    new_blob->lifetime = rand() % 10 + 1;
    new_blob->next = NULL;
    return new_blob;
}

void update_grid(Blob **grid, int width, int height) {
    Blob *current = *grid;
    Blob *next;

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            if (current == NULL) {
                current = create_blob(x, y);
                *grid = current;
            } else {
                next = current->next;
                if (next == NULL) {
                    current->next = create_blob(x, y);
                } else {
                    while (next != NULL) {
                        if (next->x == x && next->y == y) {
                            next->lifetime = rand() % 10 + 1;
                            break;
                        }
                        next = next->next;
                    }
                    if (next == NULL) {
                        current->next = create_blob(x, y);
                    }
                }
            }
            current = current->next;
        }
    }
}

void free_grid(Blob *grid) {
    Blob *current = grid;
    Blob *next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
}

int main() {
    int width = 10;
    int height = 10;
    Blob *grid = NULL;

    update_grid(&grid, width, height);

    // Use the grid here...

    free_grid(grid);

    return 0;
}
