int
CreateUnixSocket(const char *sockFile)
{
  int sock;
  struct sockaddr_un addr;

  if(strlen(sockFile) + 1 > sizeof(addr.sun_path)) {
    perror("CreateUnixSocket: socket file name too long");
    return -1;
  }

  sock = socket(AF_UNIX, SOCK_STREAM, 0);
  if (sock < 0) {
    perror("CreateUnixSocket: socket");
    return -1;
  }

  addr.sun_family = AF_UNIX;
  strcpy(addr.sun_path, sockFile);

  if (bind(sock, (struct sockaddr *)&addr, sizeof(addr.sun_family) + strlen(addr.sun_path)) < 0) {
    perror("CreateUnixSocket: bind");
    close(sock);
    return -1;
  }

  return sock;
}
