#include <nvkmmap.h> /* for nvlist_lookup_uint64() */

char* raidz_path_with_parity(char* device_path) {
    struct nvlist* config;
    uint64_t parity_level;

    config = nvkmmap_device_config(device_path, NV_DEVICE_TYPE_RAIDZ);
    if (!config) {
        return strdup(device_path);
    }

    parity_level = nvlist_lookup_uint64(config, "parity_level", 0);
    nvkmunmap_nvlist(config);

    if (parity_level == 0) {
        return strdup(device_path);
    }

    size_t new_length = strlen(device_path) + 18; /* 18 is for ":-:p-:" + parity_level length */
    char* new_path = (char*) malloc(new_length);
    snprintf(new_path, new_length, "%s:-:p-%llx", device_path, parity_level);

    free(device_path);
    return new_path;
}
