int fetch_file(const char *filename, const char *ip_address, const char mode) {
    int sockfd, new_sockfd, portno, n;
    struct sockaddr_in server_addr;
    struct hostent *server;
    FILE *fp;
    char buffer[BUFSIZE];
    int status = 0;

    // Create socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("ERROR opening socket");
        return 1;
    }

    // Get server information
    server = gethostbyname(ip_address);
    if (server == NULL) {
        fprintf(stderr, "ERROR, no such host\n");
        return 1;
    }

    portno = atoi("80"); // Change this to the desired port number

    // Prepare the sockaddr_in structure
    bzero((char *) &server_addr, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    bcopy((char *)server->h_addr,
         (char *)&server_addr.sin_addr.s_addr,
         server->h_length);
    server_addr.sin_port = htons(portno);

    // Connect to the server
    if (connect(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("ERROR connecting");
        return 1;
    }

    // Send request packet
    if (write(sockfd, "GET /", 4) < 0 ||
        write(sockfd, filename, strlen(filename)) < 0 ||
        write(sockfd, "\r\n", 2) < 0) {
        perror("ERROR writing to socket");
        return 1;
    }

    // Receive response packet
    if (read(sockfd, buffer, BUFSIZE) < 0) {
        perror("ERROR reading from socket");
        return 1;
    }

    // Check for error status in response
    if (strstr(buffer, "HTTP/1.1 4") != NULL) {
        perror("ERROR: Unable to retrieve file");
        status = 1;
    }

    // Create new socket for data transfer
    new_sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (new_sockfd < 0) {
        perror("ERROR opening new socket");
        return 1;
    }

    // Accept data connection from server
    if (accept(sockfd, (struct sockaddr *)&server_addr, (socklen_t*)NULL) < 0) {
        perror("ERROR on accept");
        return 1;
    }

    // Open local file for writing
    fp = fopen(filename, mode);
    if (fp == NULL) {
        perror("ERROR opening local file for write");
        return 1;
    }

    // Read/write file data
    while ((n = read(new_sockfd, buffer, BUFSIZE)) > 0) {
        if (fwrite(buffer, n, 1, fp) < 0) {
            perror("ERROR writing to local file");
            status = 1;
            break;
        }
    }

    // Close sockets and file
    close(new_sockfd);
    close(sockfd);
    fclose(fp);

    return status;
}
