void bubbleSort(int *arr, int size) {
    int swapped;
    for (int j = 0; j < size - 1; j++) {
        swapped = 0;
        for (int i = 0; i < size - j - 1; i++) {
            if (arr[i] > arr[i + 1]) {
                int temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                swapped = 1;
            }
        }
        // If no two elements were swapped in the inner loop, then the array is already sorted
        if (swapped == 0) {
            break;
        }
    }
}

