void copy_buffer(const void* src, void* dest, size_t size, size_t* src_size) {
    if (size > *src_size) { // buffer too small
        size_t new_size = size;
        void* temp = malloc(new_size);
        if (temp == NULL) { // handle malloc failure
            return;
        }

        size_t bytes_read = 0;
        size_t bytes_to_read = size;
        void* src_ptr = src;

        do {
            size_t bytes_to_copy = (src_size > 0 && size + bytes_read >= *src_size)
                                  ? (*src_size - (size + bytes_read)) : size;
            memcpy(temp + bytes_read, src_ptr, bytes_to_copy);
            src_ptr += bytes_to_copy;
            bytes_read += bytes_to_copy;
            size -= bytes_to_copy;
        } while (size > 0);

        free(src); // free old buffer
        *src_size = new_size;
        memcpy(dest, temp, new_size);
    } else {
        memcpy(dest, src, size);
    }
}
