#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HASH_TABLE_SIZE 101

typedef struct {
    char key[50];
    int value;
    int is_active;
} pair_t;

typedef struct {
    pair_t data[HASH_TABLE_SIZE];
} bucket_t;

typedef struct {
    int order;
    bucket_t buckets[HASH_TABLE_SIZE];
} hashtable_t;

int hash_str(const char *str)
{
    int hash = 5381;
    int i;

    for (i = 0; str[i]; i++)
        hash = ((hash << 5) + hash) + str[i]; /* hash * 33 + c */

    return hash % HASH_TABLE_SIZE;
}

pair_t *hashtable_find_pair(hashtable_t *hashtable, bucket_t *bucket, const char *key, int hash)
{
    int i;

    for (i = 0; i < HASH_TABLE_SIZE; i++) {
        if (bucket->data[i].is_active && strcmp(key, bucket->data[i].key) == 0)
            return &bucket->data[i];

        if (bucket->data[i].is_active && hashnext(hash, i) == hash)
            return &bucket->data[i];
    }

    return NULL;
}

int hashnext(int hash, int index)
{
    return (hash + index + 1) % HASH_TABLE_SIZE;
}

int hashtable_lookup(hashtable_t *hashtable, const char *key, int *collisions)
{
    pair_t *pair;
    size_t hash;
    bucket_t *bucket;
    int i;

    hash = hash_str(key);
    bucket = &hashtable->buckets[hash & hashmask(hashtable->order)];

    pair = hashtable_find_pair(hashtable, bucket, key, hash);

    if (!pair) {
        *collisions = -1;
        return -1;
    }

    *collisions = pair->is_active ? 0 : 1;
    return pair->value;
}
