struct path_table_record {
    uint8_t length;
    uint8_t flags[2];
    uint16_t padding[3];
    uint32_t volume_sequence_number;
    uint32_t path_table_file_reference;
};

int read_iso9660_path_table(char *volume_descriptor, size_t size, uint32_t *num_records) {
    struct path_table_record *path_table;
    size_t i = 0;
    char *buffer = malloc(size);
    if (!buffer) {
        perror("malloc");
        return -ENOMEM;
    }

    memcpy(buffer, volume_descriptor, size);

    path_table = (struct path_table_record *) buffer;

    *num_records = 0;

    while (i < (size / sizeof(struct path_table_record))) {
        if (path_table->length < 1 || path_table->length > 32) {
            free(buffer);
            return -EINVAL;
        }

        if (path_table->flags[0] & 0x80) {
            if (read_iso9660_path_table_extended(buffer, path_table->length, num_records) < 0) {
                free(buffer);
                return -EIO;
            }
            break;
        }

        (*num_records)++;
        path_table = (struct path_table_record *) ((char *) path_table + path_table->length);
        i += path_table->length;
    }

    free(buffer);
    return 0;
}

int read_iso9660_path_table_extended(char *buffer, uint8_t length, uint32_t *num_records) {
    struct path_table_record path_table;
    struct iso9660_directory_entry *directory_entry;
    size_t i = 0;
    char *buffer_end = buffer;
    uint32_t current_volume_sequence_number = 0;

    memset(&path_table, 0, sizeof(path_table));

    memcpy(&path_table, buffer, sizeof(path_table));

    while (i < length) {
        directory_entry = (struct iso9660_directory_entry *) (buffer_end + path_table.padding[1]);

        if (directory_entry->length < 28 || directory_entry->length > 2 * 1024) {
            return -EINVAL;
        }

        if (directory_entry->name[0] != 0x05) {
            i += directory_entry->length;
            continue;
        }

        if (current_volume_sequence_number != path_table.volume_sequence_number) {
            *num_records += (path_table.length / sizeof(struct path_table_record));
            current_volume_sequence_number = path_table.volume_sequence_number;
            path_table = (struct path_table_record) {};
        }

        memcpy(&path_table, buffer + i, sizeof(path_table));
        i += path_table.length;
    }

    *num_records += (path_table.length / sizeof(struct path_table_record));

    return 0;
}
