bool validate_oauth2_token(const char *token_str) {
    json_t *root;
    json_error_t error;

    root = json_loads(token_str, 0, &error);

    if (!root) { // Check if parsing was successful
        json_decref(root);
        return false;
    }

    json_t *access_token, *expires_in, *token_type, *refresh_token;
    json_error_t token_error;

    access_token = json_object_get(root, "access_token");
    if (!access_token) {
        json_decref(root);
        return false;
    }

    expires_in = json_object_get(root, "expires_in");
    if (!expires_in) {
        json_decref(root);
        return false;
    }

    token_type = json_object_get(root, "token_type");
    if (!token_type || json_string_value(token_type) == NULL ||
        json_string_value(token_type) != "Bearer") {
        json_decref(root);
        return false;
    }

    if (json_is_number(expires_in) && json_number_value(expires_in) > 0) {
        json_decref(root);
        return true;
    }

    if (json_object_size(root) > 4) { // Optional refresh_token
        refresh_token = json_object_get(root, "refresh_token");
        json_decref(root);
        // You can add a check for the refresh_token here if needed
    } else {
        json_decref(root);
        return true;
    }

    json_error_t token_parse_error;
    int expires_in_int = json_number_value(expires_in);
    json_t *error_obj;

    json_t *parsed_expires_in = json_pack("{ki{si}}", "error", "expires_in", expires_in_int);
    json_object_set_new(root, "error", parsed_expires_in);
    error_obj = json_error_from_err(json_dumps(root, 0, &token_parse_error), &token_error);
    const char *error_msg = json_string_value(error_obj);

    json_decref(root);
    json_decref(error_obj);

    // Print error message for debugging purposes
    printf("Error validating token: %s\n", error_msg);
    return false;
}
