        char name[32];
        snprintf(name, sizeof(name), "AES-%d", i);
        if (EVP_add_cipher(EVP_symmetric(EVP_aes_128_cbc(), name, NULL)) < 0) {
            fprintf(stderr, "Error adding AES-%d cipher.\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Add DES
    if (EVP_add_cipher(EVP_des_cbc()) < 0) {
        fprintf(stderr, "Error adding DES cipher.\n");
        exit(EXIT_FAILURE);
    }

    // Add RSA
    if (EVP_add_encryption_method() < 0) {
        fprintf(stderr, "Error adding RSA encryption method.\n");
        exit(EXIT_FAILURE);
