#define MD4_BLOCK_SIZE 64
#define MD4_STATE_SIZE 128 // 64 bytes for state buffer, 16 bytes for integers

typedef struct {
    uint32_t state[4];
    uint8_t buffer[MD4_BLOCK_SIZE];
    size_t buf_len;
} md4_context;

static inline void rol(uint32_t *value, uint32_t bits) {
    uint32_t carry = *value >> (32 - bits);
    *value = (*value << bits) | carry;
}

static inline void md4_absorb(md4_context *ctx, const uint8_t *data, size_t len) {
    size_t i;

    if (ctx->buf_len + len > MD4_BLOCK_SIZE) {
        size_t remaining = MD4_BLOCK_SIZE - ctx->buf_len;
        memcpy(ctx->buffer + ctx->buf_len, data, remaining);
        len -= remaining;
        md4_process(ctx);
    }

    ctx->buf_len += len;
    memcpy(ctx->buffer + ctx->buf_len - len, data, len);
}

static inline void md4_process(md4_context *ctx) {
    uint32_t a = ctx->state[0];
    uint32_t b = ctx->state[1];
    uint32_t c = ctx->state[2];
    uint32_t d = ctx->state[3];

    size_t i;

    for (i = 0; i < MD4_BLOCK_SIZE / 64; ++i) {
        uint64_t x[16];

        for (size_t j = 0; j < 16; ++j) {
            x[j] = ((uint64_t)ctx->buffer[i * 64 + j * 4] << 24) |
                   ((uint64_t)ctx->buffer[i * 64 + j * 4 + 1] << 16) |
                   ((uint64_t)ctx->buffer[i * 64 + j * 4 + 2] << 8) |
                   ((uint64_t)ctx->buffer[i * 64 + j * 4 + 3]);

            rol(x[j], 9);
            x[j] = (x[j] & 0xFFFFFFFF) + a;
            a = b;
            b = c;
            c = d;
            d = x[j];
        }

        uint32_t temp = a;
        a = b + ((b & c) | (~b & d));
        b = c;
        c = d;
        d = temp;
    }

    ctx->state[0] += a;
    ctx->state[1] += b;
    ctx->state[2] += c;
    ctx->state[3] += d;

    ctx->buf_len = 0;
}

