void checkMemoryAllocation(int width, int height) {
    if (overflow2(width * height, sizeof(unsigned char) * width * height)) {
        std::cerr << "Error: Failed to allocate memory for image.\n";
        return;
    }
}

unsigned char* createBlankImage(int width, int height) {
    checkMemoryAllocation(width, height);

    std::unique_ptr<unsigned char[]> imageData(new unsigned char[width * height]);
    if (!imageData) {
        std::cerr << "Error: Failed to allocate memory for image data.\n";
        return nullptr;
    }

    std::vector<std::unique_ptr<unsigned char[]>> rows(height, std::make_unique<unsigned char[]>(width));
    for (auto& row : rows) {
        if (!row) {
            for (size_t i = 0; i < height; i++) {
                std::unique_ptr<unsigned char[]> tempRow(rows[i].release());
                std::unique_ptr<unsigned char[]> tempData(imageData.release());
                delete[] tempRow.get();
                imageData = std::move(std::unique_ptr<unsigned char[]>(std::move(tempData)));
                return nullptr;
            }
        }
    }

    std::unique_ptr<unsigned char*> image(imageData.release());
    for (auto& row : rows) {
        std::unique_ptr<unsigned char[]> tempRow(row.release());
        std::unique_ptr<unsigned char[]> tempData(image.get());
        image = std::move(std::unique_ptr<unsigned char[]>(std::move(tempData)));
        row = std::move(std::unique_ptr<unsigned char[]>(std::move(tempRow)));
        std::fill(row.get(), row.get() + width, 0);
    }

    for (size_t i = 0; i < height; i++) {
        std::copy(row[i].begin(), row[i].end(), image.get() + i * width);
    }

    return image.release();
}
