#include <vector>
#include <algorithm>
#include <utility>

using namespace std;

struct Pair {
    int value;
    bool selected;
};

struct Combination {
    int sum;
    int num_selected;
    vector<int> indices;

    Combination(int sum, int num_selected) : sum(sum), num_selected(num_selected) {}

    bool operator<(const Combination& other) const {
        if (sum == other.sum) {
            return num_selected < other.num_selected;
        }
        return sum < other.sum;
    }
};

void find_best_combination(const vector<Pair>& pairs, int target_sum, Pair& best_pair) {
    vector<Pair> remaining_pairs;
    vector<Combination> combinations;

    copy(pairs.begin(), pairs.end(), back_inserter(remaining_pairs));

    combinations.push_back(Combination(0, 0));

    while (!remaining_pairs.empty()) {
        Pair current_pair = remaining_pairs.back();
        remaining_pairs.pop_back();

        for (auto& combination : combinations) {
            int new_sum = combination.sum + current_pair.value;
            int new_num_selected = combination.num_selected + (current_pair.selected ? 1 : 0);

            if (new_sum >= target_sum) {
                continue;
            }

            combinations.push_back(Combination(new_sum, new_num_selected));
            combination.indices.push_back(-static_cast<int>(remaining_pairs.size()));
        }

        auto it = lower_bound(combinations.begin(), combinations.end(), Combination(target_sum, numeric_limits<int>::max()));

        if (it != combinations.end() && it->sum == target_sum) {
            best_pair = current_pair;
            best_pair.selected = true;
            for (auto index : it->indices) {
                int index_abs = abs(index);
                pairs[index_abs] = current_pair;
            }
            break;
        }
    }
}
