void createAndCheckSortedSets(std::vector<int>& originalSet, std::vector<int>& newSet) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, originalSet.size());

    std::srand(time(0)); // For random number generation in case of function call multiple times

    int numElements = dis(gen) + 1; // Random number of elements between 1 and size of originalSet

    std::cout << "Number of elements: " << numElements << std::endl;

    // Create original set and check if it's sorted
    std::sort(originalSet.begin(), originalSet.end());
    if (!isSorted(originalSet)) {
        std::cout << "Error: Original set is not sorted!" << std::endl;
        return;
    }

    // Create new set by inserting elements of original set
    newSet.clear();
    for (int i = 0; i < numElements; ++i) {
        int index = dis(gen) % originalSet.size();
        newSet.push_back(originalSet[index]);
        originalSet.erase(originalSet.begin() + index);
    }

    // Check if new set is sorted and equal to original set
    std::sort(newSet.begin(), newSet.end());
    if (!isSorted(newSet)) {
        std::cout << "Error: New set is not sorted!" << std::endl;
        return;
    }

    if (newSet.size() != originalSet.size()) {
        std::cout << "Error: New set and original set have different sizes!" << std::endl;
