std::string generate_random_string(int length) {
    std::srand(std::time(nullptr));
    std::string result;

    for (int i = 0; i < length; ++i) {
        int randomIndex;
        if (length - i > 1) {
            randomIndex = rand() % (26 + 10 + 32); // 26 lowercase, 10 digits, 32 special chars
        } else {
            randomIndex = rand() % (26 + 10); // No special chars for a single character
        }

        if (length - i > 1) {
            result += (randomIndex < 26) ? (char)('a' + randomIndex) :
                     (randomIndex < 26 + 10) ? (char)('0' + (randomIndex - 26)) :
                     special_chars[randomIndex - (26 + 10)];
        } else {
            result += (randomIndex < 26) ? (char)('a' + randomIndex) :
                     (randomIndex < 26 + 10) ? (char)('0' + (randomIndex - 26)) :
                     special_chars[0];
        }
    }

    return result;
}
