    vector<int> getEntitiesByLayer(const string& layerName) {
        vector<int> ids;
        string sql = "SELECT id FROM entities WHERE layer = ?";
        sqlite3_stmt* stmt;

        if (sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr) != SQLITE_OK) {
