void set_env_var(char *name, char *value) {
    char *old_value = getenv(name);
    if (old_value) {
        free(old_value);
    }
    size_t len = strlen(name) + strlen(value) + 2;
    char *new_env_var = malloc(len);
    if (new_env_var == NULL) {
        perror("malloc: out of memory");
        return;
    }
    snprintf(new_env_var, len, "%s=%s", name, value);
    setenv(name, new_env_var, 1); // 1 means "overwrite"
    free(new_env_var);
}

char *copy_string(char *str) {
    size_t len = strlen(str) + 1;
    char *copy = malloc(len);
    if (copy == NULL) {
        perror("malloc: out of memory");
        return NULL;
    }
    strcpy(copy, str);
    return copy;
}

char *create_env_var(char *old_env_var_name, char *new_env_var) {
    char *old_env_var = getenv(old_env_var_name);

    // Remove existing environment variable
    if (old_env_var != NULL) {
        setenv(old_env_var_name, NULL, 0); // 0 means "delete"
        free(old_env_var);
    }

    // Allocate memory for a copy of the new string
    char *new_env_var_copy = copy_string(new_env_var);
    if (new_env_var_copy == NULL) {
        return NULL;
    }

    // Set the new environment variable
    set_env_var(old_env_var_name, new_env_var_copy);

    return new_env_var_copy;
}

char **new_environment_variables(int *num_env_vars, char **env_vars, char *new_env_var) {
    char **new_env_vars = malloc(*num_env_vars + 2 * sizeof(char *));
    if (new_env_vars == NULL) {
        perror("malloc: out of memory");
        return NULL;
    }

    for (int i = 0; i < *num_env_vars; ++i) {
        new_env_vars[i] = env_vars[i];
    }

    char *new_env_var_copy = create_env_var("", new_env_var);
    if (new_env_var_copy == NULL) {
        free(new_env_vars);
        return NULL;
    }

    new_env_vars[*num_env_vars++] = new_env_var_copy;

    return new_env_vars;
}

void free_environment_variables(int num_env_vars, char **env_vars) {
    for (int i = 0; i < num_env_vars; ++i) {
        free(env_vars[i]);
