typedef struct {
    size_t len;
    unsigned char *bytes;
} byte_vector;

byte_vector ecies_encrypt(byte_vector plaintext, byte_vector key) {
    byte_vector iv = {AES_BLOCK_SIZE, malloc(AES_BLOCK_SIZE)};
    byte_vector tag = {EVP_MAX_MD_SIZE, malloc(EVP_MAX_MD_SIZE)};
    byte_vector encrypted = {0};
    EVP_CIPHER_CTX *ctx;
    EVP_MD_CTX *md;
    int ret;

    EVP_CIPHER_init_cipher(&ctx, EVP_aes_128_cbc(), key.bytes, iv.bytes);

    ret = EVP_CIPHER_do_init(ctx);
    if (ret != 1) {
        free(iv.bytes);
        free(tag.bytes);
        free(encrypted.bytes);
        EVP_CIPHER_CTX_free(ctx);
        printf("Error initializing cipher: %s\n", EVP_ErrorString(ret, NULL, NULL));
        exit(EXIT_FAILURE);
    }

    ret = EVP_CIPHER_do_crypt(ctx, ENCRYPT, plaintext.bytes, plaintext.len, NULL, &encrypted.len);
    if (ret != 1) {
        free(iv.bytes);
        free(tag.bytes);
        free(encrypted.bytes);
        EVP_CIPHER_CTX_free(ctx);
        printf("Error encrypting data: %s\n", EVP_ErrorString(ret, NULL, NULL));
        exit(EXIT_FAILURE);
    }

    EVP_MD_CTX_init(&md);
    MD_CTX_set0(md);
    MD_CTX_use_md(md, EVP_ripemd160());
    MD_CTX_update(md, iv.bytes, AES_BLOCK_SIZE);
    MD_CTX_update(md, key.bytes, key.len);
    MD_CTX_update(md, plaintext.bytes, plaintext.len);
    MD_CTX_update(md, encrypted.bytes, encrypted.len);
    MD_CTX_finalize(md, tag.bytes);

    free(iv.bytes);
    free(plaintext.bytes);

    byte_vector output = {encrypted.len + EVP_MAX_MD_SIZE, malloc(encrypted.len + EVP_MAX_MD_SIZE)};
    memcpy(output.bytes, encrypted.bytes, encrypted.len);
    memcpy(output.bytes + encrypted.len, tag.bytes, EVP_MAX_MD_SIZE);

    free(iv.bytes);
    free(key.bytes);
    free(encrypted.bytes);
    free(tag.bytes);
    EVP_MD_CTX_free(md);
    EVP_CIPHER_CTX_free(ctx);

    return output;
}
