#include <random> // For std::mt19937 and std::uniform_int_distribution

template<typename DataType, int RowDim, int ColDim, int SizeIndex>
void randomizeSparseMatrix(DataType* values, int* rowPtr, int* colInd, int numRows) {
    std::mt19937 generator; // Mersenne Twister pseudo-random number generator
    std::uniform_int_distribution<int> distribution(0, std::numeric_limits<DataType>::max());

    // Seed the generator with current time to ensure randomness
    std::time_t now = std::time(nullptr);
    generator.seed(now);

    for (int i = 0; i < numRows; ++i) {
        for (int j = rowPtr[i]; j < rowPtr[i + 1]; ++j) {
            int row = colInd[j];
            int col = SizeIndex == 0 ? colInd[j] : colInd[j] + 1; // Adjust for CSC format
            values[j] = distribution(generator);
            if (row < i) { // Handle boundaries for CSR format
                int k = rowPtr[row];
                for (; k < rowPtr[row + 1]; ++k) {
                    if (colInd[k] == col) {
                        values[k] = values[j];
                        break;
                    }
                }
            }
        }
    }
}
