#include <vector>

void generateWireframeIndices(int* inputArray, int size, int& primitivesCount) {
    std::vector<int> pointsIndices(3 * size); // 3 indices per point for lines and faces
    std::vector<int> linesIndices(size); // 2 indices per line
    std::vector<int> facesIndices(3 * size); // 3 indices per face

    std::vector<int>* currentIndices = &pointsIndices;
    int counter = 0;

    for (int i = 0; i < size; ++i) {
        int pointIndex = counter++;
        currentIndices->at(pointIndex) = i;
        currentIndices->at(pointIndex + 1) = i + 1;
        currentIndices->at(pointIndex + 2) = i + 1;

        if (i < size - 1) {
            currentIndices = &linesIndices;
            currentIndices->at(counter++) = pointIndex;
            currentIndices->at(counter++) = pointIndex + 1;
        }

        if (i < size - 2) {
            currentIndices = &facesIndices;
            currentIndices->at(counter++) = pointIndex;
            currentIndices->at(counter++) = pointIndex + 1;
            currentIndices->at(counter++) = pointIndex + 2;
        }
    }

    primitivesCount += pointsIndices.size() / 3; // Points are considered as vertices
    primitivesCount += linesIndices.size(); // Lines are considered as edges

    // Allocate memory for the output arrays using new
    int* pointsIndicesArray = new int[pointsIndices.size().bytes()];
    std::copy(pointsIndices.begin(), pointsIndices.end(), pointsIndicesArray);

    int* linesIndicesArray = new int[linesIndices.size().bytes()];
    std::copy(linesIndices.begin(), linesIndices.end(), linesIndicesArray);

    int* facesIndicesArray = new int[facesIndices.size().bytes()];
    std::copy(facesIndices.begin(), facesIndices.end(), facesIndicesArray);

    // Return the output arrays and increment the counter
    pointsIndices.clear();
    linesIndices.clear();
    facesIndices.clear();

    return {pointsIndicesArray, linesIndicesArray, facesIndicesArray, linesIndicesArray, primitivesCount};
