template <typename Container>
std::vector<size_t> getUniqueElementCounts(const std::initializer_list<Container>& containers) {
    std::vector<size_t> counts;
    std::unordered_map<typename Container::value_type, bool> uniqueElements;

    for (const Container& container : containers) {
        for (const auto& element : container) {
            if (uniqueElements.emplace(element, true).second) {
                counts.push_back(1);
            } else {
                counts.back()++;
            }
        }
    }

    return counts;
}
