#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <upnp.h>

#define MAX_DEVICES 10

typedef struct {
    char description[256];
    UPNP_SSDP_DESCRIPTOR descriptor;
} UPnPDevice;

UPnPDevice devices[MAX_DEVICES];
int num_devices = 0;

void print_device_description(UPNP_SSDP_DESCRIPTOR descriptor) {
    printf("Device Description:\n");
    printf("  Location: %s\n", descriptor.location.host);
    printf("  Device Type: %s\n", descriptor.deviceType);
    printf("  Manufacturer: %s\n", descriptor.manufacturer);
    printf("  Model Number: %s\n", descriptor.modelName);
    printf("  Serial Number: %s\n", descriptor.serialNum);
    printf("  Description: %s\n", descriptor.description);
}

int discover_upnp_devices() {
    int i, sockfd;
    struct sockaddr_in server_addr;
    char search_string[128];
    UPNP_SSDP_EVENT_RESPONSE response;
    int len = sizeof(struct sockaddr_in);

    if ((sockfd = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP)) < 0) {
        perror("socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(1900);

    snprintf(search_string, sizeof(search_string), "*:1900/%s", "ssdp:all");

    if (sendto(sockfd, search_string, strlen(search_string), 0,
            (struct sockaddr *) &server_addr, sizeof(server_addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }

    while (num_devices < MAX_DEVICES) {
        memset(&response, 0, sizeof(UPNP_SSDP_EVENT_RESPONSE));
        if (recvfrom(sockfd, (char) &response, sizeof(UPNP_SSDP_EVENT_RESPONSE), 0,
                (struct sockaddr *) &server_addr, &len) <= 0) {
            perror("recvfrom");
            close(sockfd);
            return -1;
        }

        if (response.eventType != SSDP_EVENT_ALIVE &&
            response.eventType != SSDP_EVENT_BYE) {
            continue;
        }

        if (num_devices < MAX_DEVICES) {
            strcpy(devices[num_devices].description, response.SSDP_DESCRIPTOR.description);
            devices[num_devices].descriptor = response.SSDP_DESCRIPTOR;
            num_devices++;
        }
    }

    close(sockfd);

    printf("Discovered %d UPnP devices:\n", num_devices);
    for (i = 0; i < num_devices; i++) {
        print_device_description(devices[i].descriptor);
    }

    return num_devices;
}

int main() {
    discover_upnp_devices();
    return 0;
}
