typedef struct upnp_device {
    char name[256];
    char description[256];
    char *ip_address;
} upnp_device;

int discover_upnp_devices(char *multicast_address, char *miniupnpc_path) {
    IUPNPDiscover *discover;
    IUPNPDevice *device;
    IUPNPDevice *next_device;
    char err_buf[512];
    int num_devices = 0;
    upnp_device *devices = NULL;

    discover = upnpDiscover(multicast_address, 1900, err_buf, sizeof(err_buf), 0);

    if (discover == NULL) {
        fprintf(stderr, "Error discovering UPnP devices: %s\n", err_buf);
        return -1;
    }

    while ((device = upnpNextDevice(discover)) != NULL) {
        upnp_device *new_device = malloc(sizeof(upnp_device));

        if (new_device == NULL) {
            upnpDeviceFree(discover);
            fprintf(stderr, "Error allocating memory for device\n");
            return -1;
        }

        strncpy(new_device->name, device->friendlyName, sizeof(new_device->name) - 1);
        strncpy(new_device->description, device->description, sizeof(new_device->description) - 1);
        new_device->ip_address = strdup(device->internalIPAddr.host);

        new_device->next = devices;
        devices = new_device;
        num_devices++;

        upnpDeviceFree(device);
    }

    upnpDiscoverFree(discover);

    if (num_devices == 0) {
        fprintf(stderr, "No UPnP devices found\n");
        return -1;
    }

    printf("Found %d UPnP devices:\n", num_devices);
    for (int i = 0; devices != NULL; i++) {
        printf("%d. %s (%s)\n", i + 1, devices->name, devices->ip_address);
        free(devices->ip_address);
        devices = devices->next;
    }

    free(devices);

    return 0;
}
