    paragraphs->size = sizeof(current_paragraph);

    for (size_t i = 0; i < input_text_length; ++i) {
        char current_char = input_text[i];

        if (current_paragraph_size + 1 >= paragraphs->size) {
            Paragraph *new_paragraph = (Paragraph *) realloc(paragraphs,
                                                           sizeof(Paragraph) *
                                                                 (number_of_paragraphs + 1));
            if (new_paragraph == NULL) {
