        if (current_char == '\n') {
            current_paragraph[current_paragraph_size] = '\0';
            ++number_of_paragraphs;
            current_paragraph_size = 0;
        }
    }

    if (current_paragraph_size > 0) {
        ++number_of_paragraphs;
    }

    free(paragraphs[number_of_paragraphs].data);

    free(paragraphs);

