        return NULL;
    }

    size_t len = strlen(input);
    char *output = malloc(len + 1);
    if (!output) {
        return NULL;
    }

    char *ptr = output;
    for (size_t i = 0; i < len; ++i) {
        if (!isspace((unsigned char)input[i])) {
            *ptr++ = input[i];
        }
    }

    *ptr = '\0';
    return output;
}
