import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.PDImageXObject;
import org.apache.pdfbox.pdmodel.PDPageContentStream;
import org.apache.commons.io.ByteArrayOutputStream;
import org.apache.commons.io.IOUtils;
import java.awt.image.BufferedImage;
import java.awt.Toolkit;
import java.awt.Graphics2D;
import java.awt.image.BufferedImageOp;
import java.awt.image.ResizeOp;

public static byte[] generatePPMImage(PDDocument document, int pageNumber) throws Exception {
    PDPage page = document.getPage(pageNumber);
    PDRectangle pageSize = page.getMediaBox();

    int displayWidth = 256; // Desired display width
    int displayHeight = 256; // Desired display height

    BufferedImage sourceImage = ImageIO.read(page.getResources().getResource(page.getResources().getResourceType(page.getResources().get(0))).getInputStream());
    BufferedImage targetImage = new BufferedImage(displayWidth, displayHeight, BufferedImage.TYPE_BYTE_GRAY);

    BufferedImageOp resizer = new ResizeOp(displayWidth, displayHeight, ResizeOp.NEAREST_NEIGHBOR);
    targetImage = resizer.filter(sourceImage, null);

    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();

    try (PDPageContentStream contentStream = new PDPageContentStream(document, new PDPage(pageSize))) {
        PDImageXObject pdImage = contentStream.createTemplate(pageSize.getWidth(), pageSize.getHeight());
        pdImage.drawImage(ImageIO.createImageInputStream(new ByteArrayInputStream(IOUtils.toByteArray(new ByteArrayInputStream(IOUtils.toByteArray(IOUtils.toInputStream(new ByteArrayInputStream(generatePPMImage(document, pageNumber))))))).getInputStream()), 0, 0, pageSize.getWidth(), pageSize.getHeight());
        contentStream.drawImage(pdImage, 0, 0);
        contentStream.close();
    }

    byte[] ppmImageData = toPPM(targetImage);

    try {
        IOUtils.write(ppmImageData, outputStream);
    } finally {
        outputStream.close();
    }

    return ppmImageData;
}

private static byte[] toPPM(BufferedImage image) {
    int width = image.getWidth();
    int height = image.getHeight();
    int maxPixel = 255;

    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();

    outputStream.write("P5\n".getBytes());
    outputStream.write((width + " " + height + "\n").getBytes());
    outputStream.write("255\n".getBytes());
    outputStream.write("255\n".getBytes());
    outputStream.write("B\n".getBytes());

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int pixel = image.getRGB(x, y);
            double gray = (double) (pixel & 0xFF) / 255.0;
            outputStream.write((int) (gray * maxPixel + 0.5) + " ");
        }
        outputStream.write("\n");
    }

    return outputStream.toByteArray();
}
