#include <iostream>
#include <string>
#include <vector>

struct Node {
    std::string name;
    int duration;
    Node* left;
    Node* right;

    Node(const std::string& name, int duration) : name(name), duration(duration), left(nullptr), right(nullptr) {}
};

void print_node(const Node* node, const std::vector<std::string>& transformations, std::ostream& out) {
    std::string name = node->name;
    for (const auto& transformation : transformations) {
        name = transformation + name;
    }

    out << name << ": " << node->duration << std::endl;

    if (node->left) {
        print_node(node->left, transformations, out);
    }
    if (node->right) {
        print_node(node->right, transformations, out);
    }
}

void traverse_tree(Node* root, const std::vector<std::string>& transformations, std::ostream& out) {
    if (!root) {
        return;
    }

    print_node(root, transformations, out);
    traverse_tree(root->left, transformations, out);
    traverse_tree(root->right, transformations, out);
}

void recursive_print_tree(Node* root, const std::vector<std::string>& transformations) {
    std::stringstream ss;
    traverse_tree(root, transformations, ss);
    std::cout << ss.str();
}
