template<typename T>
void fill_random(vector<vector<T>>& image, int width, int height) {
    default_random_engine generator;
    uniform_int_distribution<int> distribution(0, 255);

    for (auto& row : image) {
        for (auto& pixel : row) {
            pixel = distribution(generator);
        }
    }
}

void measure_access_time(vector<vector<int>>& image, int width, int height, int method) {
    int sum = 0;
    auto start = steady_clock::now();

    if (method == 0) { // Direct indexing
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                sum += image[y][x];
            }
        }
    } else if (method == 1) { // Boundary clamping
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                sum += image[(y + height) % height][(x + width) % width];
            }
        }
    } else if (method == 2) { // Scalar access
        for (auto& row : image) {
            for (auto pixel : row) {
                sum += pixel;
            }
        }
    }

    auto end = steady_clock::now();
    auto duration = duration_cast<microseconds>(end - start);
    cout << "Method " << method << " execution time: " << duration.count() << " microseconds" << endl;
}

void generate_random_image(int width, int height) {
    vector<vector<int>> image(height, vector<int>(width));
    fill_random(image, width, height);

    int method;
    cout << "Enter the method number (0 for direct indexing, 1 for boundary clamping, 2 for scalar access): ";
    cin >> method;

    measure_access_time(image, width, height, method);
}
