void vertical_flip_2d_array(unsigned char* input_array, int width, int height, int pixel_size) {
  size_t x_size = width;
  size_t y_size = height;
  size_t stride = x_size * pixel_size;

  unsigned char* temp_array = new unsigned char[width * height * pixel_size];

  for (size_t y = 0; y < y_size; y++) {
    std::memcpy(temp_array + (height - y - 1) * stride, input_array + y * stride, stride);
  }

  for (size_t y = 0; y < y_size; y++) {
    std::memcpy(input_array + y * stride, temp_array + y * stride, stride);
  }

  delete[] temp_array;
}

