#include <elf.h>

void print_symbol(Elf_Internal_Sym *sym, char *strtab, size_t strtab_size) {
  const char *sstr = sym->st_name ? strtab + sym->st_name : "<no name>";
  printf("%s: ", sstr);
}

void print_symbol_info(Elf_Internal_Sym *sym, Elf_Internal_Shdr *section, char *strtab, size_t strtab_size) {
  printf("%p: ", (void *)sym->st_value);
  printf("%ld ", sym->st_size);
  print_symbol(sym, strtab, strtab_size);
  printf(" %s\n", sym->st_info & STB_GLOBAL ? "GLOBAL" : "LOCAL");
}

void process_symbols(Elf *elf, Elf_Scn *section, char *strtab, size_t strtab_size) {
  Elf_Internal_Sym *sym = NULL;
  Elf_Data *strdata = NULL;
  size_t i, strsize;

  if (section->sh_type != SHT_SYMTAB) {
    fprintf(stderr, "Invalid section type: %d\n", section->sh_type);
    return;
  }

  strdata = elf_getdata(elf, section->sh_link);
  if (!strdata) {
    fprintf(stderr, "Failed to get string table data\n");
    return;
  }

  strsize = strdata->d_size;

  for (i = 0; i < section->sh_info.sh_size / sizeof(Elf_Internal_Sym); i++) {
    sym = elf_getelsym(elf, i);
    if (!sym) {
      fprintf(stderr, "Failed to get symbol %d\n", i);
      continue;
    }

    print_symbol_info(sym, section, strtab, strtab_size);
  }
}

int main(int argc, char **argv) {
  Elf *elf;
  Elf_Scn *section;
  int status;

  if ((elf = elf_parse(argv[1], NULL, 0, ELFCLASS32, EV_CURRENT)) == NULL) {
    fprintf(stderr, "%s\n", elf_errmsg(ELF_ET_MESSAGE));
    return 1;
  }

  if ((section = elf_nextscn(elf, NULL)) == NULL) {
    fprintf(stderr, "No sections in file\n");
    elf_end(elf);
    return 1;
  }

  process_symbols(elf, section, elf_getdata(elf, section->sh_link)->d_buf, elf_dsize(elf, section->sh_link));

  elf_end(elf);
  return 0;
}
