#define FIXED_STRING "INITIAL_STRING"

void custom_asnprintf(char *str, size_t size, const char *format, ...) {
    va_list args;
    int len;

    va_start(args, format);
    len = vsnprintf(str, size, format, args);
    va_end(args);

    if (len >= size) {
        size_t new_size = len + 1;
        char *new_str = realloc(str, new_size);
        if (new_str == NULL) {
            fprintf(stderr, "Failed to allocate memory for custom_asnprintf\n");
