using namespace std;

void MatrixProjectionTest(int numSamples, int tableSize, int inputDimension) {
  // Generate random matrix
  vector<vector<float>> matrix(tableSize, vector<float>(inputDimension));
  default_random_engine generator;
  uniform_real_distribution<float> distribution(0.0, 1.0);

  for (auto &row : matrix) {
    generate(row.begin(), row.end(), [&]() { return distribution(generator); });
  }

  // Generate random vector
  vector<float> vector(inputDimension, 0.0);
  generate(vector.begin(), vector.end(), [&]() { return distribution(generator); });

  // Project vector onto rows of matrix
  vector<float> result(inputDimension, 0.0);
  for (int i = 0; i < tableSize; i++) {
    for (int j = 0; j < inputDimension; j++) {
      result[j] += matrix[i][j] * vector[j];
    }
  }

  // Reference implementation using dot product
  vector<float> reference(inputDimension, 0.0);
  for (int i = 0; i < tableSize; i++) {
    for (int j = 0; j < inputDimension; j++) {
      reference[j] += matrix[i][j] * vector[j];
    }
  }

  // Compare results
  bool isEqual = true;
  for (int i = 0; i < inputDimension; i++) {
    if (result[i] != reference[i]) {
      isEqual = false;
      break;
    }
  }

  // Print log message
  cout << "Matrix Projection Test: numSamples=" << numSamples
       << ", tableSize=" << tableSize
       << ", inputDimension=" << inputDimension
       << ", result=";
  for (auto elem : result) {
    cout << " " << elem;
  }
  cout << ", reference=";
  for (auto elem : reference) {
