void check_process_status(const std::string& pidFile, const std::string& magicNumber) {
    std::ifstream pidFileStream(pidFile);
    if (!pidFileStream.is_open()) {
        std::cerr << "Error opening pid file: " << pidFile << std::endl;
        return;
    }

    std::string pidStr;
    std::getline(pidFileStream, pidStr);
    pidFileStream.close();

    if (pidStr.empty()) {
        std::cout << "Process not running. Run the command as root for more precise information." << std::endl;
        return;
    }

    int pid = std::stoi(pidStr);
    if (kill(pid, 0) == -1) {
        std::cout << "Process not running." << std::endl;
        return;
    }

    std::ifstream statusFile("/proc/" + std::to_string(pid) + "/status");
    if (!statusFile.is_open()) {
        std::cerr << "Error opening process status file for pid: " << pid << std::endl;
        return;
    }

    std::string statusLine;
    std::getline(statusFile, statusLine);

    if (statusLine.find("Name:   ") != std::string::npos) {
        std::cout << "Process with pid " << pid << " is running." << std::endl;
    } else {
        std::cout << "Process with pid " << pid << " is not running. Run the command as root for more precise information." << std::endl;
    }

    statusFile.close();
}

int main() {
    std::string pidFile = "/path/to/pid.file";
    std::string magicNumber = "MAGIC_NUMBER";
    check_process_status(pidFile, magicNumber);
    return 0;
}
