    JDIMENSION line_size;
    JDIMENSION num_components;
    JDIMENSION height_in_blocks;
    JDIMENSION row_ptr[1];
    int byte_per_pixel;
    JPEG_ERROR_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);

    jpeg_create_decompress(&cinfo);
    jpeg_mem_src(&cinfo, buffer, strlen(buffer));

