    jpeg_calc_output_dimensions(&cinfo, &width, &height);
    num_components = cinfo.output_components;
    byte_per_pixel = cinfo.output_components * 3;
    height_in_blocks = (height + 7) / 8;

    line_size = width * byte_per_pixel;
    output_buffer = (*jpeg_malloc) (line_size * height_in_blocks, &jerr);

    jpeg_start_decompress(&cinfo);

    while (cinfo.next_scanline < height_in_blocks) {
        row_ptr[0] = output_buffer + cinfo.output_buffer +
                     cinfo.output_row * line_size;
        jpeg_read_scanlines(&cinfo, row_ptr, 1);
    }

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);

    JSAMPLE *pixels = malloc(width * height * byte_per_pixel);
    if (pixels == NULL) {
        jpeg_free_decompress(&cinfo);
        jpeg_destroy_decompress(&cinfo);
        return NULL;
    }

    for (JDIMENSION i = 0; i < height; i++) {
        memcpy(pixels + i * width * byte_per_pixel, output_buffer + i * line_size, line_size);
    }

    jpeg_free_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    jpeg_free(output_buffer);

    return pixels;
}
