void countingSort(const std::vector<int>& input, std::unordered_map<int, int>& output) {
    std::vector<int> count(10, 0); // An array of size 10 to store the count of each digit

    for (const auto& num : input) {
        count[(num / 10) % 10]++; // Increment the count of the first digit of the number
        if (num % 10 >= 0) {
            count[(num % 10)]++; // Increment the count of the second digit of the number
        }
    }

    output.clear(); // Clear the map before filling it with the frequency of each number

    for (size_t i = 0; i < count.size(); ++i) {
        for (size_t j = 0; j < count[i]; ++j) {
            output[i]++; // Increment the frequency of each number based on the count of its digits
        }
    }

    // Initialize an empty vector to store the numbers in the correct order
    std::vector<int> result;
    result.resize(input.size());

    for (const auto& num : input) {
        result[output[num / 10]++] = num; // Place each number in the correct position based on the frequency of its digits
    }

    // Copy the result into the output map
    for (size_t i = 0; i < result.size(); ++i) {
        output[input[i]] = i; // Store the index of each number in the output map
    }
}

