        graph[node2][node1] = true;

        // Merge connected components
        for (int j = 0; j < MAX_NODES; j++) {
            if (!num_components && j != node1 && !graph[j][node1]) {
                int new_component = j;
                for (int k = 0; k < MAX_NODES; k++) {
                    if (!are_connected(graph, new_component, k)) {
                        num_components++;
