FileHandle *open_file(char const *filename, char const *message) {
    FileHandle *file = malloc(sizeof(FileHandle));
    if (file == NULL) {
        return NULL;
    }

    file->filename = strdup(filename);
    file->fd = fopen(filename, "r+");
    if (file->fd == NULL) {
        free(file->filename);
        free(file);
        return NULL;
    }

    fseek(file->fd, 0, SEEK_END);
    file->datalen = ftell(file->fd);
    rewind(file->fd);

    file->data = malloc(file->datalen + strlen(message) + 1);
    if (file->data == NULL) {
        fclose(file->fd);
        free(file->filename);
        free(file);
        return NULL;
    }

    if (fwrite(message, strlen(message), 1, file->fd) != strlen(message)) {
        fclose(file->fd);
        free(file->filename);
        free(file->data);
        free(file);
        return NULL;
    }

    if (fseek(file->fd, 0, SEEK_SET) != 0) {
        fclose(file->fd);
        free(file->filename);
        free(file->data);
        free(file);
        return NULL;
    }

    return file;
}

void read_message(FileHandle *file) {
    size_t message_length = 0;
    char message[1024];

    while (fgetc(file->fd) != '\n') {
        message[message_length++] = fgetc(file->fd);
    }
    message[message_length] = '\0';

    printf("Message written to file: %s\n", message);

    free(file->filename);
    free(file->data);
    fclose(file->fd);
    free(file);
}

