        return new_address_sa(&s.a, offsetof(struct sockaddr_un, sun_path) +
                              strlen(s.un.sun_path) + 1);
    }

    /* Trailing port */
    if ((port = strrchr(hostname_or_ip, ':')) != NULL &&
            is_numeric(port + 1)) {
        len = (size_t)(port - hostname_or_ip);
        int port_num = atoi(port + 1);

