    double width, height;
    Image *image;
} PlasmaEffectInput;

typedef struct {
    double center_x, center_y;
    Color colormap_start, colormap_end;
} PlasmaEffectSection;

PlasmaEffectSection sections[4] = {
    {250.0, 250.0, {0.0, 0.0, 0.0}, {1.0, 1.0, 1.0}},
    {50.0, 50.0, {1.0, 1.0, 1.0}, {0.0, 0.0, 0.0}},
    {750.0, 50.0, {0.0, 0.0, 0.0}, {1.0, 1.0, 1.0}},
    {50.0, 750.0, {1.0, 1.0, 1.0}, {0.0, 0.0, 0.0}};

MagickExport Image *ApplyPlasmaEffect(const Image *image, double width, double height, double roughness, ExceptionInfo *exception) {
    PlasmaEffectInput input = {width, height, image};
    Image *output = CloneImage(image, 0, 0, MagickTrue, exception);
    if (output == NULL) return NULL;

    double center_x = input.width / 2.0;
    double center_y = input.height / 2.0;

    ImageInfo image_info;
    InitializeImageInfo(&image_info);
    image_info.width = input.width;
    image_info.height = input.height;
    image_info.depth = 8;
    image_info.channels = 3;
    image_info.filename = MagickStringFromFormat("plasma_output.png");
    output = NewImage(&image_info, exception);
    if (output == NULL) {
        DestroyImage(output);
        return NULL;
    }

    for (int i = 0; i < 4; i++) {
        double roughness_factor = roughness / 4.0;
        PlasmaEffectSection current_section = sections[i];

        for (int y = 0; y < input.height; y++) {
            for (int x = 0; x < input.width; x++) {
                Point current_point = {x, y};
                double distance = sqrt(pow(current_point.x - center_x, 2.0) + pow(current_point.y - center_y, 2.0));

                Color new_color;
                double hue = fmod(distance * roughness_factor, 1.0);

                new_color.r = current_section.colormap_start.r + hue * (current_section.colormap_end.r - current_section.colormap_start.r);
                new_color.g = current_section.colormap_start.g + hue * (current_section.colormap_end.g - current_section.colormap_start.g);
                new_color.b = current_section.colormap_start.b + hue * (current_section.colormap_end.b - current_section.colormap_start.b);

                SetPixelColor(output, x, y, NewPixel(new_color.r, new_color.g, new_color.b, 255));
            }
        }
    }

    DestroyImage(&image_info);
    return output;
}
