int
create_and_write_file(const char *name, size_t size, const char *str)
{
    FILE *fp;
    char *data;
    size_t len = strlen(str) + 1;
    int ret = 0;

    data = malloc(len);
    if (!data) {
        warn("memory allocation failed.");
        return -1;
    }

