        fseek(fp, size - 1, SEEK_SET);
        fputchar('\0', fp);
        fseek(fp, 0, SEEK_END);
    }

    if (fwrite(str, 1, len, fp) != len || fflush(fp) != 0) {
        warn("failed to write to file %s.", name);
        ret = -1;
    }

    fclose(fp);
    free(data);

    return ret;
}
