std::string generate_random_string(int length, const std::vector<std::string>& base_strings, double distribution) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, base_strings.size() - 1);

    std::string result;
    for (int i = 0; i < length; ++i) {
        int base_index = dis(gen);
        result += base_strings[base_index][gen() % base_strings[base_index].size()];
    }

    std::shuffle(base_strings.begin(), base_strings.end(), gen); // Shuffle base strings for better distribution

    std::uniform_real_distribution<> dist(0.0, 1.0);
    double total_probability = 0.0;
    int current_index = 0;
    for (const std::string& base_string : base_strings) {
        total_probability += base_string.size();
        if (dist(gen) < total_probability * distribution) {
            result += base_string[gen() % base_string.size()];
        }
        ++current_index;
    }

    return result;
}
