std::vector<int> selectSubset(std::vector<int>& numbers, int target, int& numSelected) {
    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> dis(0, numbers.size() - 1);
    std::vector<int> subset;
    int sum = 0;

    numSelected = 0;

    while (sum < target && numSelected < numbers.size()) {
        int index = dis(gen);
        int num = numbers[index];
        subset.push_back(num);
        sum += num;
        numSelected++;
        numbers.erase(numbers.begin() + index);
    }

    if (sum == target) {
        return subset;
    } else {
        std::vector<int> empty;
        numSelected = 0;
        return empty;
    }
}

