#include <stdlib.h>
#include <string.h>
#include <openssl/hmac.h>
#include <openssl/base.h>
#include <openssl/bio.h>
#include <openssl/buffer.h>

char *hmac_sha1(const char *message, const char *key) {
    unsigned char hmac[EVP_MAX_MD_SIZE];
    unsigned int len = strlen(message) + strlen(key) + 1;
    unsigned int hmac_len;
    HMAC_CTX ctx;
    BIO *bmem;
    BUF_MEM *bptr;

    HMAC_Init(&ctx, key, strlen(key), EVP_sha1(), NULL);
    HMAC_Update(&ctx, message, strlen(message));
    HMAC_Final(&ctx, hmac, &hmac_len);

    bmem = BIO_new(BIO_s_mem());
    bptr = BUF_alloc(hmac_len);
    BIO_write(bmem, hmac, hmac_len);
    BIO_flush(bmem);

    char *signature = BIO_gets_mem_ptr(bmem);
    BIO_free_all(bmem);

    BUF_MEM_free(bptr);

    char *base64_signature = BIO_sk_new_null(TYPE_BIO);
    BIO *base64 = BIO_new(BIO_f_base64());
    BIO *bio_out = BIO_push(base64, base64_signature);
    BIO_write(bio_out, signature, hmac_len);
    BIO_flush(bio_out);
    BIO_get_mem_ptr(base64_signature, &signature);

    HMAC_CTX_free(&ctx);

    return strdup(signature);
}
