#include <boost/python.hpp>
#include <iostream>
#include <string>
#include <boost/asio.hpp>
#include <openssl/sha.h>

using namespace boost::python;
using namespace std;

namespace {
    void kdf2_sha1(const uint8_t* password, size_t password_len,
                   const uint8_t* master_key, size_t master_key_len,
                   uint8_t* output, size_t output_len) {
        SHA_CTX ctx;
        SHA1_Init(&ctx);

        // First iteration
        SHA1_Update(&ctx, password, password_len);
        SHA1_Update(&ctx, master_key, master_key_len);
        SHA1_Final(output, &output_len, &ctx);

        // Second iteration
        SHA1_Init(&ctx);
        SHA1_Update(&ctx, master_key, master_key_len);
        SHA1_Update(&ctx, output, output_len);
        SHA1_Final(output + output_len, &output_len, &ctx);

        // Output transformation
        for (size_t i = 0; i < output_len; ++i) {
            output[i] ^= master_key[i % master_key_len];
        }
    }

    object derive_key(const string& password, const string& master_key,
                      size_t output_length) {
        const size_t password_len = password.size();
        const size_t master_key_len = master_key.size();

        if (password_len == 0 || master_key_len == 0) {
            throw ValueError("Both password and master key must be provided.");
        }

        if (output_length == 0) {
            throw ValueError("Output length must be provided.");
        }

        // Allocate memory for the output key
        uint8_t output[output_length];

        try {
            kdf2_sha1((const uint8_t*)password.c_str(), password_len,
                      (const uint8_t*)master_key.c_str(), master_key_len,
                      output, output_length);

            string result(reinterpret_cast<const char*>(&output), output_length);
            return result;
        } catch (const std::exception& e) {
            throw PythonError("Error deriving key: " + e.what());
        }
    }
} // anonymous namespace

BOOST_PYTHON_MODULE(key_derivation) {
    def("derive_key", derive_key);
}
