#include <vector>
#include <random>
#include <algorithm>

struct Pair { int value; bool selected; };

int find_best_combination(const std::vector<Pair>& pairs, int target) {
    int max_total = 0;
    int current_total = 0;
    std::vector<Pair> remaining_pairs;

    std::mt19937 gen(std::random_device{}());
    std::uniform_int_distribution<> dist(0, pairs.size() - 1);

    while (!remaining_pairs.empty() || current_total < target) {
        int index = dist(gen);
        if (!remaining_pairs[index].selected && current_total + remaining_pairs[index].value <= target) {
            current_total += remaining_pairs[index].value;
            remaining_pairs[index].selected = true;
            if (current_total > max_total) {
                max_total = current_total;
            }
        }
        remaining_pairs.erase(remaining_pairs.begin() + index);
    }

    if (current_total > max_total) {
        max_total = current_total;
    }

    return max_total;
}
