#include <stdio.h>
#include <string.h>
#include <ctype.h>
#define MAX_STRING_LENGTH 100

typedef struct {
    int top;
    char stack[MAX_STRING_LENGTH];
} Stack;

void push_char(Stack *stack, char c) {
    stack->stack[stack->top++] = c;
}

char pop_char(Stack *stack) {
    return stack->stack[--stack->top];
}

int str_case_insensitive_match(const char *str1, const char *str2, int length) {
    Stack char1, char2;
    int i, matching = 1;

    char1.top = -1;
    char2.top = -1;

    for (i = 0; i < length; i++) {
        if (str1[i] != '\0') {
            push_char(&char1, toupper((unsigned char)str1[i]));
        }

        while (char2.top < i && str2[char2.top + 1] != '\0') {
            if (toupper((unsigned char)str2[++char2.top]) != str1[i]) {
                matching = 0;
                break;
            }
        }

        if (str2[i] != '\0') {
            push_char(&char2, toupper((unsigned char)str2[i]));
        }

        if (!matching) {
            break;
        }
    }

    if (char1.top >= 0 && char2.top >= 0) {
        while (char1.top >= 0 && char2.top >= 0) {
            if (toupper((unsigned char)char1.stack[char1.top]) != toupper((unsigned char)char2.stack[char2.top])) {
                matching = 0;
                break;
            }
            char1.top--;
            char2.top--;
        }
    }

    if (str1[length] == '\0' && char1.top < 0 && char2.top < 0) {
        return matching;
    }

    return 0;
}
