struct Option {
    std::string key;
    std::string value;
};

std::vector<Option> parseOptions(const std::string& input) {
    std::vector<Option> options;
    std::stringstream ss(input);
    std::string item;

    while (std::getline(ss, item, ',')) {
        size_t equal = item.find('=');
        if (equal == std::string::npos) {
            throw std::invalid_argument("Option format error: missing '=' in key-value pair.");
        }

        std::string key = item.substr(0, equal);
        std::string value = item.substr(equal + 1);

        if (key.empty() || value.empty()) {
            throw std::invalid_argument("Option format error: empty key or value.");
        }

        options.push_back({key, value});
    }

    return options;
}
