#include <vector>
#include <random>

void percolation_step(std::vector<int>* sites, double probability, int time_step) {
    std::mt19937 gen(time_step); // seed with time step
    std::uniform_int_distribution<> dis(0, sites->size() - 1);

    int selected_site = dis(gen);
    sites->at(selected_site) = 1; // mark site as open

    if (std::rand() < probability * 100) { // apply percolation rule
        for (size_t i = selected_site + 1; i < sites->size(); ++i) {
            if (sites->at(i) == 0) {
                sites->at(i) = 1;
            }
        }
    }
}
