std::vector<std::string> extract_url_components(const std::string& url) {
    std::vector<std::string> components;
    size_t begin, end;

    // Find protocol start
    size_t protocol_start = url.find("://");
    if (protocol_start == std::string::npos) {
        return components;
    }

    // Extract protocol
    begin = protocol_start;
    end = url.find('/', protocol_start);
    if (end == std::string::npos) {
        end = url.size();
    }
    components.push_back(url.substr(begin, end - begin));

    // Find host start
    begin = end;
    if (url[begin] == '/') {
        begin++;
    }
    end = url.find('/', begin);
    if (end == std::string::npos) {
        end = url.size();
