class SandeshClient {
public:
    SandeshClient(io_service& io_service, message_queue& queue)
        : _resolver(io_service), _socket(io_service), _queue(queue) {}

    void sendGetRequest() {
        boost::asio::ip::udp::endpoint server_endpoint;
        _resolver.resolve("localhost", 1900, server_endpoint);

        boost::asio::ip::udp::packet<1024> request(buffer("GET / SandeshRequest"));
        write(_socket, request);

        boost::asio::ip::udp::packet<1024> response;
        deadline_timer timer(_io_service, boost::posix_time::seconds(5));
        int num_bytes = read(_socket, response.data(), response.max_size());

        if (num_bytes > 0) {
            std::cout << "Received response: ";
            std::cout.write(response.data(), num_bytes);
            std::cout << std::endl;

            BOOST_TEST(verifyResponse(response.data(), num_bytes));
        } else {
            std::cerr << "No response received within 5 seconds." << std::endl;
        }

        timer.cancel();
    }

