typedef struct HuffmanNode {
    uint8_t symbol;
    uint8_t frequency;
    struct HuffmanNode *left;
    struct HuffmanNode *right;
} HuffmanNode;

HuffmanNode* create_node(uint8_t symbol, uint8_t frequency) {
    HuffmanNode *new_node = (HuffmanNode*) lodepng_malloc(sizeof(HuffmanNode));
    if (!new_node) {
        return NULL;
    }
    new_node->symbol = symbol;
    new_node->frequency = frequency;
    new_node->left = NULL;
    new_node->right = NULL;
    return new_node;
}

void add_to_queue(HuffmanNode **queue, HuffmanNode *node) {
    while (*queue && (*queue)->frequency < node->frequency) {
        queue = &(*queue)->next;
    }
    node->next = *queue;
    *queue = node;
}

HuffmanNode* build_huffman_tree(uint8_t *symbol_lengths, uint8_t num_symbols) {
    HuffmanNode **queue = NULL;
    HuffmanNode *nodes = (HuffmanNode*) lodepng_malloc(num_symbols * sizeof(HuffmanNode));
    if (!nodes) {
        return NULL;
    }

    for (int i = 0; i < num_symbols; ++i) {
        nodes[i].symbol = i;
        nodes[i].frequency = symbol_lengths[i];
        add_to_queue(&queue, &nodes[i]);
    }

    while (queue && queue[0] && queue[0]->next) {
        HuffmanNode *left = queue[0];
        HuffmanNode *right = queue[0]->next;
        queue[0] = queue[0]->next;

        HuffmanNode *new_node = create_node('\0', left->frequency + right->frequency);
        new_node->left = left;
        new_node->right = right;

        add_to_queue(&queue, new_node);
    }

    HuffmanNode *root = queue[0];
    free(nodes); // free memory for individual nodes
    return root;
}

int huffman_tree_create(uint8_t *symbol_lengths, uint8_t num_symbols, HuffmanNode **tree) {
    *tree = build_huffman_tree(symbol_lengths, num_symbols);
    if (!*tree) {
        return -1; // Allocation failed
    }
    return 0;
}
