char * safe_vsnprintf(char *buffer, size_t size, const char *format, va_list args) {
    va_list ap;
    char *result;

    va_start(ap, args);
    size_t len = vsnprintf(buffer, size, format, ap);
    va_end(ap);

    if (len >= size) {
        char *new_buffer;
        size_t new_size = static_cast<size_t>(len) + 1; // +1 for null terminator

        new_buffer = static_cast<char*>(std::malloc(new_size * sizeof(char)));
        if (new_buffer == nullptr) {
            // handle out of memory error
            return nullptr;
        }

        len = vsnprintf(new_buffer, new_size, format, args);
        if (len < 0) {
            // handle vsnprintf error
            std::free(new_buffer);
            return nullptr;
        }

        result = new_buffer;
    } else {
        result = buffer;
    }

    return result;
}

