        if (result < 0) {
            std::cerr << "Failed to connect to Tor: " << Tor_strerror(tor, result) << std::endl;
            Tor_quit(tor);
            exit(1);
        }

        char *hidden_service_key = new char[1024];
        result = Tor_generate_hidden_service_key(tor, hidden_service_key, 1);
        if (result < 0) {
            std::cerr << "Failed to generate hidden service key: " << Tor_strerror(tor, result) << std::endl;
            Tor_quit(tor);
            exit(1);
        }

        std::string hidden_service_dir = "/tmp/hidden_service";
        result = Tor_create_hidden_service(tor, hidden_service_key, "example.onion", 80, &onion_address, hidden_service_dir.c_str());
        if (result < 0) {
            std::cerr << "Failed to create hidden service: " << Tor_strerror(tor, result) << std::endl;
            Tor_quit(tor);
            exit(1);
        }

        std::string auth_cookie;
        result = Tor_get_auth_cookie(tor, "example.onion", &auth_cookie);
        if (result < 0) {
            std::cerr << "Failed to get authentication cookie: " << Tor_strerror(tor, result) << std::endl;
            Tor_quit(tor);
            exit(1);
        }

        int auth_attempts = 5;
        while (auth_attempts > 0 && !authenticated) {
            result = Tor_make_authenticated_connection(tor, "example.onion:80", private_key.c_str(), auth_cookie.c_str(), NULL, NULL);
            if (result < 0) {
                std::cerr << "Authentication failed: " << Tor_strerror(tor, result) << std::endl;
                Tor_sleep(tor, 1000);
                auth_attempts--;
            } else {
                authenticated = true;
            }
        }

        if (!authenticated) {
            std::cerr << "Failed to authenticate with hidden service" << std::endl;
            Tor_quit(tor);
            exit(1);
        }

        Tor_free(hidden_service_key);
    }

    ~TorProxy() {
        Tor_quit(tor);
    }
};
