#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cstring>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <cstdlib>

std::string sha256_hmac(const std::string& message, const std::string& secret) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    unsigned char key[SHA256_DIGEST_LENGTH];
    std::vector<unsigned char> hmac(SHA256_DIGEST_LENGTH * 2 + message.size());

    std::copy(secret.begin(), secret.end(), key);

    HMAC(EVP_sha256(), key, SHA256_DIGEST_LENGTH, (unsigned char*)message.c_str(), message.size(), digest, &hmac[0]);

    std::copy(digest, digest + SHA256_DIGEST_LENGTH, hmac.begin() + SHA256_DIGEST_LENGTH);

    SHA256_CTX sha256;
    unsigned char hex[SHA256_DIGEST_LENGTH * 2];

    SHA256_Init(&sha256);
    SHA256_Update(&sha256, hmac.data(), hmac.size());
    SHA256_Final(hex, &sha256);

    std::string hex_digest;
    for (int i = 0; i < SHA256_DIGEST_LENGTH * 2; i++) {
        hex_digest += std::hex{}(static_cast<unsigned int>(hex[i]));
        if (i != SHA256_DIGEST_LENGTH * 2 - 1) hex_digest += ':';
    }

    return hex_digest;
}
