template<size_t Height, size_t Width>
float* create_2d_array_with_differences(float default_value = 0.0f) {
    std::vector<std::vector<float>> array(Height, std::vector<float>(Width));

    for (size_t i = 0; i < Height; ++i) {
        for (size_t j = 0; j < Width; ++j) {
            array[i][j] = default_value;
        }
