#include <iostream>
#include <fstream>
#include <vector>

using namespace std;

struct DataPoint {
    float x;
    float y;
};

void linearRegression(const vector<DataPoint>& data, float& m, float& b) {
    float sumX = 0, sumY = 0, sumX2 = 0, sumXY = 0;
    int n = data.size();

    for (int i = 0; i < n; ++i) {
        sumX += data[i].x;
        sumY += data[i].y;
        sumX2 += data[i].x * data[i].x;
        sumXY += data[i].x * data[i].y;
    }

    m = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    b = (sumY - m * sumX) / n;
}

int main() {
    ifstream inputFile("data.txt");
    if (!inputFile.is_open()) {
        cerr << "Error opening file" << endl;
        return 1;
    }

    vector<DataPoint> data;
    DataPoint point;

    while (inputFile >> point.x >> point.y) {
        data.push_back(point);
    }

    int n = data.size();
    cout << "Number of data points: " << n << endl;

    float m, b;
    linearRegression(data, m, b);

    cout << "Linear Regression Results:" << endl;
    cout << "Slope (m): " << m << endl;
    cout << "Intercept (b): " << b << endl;

    return 0;
}
