#include <cstdlib> // for malloc

std::string dyn_string_dup(const std::string& input) {
  size_t length = strlen(input.c_str()) + 1; // add 1 for null terminator
  char* result = static_cast<char*>(std::malloc(length));

  if (result == nullptr) {
    // handle out-of-memory error
