class TestAllocator {
public:
    TestAllocator() { total_allocated = 0; }
    char* allocate(size_t size) {
        char* result = new char[size];
        total_allocated += size;
        return result;
    }
    void printAllocations(bool verbose) const {
        if (verbose) {
            std::cout << "Total allocated memory: " << total_allocated << " bytes\n";
        }
        std::cout << "Memory addresses and sizes:\n";
        for (const auto& alloc : allocations) {
            std::cout << "Allocated memory of length " << alloc.second << " at address " << static_cast<void*>(alloc.first) << "\n";
        }
    }
    ~TestAllocator() {
        for (auto& alloc : allocations) {
            delete[] alloc.first;
        }
        std::cout << "All memory allocated by the test allocator has been freed.\n";
    }

private:
    size_t total_allocated;
    std::vector<std::pair<char*, size_t>> allocations;
};

void initializeAndPrintAllocations(TestAllocator& allocator, int verbosity, const char* format, ...) {
    va_list args;
    va_start(args, format);

    for (size_t length = 0; length <= 100; length++) {
        char* allocatedMemory = allocator.allocate(length);
        allocator.allocations.push_back(std::make_pair(allocatedMemory, length));

        va_list argsCopy;
        va_copy(argsCopy, args);

        size_t size;
        char* result = allocator.allocate(sizeof(char) * vsnprintf(nullptr, 0, format, argsCopy) + length);
        va_end(argsCopy);

        vsnprintf(allocatedMemory, length, format, args);

        std::cout << "Allocated memory of length " << length << " at address " << static_cast<void*>(allocatedMemory) << "\n";
        std::cout << "Address of allocated string: " << static_cast<void*>(result) << "\n";
        std::cout << "String: " << allocatedMemory << "\n";

        if (verbosity > 0) {
            size = strlen(allocatedMemory);
            std::cout << "Size of allocated string: " << size << "\n";
        }

        allocator.allocate(length); // Free the first allocated memory block
    }

    va_end(args);
    allocator.printAllocations(verbosity);
}

