void getEigenvectorsAndEigenvalues(int** matrix, int rows, int cols,
                                  double* eigenvalues, double** eigenvectors) {
  int num_non_zero = 0;
  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      if (matrix[i][j] != 0) {
        ++num_non_zero;
      }
    }
  }

  valarray<complex<double>> mat(rows, cols);
  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      mat(i, j) = complex(static_cast<double>(matrix[i][j]), 0.0);
    }
  }

  lapack_int n = rows;
  lapack_int m = cols;
  lapack_int info;

  complex<double>* work = new complex<double>[rows];
  complex<double>* rwork = new complex<double>[rows * cols];

  zgeev_('V', 'N', &n, &m, mat.data(), &n, eigenvalues, work, rwork, &info);

  if (info != 0) {
    throw runtime_error("Matrix cannot be diagonalized!");
  }

  std::vector<complex<double>> eigenvectors_vec(rows * cols);
  copy(eigenvectors_begin(work), eigenvectors_end(work),
       eigenvectors_vec.begin());

  for (size_t i = 0; i < rows * cols; ++i) {
    eigenvectors[i / cols][i % cols] = eigenvectors_vec[i].real();
    eigenvectors[i / cols][i % cols] +=
        eigenvectors_vec[i].imag() * I;
  }

  delete[] work;
  delete[] rwork;
}
