    *iv = key_material + key_length;

    if (EVP_CIPHER_iv_length((EVP_CIPHER *)EVP_aes_128_cbc()) > 0) {
        int iv_length = EVP_CIPHER_iv_length((EVP_CIPHER *)EVP_aes_128_cbc());
