typedef struct {
    float x, y, z;
} Point;

void compute_normals(Point *points, int num_points, Point *normals) {
    for (int i = 0; i < num_points; ++i) {
        Point p0 = points[i];
        normals[i] = (Point){0.0f, 0.0f, 0.0f};
        for (int j = 0; j < num_points && j != i; ++j) {
            Point p1 = points[j];
            float length_sq = (p1.x - p0.x) * (p1.x - p0.x) +
                             (p1.y - p0.y) * (p1.y - p0.y) +
                             (p1.z - p0.z) * (p1.z - p0.z);
            if (length_sq > 0.001f) { // Small epsilon to avoid division by zero
                normals[i].x += (p1.x - p0.x) / sqrtf(length_sq);
                normals[i].y += (p1.y - p0.y) / sqrtf(length_sq);
                normals[i].z += (p1.z - p0.z) / sqrtf(length_sq);
            }
        }
    }
}

Point *generate_normals(Point *points, int num_points) {
    Point *normals = (Point *)alloca(num_points * sizeof(Point));
    compute_normals(points, num_points, normals);
    return normals;
}
