size_t readFile(const char *path, wchar_t **contents) {
    FILE *file;
    fpos_t pos;
    size_t fileSize;
    wchar_t *buffer;

    if (!(file = fopen(path, "r"))) {
        fprintf(stderr, L"Error opening file %s\n", path);
        return 0;
    }

    if (fgetpos(file, &pos) || fseek(file, 0, SEEK_END) || (fileSize = ftell(file)) < 0) {
        fprintf(stderr, L"Error determining file size\n");
        fclose(file);
        return 0;
    }

    if (!(buffer = malloc((fileSize + 1) * sizeof(wchar_t)))) {
        fprintf(stderr, L"Error allocating memory\n");
        fclose(file);
        return 0;
    }

    if (fsetpos(file, &pos) || fread(buffer, sizeof(wchar_t), fileSize, file) != fileSize) {
        fprintf(stderr, L"Error reading file\n");
        free(buffer);
        fclose(file);
        return 0;
    }

    buffer[fileSize / sizeof(wchar_t)] = L'\0';
    fclose(file);

    *contents = buffer;
    return fileSize * sizeof(wchar_t);
}
