#define ALPHABET_SIZE 256

typedef struct TrieNode {
    int count;
    struct TrieNode *children[ALPHABET_SIZE];
} TrieNode;

TrieNode* createNode() {
    TrieNode *newNode = (TrieNode *) malloc(sizeof(TrieNode));
    newNode->count = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        newNode->children[i] = NULL;
    }
    return newNode;
}

void insert(TrieNode *root, const char *str, int length) {
    if (length > 0) {
        int index = (int)str[0];
        if (root->children[index] == NULL) {
            root->children[index] = createNode();
        }
        insert(root->children[index], str + 1, length - 1);
        root->count++;
    }
}

void traverse(TrieNode *node, int *counts) {
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (node->children[i] != NULL) {
            traverse(node->children[i], counts);
            counts[node->children[i]->count]++;
        }
    }
}

int *countChars(const char *str) {
    TrieNode *root = createNode();
    int length = strlen(str);
    insert(root, str, length);

    int *counts = (int *) malloc(ALPHABET_SIZE * sizeof(int));
    memset(counts, 0, ALPHABET_SIZE * sizeof(int));
    traverse(root, counts);

    free(root);
    return counts;
