int remove_file(const char* path) {
    int ret = 0;

    if (!path) {
        return -1;
    }

    if (access(path, F_OK) == -1) {
        return -1;
    }

    if (S_ISDIR(stat(path, NULL).st_mode)) {
        free(path);
        return -1;
    }

    ret = remove(path);

    free(path);

    return ret == 0 ? 0 : -1;
