struct Camera {
  virtual Color GetPixelColor(int x, int y) = 0;
};

struct Color {
  float r, g, b;
};

struct Image {
  int width, height;
  std::vector<Color> pixels;
};

void RenderPixel(const Camera& camera, int x, int y, Image& image) {
  Color pixelColor = camera.GetPixelColor(x, y);
  image.pixels[x + y * image.width] = pixelColor;
}

void RenderImage(const Camera& camera, const Image& imageSize, Image& image) {
  image.width = imageSize.width;
  image.height = imageSize.height;
  image.pixels.resize(image.width * image.height);

  std::vector<std::future<void>> tasks;
  std::unique_ptr<std::thread_pool> threadPool(new std::thread_pool);

  for (int y = 0; y < image.height; ++y) {
    for (int x = 0; x < image.width; ++x) {
      tasks.emplace_back(threadPool->enqueue(std::bind(RenderPixel, std::ref(camera), x, y, std::ref(image))));
    }
  }

  threadPool->wait();
}
