#define MAX_FILE_NAME 256

int ask_for_new_name(char *old_name) {
    char new_name[MAX_FILE_NAME];
    int ret;
    HANDLE hDlg;

    memset(new_name, 0, MAX_FILE_NAME);

    ret = DialogBoxParam(GetModuleHandle(NULL), "ASKNAMEDLG", NULL, (DLGPROC)askNameProc, (LPARAM)old_name);

    if (ret == IDOK) {
        strcpy(old_name, new_name);
        return 1;
    }

    return 0;
}

int askNameProc(HWND hDlg, UINT message, WPARAM wParam, LPARAM lParam) {
    static char old_name[MAX_FILE_NAME];
    char new_name[MAX_FILE_NAME];
    HANDLE hFile;
    int ret = 0;

    switch (message) {
        case WM_INITDIALOG:
            SendMessage(hDlg, WM_SETTEXT, IDC_OLDNAME, (LPARAM)old_name);
            EndDialog(hDlg, IDCANCEL);
            return TRUE;

        case WM_COMMAND:
            if (LOWORD(wParam) == IDOK) {
                GetDlgItemText(hDlg, IDC_NEWNAME, new_name, MAX_FILE_NAME);
                hFile = CreateFile(new_name, 0, FILE_SHARE_READ, NULL, 0, FILE_ATTRIBUTE_NORMAL, NULL);
                if (hFile != INVALID_HANDLE_VALUE) {
                    CloseHandle(hFile);
                    MessageBox(hDlg, "A file with this name already exists. Please enter a new name.", "Error", MB_ICONERROR);
                    EndDialog(hDlg, IDCANCEL);
                    return 0;
                }
                SendMessage(hDlg, WM_CLOSE, 0, 0);
                ret = 1;
            }
            break;
    }

    return FALSE;
}

int rename_file(char *old_name) {
    char new_name[MAX_FILE_NAME];

    if (!ask_for_new_name(old_name)) {
        return 0;
    }

    if (MoveFile(old_name, new_name)) {
        return 1;
    }

    return 0;
}

int main() {
    char old_name[MAX_FILE_NAME];

    strcpy(old_name, "example.txt");

    if (rename_file(old_name)) {
        printf("File %s was renamed successfully.\n", old_name);
    } else {
        printf("Failed to rename file %s.\n", old_name);
    }

    return 0;
}
