#include <vector>
#include <random>

template <typename T>
std::vector<std::vector<T>> generate_dense_input_matrix(int rows, int cols, int batch_size) {
    std::vector<std::vector<T>> input_matrix(batch_size, std::vector<T>(rows * cols));
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, INT_MAX);

    for (size_t i = 0; i < batch_size; ++i) {
        for (size_t j = 0; j < rows * cols; ++j) {
            input_matrix[i][j] = static_cast<T>(dis(gen));
        }
    }

    return input_matrix;
}

template <typename T, class IndexType>
std::vector<std::vector<T>> generate_sparse_input_matrix(int rows, int cols, int batch_size) {
    std::vector<std::vector<std::pair<IndexType, T>>> input_matrix(batch_size);

    for (size_t i = 0; i < batch_size; ++i) {
        input_matrix[i].resize(rows * cols);
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> row_dist(0, rows - 1);
        std::uniform_int_distribution<> col_dist(0, cols - 1);
        std::uniform_int_distribution<> value_dist(0, INT_MAX);

        for (auto& entry : input_matrix[i]) {
            entry.first.first = row_dist(gen);
            entry.first.second = col_dist(gen);
            entry.second = static_cast<T>(value_dist(gen));
        }
    }

    return input_matrix;
}

template <typename T, size_t sequence_length>
std::vector<std::vector<T>> generate_sequence_input_matrix(int batch_size) {
    std::vector<std::vector<T>> input_matrix(batch_size, std::vector<T>(sequence_length));
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, INT_MAX);

    for (size_t i = 0; i < batch_size; ++i) {
        for (size_t j = 0; j < sequence_length; ++j) {
            input_matrix[i][j] = static_cast<T>(dis(gen));
        }
    }

    return input_matrix;
}
