std::vector<std::vector<double>> add_border(const std::vector<std::vector<double>>& input, double border_value) {
    size_t height = input.size();
    size_t width = input[0].size();

    std::vector<std::vector<double>> output(height, std::vector<double>(width));

    if (height == 0 || width == 0) {
        return output;
    }

    for (size_t i = 0; i < height; ++i) {
        for (size_t j = 0; j < width; ++j) {
            output[i][j] = input[i][j] + border_value;
        }
    }

    if (border_value == 0) {
        return output;
    }

    size_t half_border = border_value / 2.0;

    for (size_t i = 0; i < height; ++i) {
        std::vector<double>& row = output[i];
        size_t row_start = i < border_value ? 0 : i - half_border;
        size_t row_end = i + half_border + 1 < height ? i + half_border + 1 : height - 1;

        for (size_t j = 0; j < width; ++j) {
            size_t col_start = j < border_value ? 0 : j - half_border;
            size_t col_end = j + half_border + 1 < width ? j + half_border + 1 : width - 1;

            double sum = 0.0;
            for (size_t k = row_start; k <= row_end; ++k) {
                for (size_t l = col_start; l <= col_end; ++l) {
                    sum += input[k][l];
                }
            }
            row[j] = sum + border_value * (half_border * 2 + 1);
        }
    }

    return output;
}
