void my_asnprintf(char* buf, size_t size, const char* format, va_list args) {
  int len = vsnprintf(buf, size, format, args);
  if (len >= static_cast<int>(size)) {
    // The output would be truncated, add the necessary space and reallocate
    size_t new_size = static_cast<size_t>(len + 1);
    char* new_buf = new char[new_size];
    if (new_buf == nullptr) {
      // Handle out of memory error
      return;
    }
    vsnprintf(new_buf, new_size, format, args);
    // Use the newly allocated buffer and free the old one
    std::swap(buf, new_buf);
    delete[] new_buf;
  }
}

void format_string_with_variants(const char* format, int num_args, const std::variant<int, double>* args) {
