#include <vector>
#include <cmath>
#include <iostream>

using namespace std;

const int MAX_KERNEL_SIZE = 15; // Maximum kernel size

// Function to apply Gaussian filter using separable filter
void gaussianFilter(const int imageWidth, const int imageHeight, const int kernelWidth, const int kernelHeight, uchar imageData[][MAX_KERNEL_SIZE][MAX_KERNEL_SIZE], uchar filteredImageData[][MAX_KERNEL_SIZE][MAX_KERNEL_SIZE]) {
    // Initialize kernel values
    double kernel[MAX_KERNEL_SIZE][MAX_KERNEL_SIZE];
    generateGaussianKernel(kernelWidth / 2, kernelHeight / 2, kernel);

    // Apply horizontal filter
    for (int y = 0; y < imageHeight; y++) {
        for (int x = 0; x < imageWidth; x++) {
            double sum = 0.0;
            int kernelIndex = 0;

            for (int i = 0; i < kernelHeight; i++) {
                for (int j = 0; j < kernelWidth; j++) {
                    int x_i = x + j;
                    int y_i = y + i;

                    if (x_i >= 0 && x_i < imageWidth && y_i >= 0 && y_i < imageHeight) {
                        sum += imageData[y_i][x_i] * kernel[i][j];
                        kernelIndex++;
                    }
                }
            }

            filteredImageData[y][x] = static_cast<uchar>(sum);
        }
    }

    // Apply vertical filter
    for (int x = 0; x < imageWidth; x++) {
        for (int y = 0; y < imageHeight; y++) {
            double sum = 0.0;
            int kernelIndex = 0;

            for (int i = 0; i < kernelHeight; i++) {
                for (int j = 0; j < kernelWidth; j++) {
                    int x_i = x + j;
                    int y_i = y + i;

                    if (x_i >= 0 && x_i < imageWidth && y_i >= 0 && y_i < imageHeight) {
                        sum += filteredImageData[y_i][x_i] * kernel[i][j];
                        kernelIndex++;
                    }
                }
            }

            filteredImageData[y][x] = static_cast<uchar>(sum);
        }
    }

    // Copy the filtered image data back to the original image data
    for (int y = 0; y < imageHeight; y++) {
        for (int x = 0; x < imageWidth; x++) {
            imageData[y][x] = filteredImageData[y][x];
        }
    }
}

// Function to generate Gaussian kernel
void generateGaussianKernel(int sigmaX, int sigmaY, double kernel[][MAX_KERNEL_SIZE]) {
    const double twoPi = 2.0 * M_PI;
    const double sigmaSquaredX = pow(sigmaX, 2);
    const double sigmaSquaredY = pow(sigmaY, 2);

    for (int i = 0; i < MAX_KERNEL_SIZE; i++) {
        for (int j = 0; j < MAX_KERNEL_SIZE; j++) {
            double distX = pow(i - MAX_KERNEL_SIZE / 2, 2);
            double distY = pow(j - MAX_KERNEL_SIZE / 2, 2);

            kernel[i][j] = exp(-(distX / (2 * sigmaSquaredX) + distY / (2 * sigmaSquaredY))) / (2 * M_PI * sigmaSquaredX * sigmaSquaredY);
        }
    }
}
