    if (dx < 0 || dy < 0 || dx >= width || dy >= height) {
        return;
    }

    // calculate the destination pixel position
    int dstX = dx;
    int dstY = dy;

    // check if the blit position is inside the image
    if (sx < 0) {
        sx = 0;
        w += sx;
        dx -= sx;
    }
    if (sy < 0) {
        sy = 0;
        h += sy;
        dy -= sy;
    }
