#include <vector>
#include <unordered_map>
#include <unordered_set>

using namespace std;

struct DisjointSet {
    int parent;
    int rank;

    DisjointSet(int id) : parent(id), rank(0) {}
};

DisjointSet* findSet(int x, vector<DisjointSet>& sets) {
    if (sets[x].parent != x) {
        sets[x].parent = findSet(sets[x].parent, sets).parent;
    }
    return &sets[x];
}

void unionSet(int x, int y, vector<DisjointSet>& sets) {
    DisjointSet* setX = findSet(x, sets);
    DisjointSet* setY = findSet(y, sets);

    if (setX->rank < setY->rank) {
        sets[setX->parent].parent = setY->parent;
    } else if (setX->rank > setY->rank) {
        sets[setY->parent].parent = setX->parent;
        swap(setX->rank, setY->rank);
    } else {
        sets[setX->parent].parent = setX->parent;
        sets[setY->parent].parent = setX->parent;
        setX->rank++;
    }
}

bool areConnected(const vector<int>& vec1, const vector<int>& vec2, int n) {
    vector<DisjointSet> sets(n);

    for (int i = 0; i < vec1.size(); i++) {
        sets[vec1[i]].parent = vec1[i];
    }

    for (int i = 0; i < vec2.size(); i++) {
        DisjointSet* set = findSet(vec2[i], sets);
        if (set->parent == -1) {
            // New element, add it to the sets and consider it connected to all elements in vec1
            set->parent = 0;
            for (int j = 0; j < vec1.size(); j++) {
                unionSet(vec1[j], vec2[i], sets);
            }
            continue;
        }

        if (set->parent != 0) {
            return false;
        }
    }

    return true;
}
