#define MAX_BUFFER_SIZE 1024 // Define a maximum buffer size for reading the file

static char *read_file(const char *filename, size_t *buffer_size)
{
    FILE *file = fopen(filename, "rb");
    size_t file_size = 0;
    char *buffer = NULL;

    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    buffer = malloc(file_size + 1); // +1 for null terminator

    if (!buffer) {
        perror("Error allocating memory for buffer");
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(buffer, 1, file_size, file);
    if (bytes_read != file_size) {
        perror("Error reading file");
        free(buffer);
        fclose(file);
        return NULL;
    }

    buffer[file_size] = '\0'; // Add null terminator
    *buffer_size = file_size;

    fclose(file);
    return buffer;
}

static void update_max_value(size_t *max_value, const char *buffer, size_t buffer_size)
{
    if (buffer && buffer_size > 0) {
        *max_value += buffer_size;
    }
}

static void parse_index_file(const char *filename, size_t *max_value)
{
    char *buffer = NULL;
    size_t buffer_size = 0;

    buffer = read_file(filename, &buffer_size);
    if (!buffer) {
        perror("Error reading index file");
        return;
    }

    update_max_value(max_value, buffer, buffer_size);

    free(buffer);
}

void parse_index(const char *filename, size_t *max_value)
{
    parse_index_file(filename, max_value);
