using System;

public class DisplacementFieldGenerator
{
    private static Random randomizer = new Random();

    public static double[,] GenerateDisplacementField(int width, int height, int step)
    {
        double[,] displacementField = new double[width, height];

        for (int x = 0; x < width; x += step)
        {
            for (int y = 0; y < height; y += step)
            {
                double diffx = GaussianRandom() * step;
                double diffy = GaussianRandom() * step;

                displacementField[x, y] = diffx;

                if (x + 1 < width) displacementField[x + 1, y] = diffx;
                if (y + 1 < height) displacementField[x, y + 1] = diffy;
                if (x + 1 < width && y + 1 < height) displacementField[x + 1, y + 1] = diffy;
            }
        }

        return displacementField;
    }

    private static double GaussianRandom()
    {
        double u1 = 1.0 - randomizer.NextDouble();
        double u2 = 1.0 - randomizer.NextDouble();
        double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2);
        return randStdNormal;
    }
}
