public static string AddAndStartSite(string directoryPath, string siteName)
{
    string webConfigPath = Path.Combine(directoryPath, "web.config");

    if (!File.Exists(webConfigPath))
    {
        return null;
    }

    string newDirectoryPath = Path.Combine(directoryPath, siteName);
