```csharp using System;
using System.Text;
using System.Security.Cryptography;

public static string DecryptBase64Message(string base64EncodedMessage, byte[] key, byte[] iv)
{
    // Decode base64-encoded message
    byte[] decodedMessageBytes = Convert.FromBase64String(base64EncodedMessage);

    // Create Triple DES algorithm
    using (TripleDESCryptoServiceProvider tripleDES = new TripleDESCryptoServiceProvider())
    {
        // Set the key and IV
        tripleDES.Key = key;
        tripleDES.IV = iv;

        // Create a memory stream for decryption
        using (MemoryStream msDecrypt = new MemoryStream(decodedMessageBytes))
        {
            // Create a CryptoStream for decryption
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, tripleDES.CreateDecryptor(), CryptoStreamMode.Read))
            {
                // Create a memory stream to store decrypted message
                using (MemoryStream msResult = new MemoryStream())
                {
                    // Decrypt the data
                    int read;
                    byte[] buffer = new byte[4096];
                    while ((read = csDecrypt.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        msResult.Write(buffer, 0, read);
                    }

                    // Return decrypted message as string
                    return Encoding.UTF8.GetString(msResult.ToArray());
                }
            }
        }
    }
}
