using System.Xml;

public XmlDocument CreateXmlDocumentWithElementAndAttribute(string elementName, string attributeName, string attributeValue)
{
    XmlDocument document = new XmlDocument();
    document.LoadIXml(new XmlDocument()); // Clear the existing content

    XmlElement rootElement = document.DocumentElement;
    if (rootElement == null)
    {
        rootElement = document.CreateProcessingInstruction("xml", "version='1.0'");
        document.InsertBefore(rootElement, document.DocumentElement);
    }

    XmlElement newElement = document.CreateElement(elementName);
    rootElement.AppendChild(newElement);

    XmlAttribute newAttribute = document.CreateAttribute(attributeName);
    newAttribute.Value = attributeValue;
    newElement.Attributes.Append(newAttribute);

    Console.WriteLine("Element BaseURI: " + newElement.BaseURI);
    Console.WriteLine("Attribute BaseURI: " + newAttribute.BaseURI);

    return document;
}
