public byte[] ExecuteQueryToByteArray(IDbConnection dbConnection, string query, out int numRowsAffected)
{
    using (IDbCommand command = dbConnection.CreateCommand())
    {
        command.CommandText = query;
        command.CommandType = CommandType.Text;

        byte[] result = new byte[4096]; // Initialize a buffer of a reasonable size
        MemoryStream ms = new MemoryStream();

        using (IDbDataReader reader = command.ExecuteReader())
        {
            numRowsAffected = reader.RecordsAffected;

            int bytesRead;
            while (reader.Read())
            {
                using (BinaryWriter writer = new BinaryWriter(ms))
                {
                    for (int i = 0; i < reader.FieldCount; i++)
                    {
                        if (reader.IsDBNull(i))
                        {
                            writer.Write(0);
                        }
                        else
                        {
                            switch (reader.GetFieldType(i).Name)
                            {
                                case "Byte[]":
                                    writer.Write(reader.GetBytes(i));
                                    break;
                                default:
                                    writer.Write(reader.GetValue(i).ToByteArray());
                                    break;
                            }
                        }
                    }
                }

                if (ms.Position > 0)
                {
                    ms.Position = 0;
                    int bytesToRead = (int)Math.Min(ms.Length, result.Length - ms.Position);
                    bytesRead = ms.Read(result, (int)ms.Position, bytesToRead);
                    ms.Position += bytesRead;
                }
            }
        }

        return result;
    }
}

public byte[] ExecuteDatabaseQuery(IDbConnection dbConnection, string query)
{
    int numRowsAffected;
    return ExecuteQueryToByteArray(dbConnection, query, out numRowsAffected);
}
