public class ExternalCommandExecutor
{
    private const string COMMAND = "COMMAND_KEY";
    private const string CMD_LINE_DELIMITER = "|";
    private static readonly string[] SHELL_WINDOWS = new string[] { "cmd.exe" };
    private static readonly string[] SHELL_NIX = new string[] { "/bin/sh" };

    public void ExecuteCommand(string format, string keyFile)
    {
        string commandLine = string.Format(format, keyFile);

        int timeout = 60000;

        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = GetShellForOperatingSystem(),
            Arguments = $"{GetCommandForOperatingSystem()} {commandLine}",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
            WorkingDirectory = Environment.CurrentDirectory
        };

        using (Process process = new Process())
        {
            process.StartInfo = startInfo;
            process.Start();

            StringBuilder outputBuilder = new StringBuilder();
            StringBuilder errorBuilder = new StringBuilder();

            using (StreamReader outputReader = process.StandardOutput)
            {
                string line;
                while ((line = outputReader.ReadLine()) != null)
                {
                    outputBuilder.AppendLine(line);
                }
            }

            using (StreamReader errorReader = process.StandardError)
            {
                string line;
                while ((line = errorReader.ReadLine()) != null)
                {
                    errorBuilder.AppendLine(line);
                }
            }

            process.WaitForExit(timeout);

            if (!process.HasExited)
            {
                process.Kill();
            }

            string transformedResponse = TransformOutput(outputBuilder.ToString() + errorBuilder.ToString());

            Console.WriteLine($"Command Output: {transformedResponse}");
        }
    }

