public static async Task ExecuteCassandraBatch(ISession session, string keyspace, Dictionary<string, byte[]> outgoingPayload, Dictionary<string, byte[]> expectedIncomingPayload) {
    var batch = new BatchStatement();

    foreach (KeyValuePair<string, byte[]> entry in outgoingPayload) {
        var insert = new InsertIntoStatement {
            Table = new TableName(keyspace, "your_table_name"),
            Columns = new ColumnName[] { new ColumnName("column1"), new ColumnName("column2") }, // replace with your column names
            Values = new List<IValuesPlaceholder> { new ByteArrayType(entry.Value) }
        };
        batch.Add(insert);
    }

    using var command = session.Prepare(batch.ToString());
    using var result = await command.ExecuteAsync();

    if (expectedIncomingPayload == null || expectedIncomingPayload.Count != outgoingPayload.Count) {
        throw new Exception("Incoming payload is null or has a different number of elements than outgoing payload.");
    }

    for (int i = 0; i < outgoingPayload.Count; i++) {
        var key = $"column_{i + 1}"; // replace with your column name
        using var reader = result.GetColumnReader(key);

        if (reader == null) {
            throw new Exception($"Incoming payload does not contain value for key '{key}'.");
        }

        var incomingPayloadValue = await reader.NextAsync();

        if (incomingPayloadValue == null || incomingPayloadValue.Data.Length != outgoingPayload[i].Length) {
            throw new Exception($"Incoming payload for key '{key}' has a different length than outgoing payload.");
        }

        if (!ArrayEquals(outgoingPayload[i], incomingPayloadValue.Data)) {
            throw new Exception($"Incoming payload for key '{key}' does not match outgoing payload.");
        }
    }
}

private static bool ArrayEquals(byte[] x, byte[] y) {
    if (x == null || y == null) {
        return x == y;
    }

    if (x.Length != y.Length) {
        return false;
    }

    for (int i = 0; i < x.Length; i++) {
        if (x[i] != y[i]) {
            return false;
        }
    }

    return true;
}
