public static string ExpandString(string input, int randomInt)
{
    StringBuilder expandedString = new StringBuilder();
    char[] separator = new char[] { ':' };

    string[] parts = input.Split(separator, StringSplitOptions.RemoveEmptyEntries);

    for (int i = 0; i < parts.Length; i++)
    {
        if (i > 0)
        {
            expandedString.Append(":");
        }

        if (IsNumber(parts[i]))
        {
            expandedString.Append(GetExpandedNumber(int.Parse(parts[i]), randomInt));
        }
        else
        {
            expandedString.Append(parts[i]);
        }
    }

    return expandedString.ToString();
}

private static bool IsNumber(string input)
{
    bool isNumber = false;

    if (int.TryParse(input, out _))
    {
        isNumber = true;
    }

    return isNumber;
}

private static string GetExpandedNumber(int number, int randomInt)
{
    StringBuilder expandedNumber = new StringBuilder();

    if (number > 0)
    {
        expandedNumber.Append("{");
        expandedNumber.AppendFormat("{0,{1,number}}", number, GetDigitsCount(number));
        expandedNumber.Append("}");

        if (randomInt > 0 && randomInt < GetDigitsCount(number))
        {
            expandedNumber.AppendFormat(" + {0,{1,number}}", randomInt, GetDigitsCount(number));
        }
    }
    else
    {
        expandedNumber.Append("-{");
        expandedNumber.AppendFormat("{0,{1,number}}", Math.Abs(number), GetDigitsCount(Math.Abs(number)));
        expandedNumber.Append("}");

        if (randomInt < 0 && randomInt > GetDigitsCount(Math.Abs(number)))
        {
            expandedNumber.AppendFormat(" + {0,{1,number}}", Math.Abs(randomInt), GetDigitsCount(Math.Abs(number)));
        }
    }

    return expandedNumber.ToString();
}

private static int GetDigitsCount(int number)
{
    int digitsCount = 0;

    while (number > 0)
    {
        number /= 10;
        digitsCount++;
    }

    return digitsCount;
}
