using System.Threading;

public static int StartProcessWithMonitor(ProcessStartInfo processInfo, int timeout)
{
    if (!Directory.Exists("TrackingFolder")) // Check if tracking folder exists and throw exception if not
    {
        throw new InvalidOperationException("Tracking folder does not exist.");
    }

    using (Process process = new Process())
    {
        process.StartInfo = processInfo;
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;

        process.OutputDataReceived += (sender, args) =>
        {
            File.AppendAllText("TrackingFile.txt", $"{DateTime.Now}: {args.Data}\n");
        };

        process.ErrorDataReceived += (sender, args) =>
        {
            File.AppendAllText("TrackingFile.txt", $"{DateTime.Now}: {args.Data}\n");
        };

        process.Exited += (sender, args) =>
        {
            File.Delete("TrackingFile.txt");
        };

        process.Start();

        if (process.ExitCode != 0)
        {
            throw new Exception("Process failed with exit code " + process.ExitCode);
        }

        using (var cts = new CancellationTokenSource())
        {
            if (timeout > 0)
            {
                cts.CancelAfter(timeout);

                process.BeginOutputReadLine();
                process.BeginErrorReadLine();

                process.WaitOne(timeout, cts.Token);

                if (process.HasExited)
                {
                    if (process.ExitCode != 0)
                    {
                        throw new Exception("Process timed out with exit code " + process.ExitCode);
                    }
                }
                else if (cts.IsCancellationRequested)
                {
                    process.Kill();
                    File.Delete("TrackingFile.txt");
                    throw new Exception("Process timed out.");
                }
            }
        }

        process.WaitForExit();
    }

    return 0;
}
