void RotateTransform(Transform transform, Intersection.intersectionTypes intersectionType, Transform otherTransform)
{
    float currentYRotation = Mathf.Round(transform.eulerAngles.y);
    float otherYRotation = Mathf.Round(otherTransform.eulerAngles.y);

    if (intersectionType == Intersection.intersectionTypes.fourWay)
    {
        int dir = Random.Range(1, 4);
        if (dir == 1)
            transform.Rotate(0, 90, 0);
        else if (dir == 2)
            transform.Rotate(0, -90, 0);
    }
    else if (intersectionType == Intersection.intersectionTypes.threeWay)
    {
        if (currentYRotation == otherYRotation)
        {
            int dir = Random.Range(1, 3);
            if (dir == 1)
                transform.Rotate(0, 90, 0);
            else
                transform.Rotate(0, -90, 0);
        }
        else if (Mathf.Abs(currentYRotation - otherYRotation) == 90)
