using System.Collections.Generic;
using System.Threading;
using Cassandra;

public class QueryExecutor
{
    public static async Task<(byte[]? Data, string? Error)> ExecuteQuery(string query, string connectionString)
    {
        using var session = new Session(connectionString);
        using var queryPlan = session.Prepare(new SimpleStatement(query));

        using var result = await queryPlan.ExecuteAsync();

        List<Tuple<string, object>> columns = new();
        List<Dictionary<string, object>> rows = new();

        foreach (var column in result.Metadata.Columns)
        {
            columns.Add(new Tuple<string, object>(column.Name, column.Type));
        }

        using var it = result.GetIterator();

        while (it.MoveNext())
        {
            rows.Add(it.Current.ToDictionary(kvp => kvp.Key.Name, kvp => kvp.Value));
        }

        var data = columns.Select(column => new { Name = column.Item1, Type = column.Item2.Name }).ToArray();
        var jsonData = Newtonsoft.Json.JsonConvert.SerializeObject(new { columns = data, rows = rows.ToArray() });

        return (jsonData, null);
    }
}
```

