    public async Task<IActionResult> ProcessRequest(string uri, string method = "GET")
    {
        string cacheKey = $"{uri}-{method}";
        object cachedResponse = _cache.TryGetValue(cacheKey);

        if (cachedResponse != null)
        {
            return new JsonResult(cachedResponse);
        }

        HttpResponseMessage response = await _httpClient.GetAsync(uri, new HttpRequestMessage
        {
            Method = new HttpMethod(method),
            Headers = {
