public class ConfigFileUpdater
{
    private readonly XDocument _xmlDocument;

    public ConfigFileUpdater(XDocument xmlDocument)
    {
        _xmlDocument = xmlDocument;
    }

    public XDocument UpdateXmlFile(string xpathToSearchers, string newSearcherXml, string xpathToInsertAfter)
    {
        XElement newSearcher = XElement.Parse(newSearcherXml);
        XElement searchersSection = _xmlDocument.XPathSelectElement(xpathToSearchers);

        if (searchersSection != null)
        {
            XElement insertAfterElement = _xmlDocument.XPathSelectElement(xpathToInsertAfter);
            if (insertAfterElement != null)
            {
                insertAfterElement.AddAfterSelf(newSearcher);
            }
            else
            {
                searchersSection.Add(newSearcher);
            }
        }

        return _xmlDocument;
    }
}
