{
    public static XElement ExpandString(string input, XAttribute attribute)
    {
        if (input == null || attribute == null)
        {
            throw new ArgumentNullException();
        }

        XElement expandedString = new XElement("ExpandedString");
        using (var writer = expandedString.CreateWriter())
        {
            writer.WriteValue(ExpandAttribute(input, attribute));
        }

