        string ExpandAttribute(string input, XAttribute attribute)
        {
            // Check for invalid attribute names
            if (attribute.Name.StartsWith("_") && attribute.Name != "_")
            {
                throw new ArgumentException("Invalid attribute name.");
            }

            if (attribute.Name.EndsWith("__roles__"))
            {
                throw new ArgumentException("Invalid attribute name.");
            }

            if (input is string inputString && inputString.Contains("${" + attribute.Name + "}"))
            {
                return ReplaceAttributeWithValue(input, attribute);
            }

            return input;
        }

        string ReplaceAttributeWithValue(string input, XAttribute attribute)
        {
            string expandedString = string.Empty;
            using (var xmlDocument = new XDocument())
            {
                XElement root = new XElement("Root");
                xmlDocument.Add(root);

                XElement element = new XElement("Element");
