    sub clear_session {
        @filters = ();
        @named_queries = ();
        $session->{dbh}->disconnect if $session->{dbh};
        $session->{dbh} = undef;
    }

    sub get_objects {
        my ($table, $columns) = @_;

        $query = "SELECT " . join(", ", @{$columns}) . " FROM $table";

        if (@filters) {
            $query .= " WHERE ";
            foreach my $filter (@filters) {
                $query .= "$filter->{column} = '$filter->{value}' AND ";
            }
            chomp $query;
        }

        $sth = $session->{dbh}->prepare($query);
        $sth->execute;
        return $sth->fetchall_arrayref({});
