    private readonly CassandraConnection _connection;

    public CassandraFunction(string connectionString)
    {
        _connection = new CassandraConnection(connectionString);
        _connection.Open();
    }

    public void ExecuteStatement(string query, object payload, object expectedPayload)
    {
        using (var session = new Session(_connection))
        {
            IStatement statement = session.Prepare(query);
            session.Bind(statement, new Dictionary<string, object> { { "payload", payload } });
            session.Execute(statement);

            object actualPayload = session.Execute(statement).GetValue<object>("payload");
            Assert.AreEqual(expectedPayload, actualPayload);
        }

        _connection.Close();
    }
}

