    public IActionResult CreatePurchaseOrder([Bind("StoreName,WalletId,TotalAmount")] PurchaseOrderViewModel purchaseOrder)
    {
        if (string.IsNullOrEmpty(purchaseOrder.StoreName) || string.IsNullOrWhiteSpace(purchaseOrder.StoreName))
        {
            ModelState.AddModelError("StoreName", "Store name is required.");
            return View("CreatePurchaseOrder");
        }

        var store = _context.Stores.FirstOrDefault(s => s.Name.Equals(purchaseOrder.StoreName));
        if (store == null)
        {
            ModelState.AddModelError("StoreName", "Store not found.");
            return View("CreatePurchaseOrder");
        }

        if (string.IsNullOrWhiteSpace(purchaseOrder.WalletId))
        {
            ModelState.AddModelError("WalletId", "Wallet ID is required.");
            return View("CreatePurchaseOrder");
        }

        var purchaseOrderEntity = new PurchaseOrder
        {
            Store = store,
            WalletId = purchaseOrder.WalletId,
            TotalAmount = purchaseOrder.TotalAmount
        };

        _context.Add(purchaseOrderEntity);
        _context.SaveChanges();

        return RedirectToAction("Details", new { id = purchaseOrderEntity.Id });
    }
}

