using System.Diagnostics;

public static (int ExitCode, string Output) ExecuteCommandWithCallback(string command, Action<string> outputCallback = null)
{
    ProcessStartInfo processInfo = new ProcessStartInfo
    {
        FileName = "cmd.exe",
        Arguments = $"/c {command}",
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        UseShellExecute = false,
        CreateNoWindow = true,
        StandardOutputEncoding = System.Text.Encoding.UTF8,
    };

    using (Process process = new Process())
    {
        process.StartInfo = processInfo;
        process.Start();

        string output = string.Empty;
        string error = string.Empty;

        if (outputCallback != null)
        {
            process.OutputDataReceived += (sender, args) => outputCallback(args.Data);
            process.BeginOutputReadLine();
        }

        process.ErrorDataReceived += (sender, args) => error += args.Data;
        process.BeginErrorReadLine();

        process.WaitForExit();

        return (process.ExitCode, output + error);
    }
}
