            command.CommandText = commandText;
            if (commandParameters != null) command.Parameters.AddRange(commandParameters);
        }
        catch (Exception ex)
        {
            if (command != null) command.Dispose();
            if (connection != null) connection.Dispose();
            throw ex;
        }

        return command;
    }
}

