void UpdateXmlConfig(XDocument xmlDoc, string existingSectionXPath, string newSectionName, params (string name, object value)[] newProperties)
{
    XElement root = xmlDoc.Root;
    XElement existingSection = root.XPathSelectElements(existingSectionXPath).FirstOrDefault();

    if (existingSection == null)
    {
        throw new Exception("The existing section was not found.");
    }

    XElement newSection = new XElement(newSectionName,
        from prop in newProperties
        select new XElement(prop.name, prop.value));

    existingSection.AddAfterSelf(newSection);

    foreach (var prop in newProperties)
    {
        existingSection.Element(newSectionName)?.Element(prop.name)?.Value = prop.value.ToString();
    }

    xmlDoc.Save("config.xml");
}

