public static Dictionary<string, (string Key, string Value)> LoadConfigFromXml(string filePath)
{
    XDocument document = XDocument.Load(filePath);
    XElement root = document.Root;

    Dictionary<string, (string Key, string Value)> configSettings = new Dictionary<string, (string Key, string Value)>();

    foreach (XElement configElement in root.Elements())
    {
        string key = configElement.Name.LocalName;
        string value = string.Empty;

        foreach (XElement propertyElement in configElement.Elements())
        {
            if (propertyElement.Name.LocalName == "value")
            {
                value = propertyElement.Value;
                break;
            }
        }

        configSettings.Add(key, (key, value));
    }

    return configSettings;
}
