public static (int ExitCode, string Output) ExecuteProcessWithCallback(string processPath, string[] arguments, Action<string> outputCallback)
{
    if (arguments == null || arguments.Length == 0)
    {
        throw new ArgumentException("Arguments cannot be empty.");
    }

    ProcessStartInfo startInfo = new ProcessStartInfo
    {
        FileName = processPath,
        Arguments = string.Join(" ", arguments),
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        UseShellExecute = false,
        CreateNoWindow = true,
        StandardOutputEncoding = System.Text.Encoding.UTF8,
    };

    using Process process = new Process { StartInfo = startInfo };
    process.OutputDataReceived += (sender, e) => outputCallback(e.Data);
    process.ErrorDataReceived += (sender, e) => outputCallback(e.Data);

    process.Start();
    process.BeginOutputReadLine();
    process.BeginErrorReadLine();

    process.WaitForExit();

    return (process.ExitCode, process.StandardOutput.ReadToEnd());
}
