public CreateCameraSiteResult CreateCameraSite(string userName, string name, decimal latitude, decimal longitude)
{
    using (var context = new UserContext())
    {
        var user = context.Users.FirstOrDefault(u => u.Username == userName);

        if (user != null)
        {
            foreach (var site in user.CameraSites)
            {
                if (site.Name == name)
                {
                    return new CreateCameraSiteResult { Success = false, Message = "User already has a site with that name." };
