public static XmlDocument GenerateXmlFromType(Type type)
{
    XmlDocument xmlDocument = new XmlDocument();
    object[] customAttributes = type.GetCustomAttributes(true);

    XmlizedClassAttribute classAttribute = GetAttribute(customAttributes, a => a.GetType() == typeof(XmlizedClassAttribute)) as XmlizedClassAttribute;
    if (classAttribute != null)
    {
        xmlDocument.LoadXml(classAttribute.XmlTemplate);
        XmlNode defaultParent = xmlDocument.SelectSingleNode(classAttribute.DefaultPath);

        XmlizedSqlstringIDClassAttribute sqlstringIDClassAttribute = GetAttribute(customAttributes, a => a.GetType() == typeof(XmlizedSqlstringIDClassAttribute)) as XmlizedSqlstringIDClassAttribute;
