        {
            string tmpSqlStringIDXml = sqlstringIDClassAttribute.ToXml();
            XmlDocumentFragment fragment = xmlDocument.CreateDocumentFragment();
            fragment.InnerXml = tmpSqlStringIDXml;
            defaultParent.AppendChild(fragment);
        }
    }

    return xmlDocument;
}

private static Attribute GetAttribute(object[] attributes, Func<Attribute, bool> predicate)
{
    foreach (object attribute in attributes)
    {
        if (attribute is Attribute attr && predicate(attr))
        {
            return attr;
        }
    }
    return null;
}
