using System;
using System.Security.Cryptography;
using System.Text;

public static class DesEncryption
{
    private static readonly string FixedKey = "12345678"; // 8-character key for DES

    public static string Encrypt(string text)
    {
        if (string.IsNullOrEmpty(text)) return string.Empty;

        using (DESCryptoServiceProvider des = new DESCryptoServiceProvider())
        {
            des.Key = Encoding.UTF8.GetBytes(FixedKey);
            des.Mode = CipherMode.ECB;
            des.Padding = PaddingMode.Zeros;

            byte[] inputBuffer = Encoding.UTF8.GetBytes(text);
            byte[] outputBuffer = des.CreateEncryptor().TransformFinalBlock(inputBuffer, 0, inputBuffer.Length);

            return Convert.ToBase64String(outputBuffer);
        }
    }
}
