        proc.StandardInput.WriteLine("exit");
        proc.WaitForExit();

        string errorOutput = proc.StandardError.ReadToEnd();
        if (!string.IsNullOrEmpty(errorOutput))
        {
            return false;
        }

        return true;
    }
    catch
    {
        return false;
    }
    finally
    {
        proc.Close();
    }
}
