using System.Xml;

public static bool ValidateXmlDocumentAgainstSchema(string xmlString, string schemaString)
{
    XmlReaderSettings settings = new XmlReaderSettings();
    settings.ValidationType = ValidationType.Schema;

    if (!string.IsNullOrEmpty(schemaString))
    {
        using (StringReader schemaReader = new StringReader(schemaString))
        {
            settings.Schemas.Add(null, new XmlTextReader(schemaReader));
        }
    }

    using (StringReader xmlReader = new StringReader(xmlString))
    using (XmlReader xml = XmlReader.Create(xmlReader, settings))
    {
        if (xml.MoveToFirstAttribute())
        {
            return string.IsNullOrEmpty(xml.Prefix);
        }
        else
        {
            throw new InvalidOperationException("The XML document does not contain any attributes.");
        }
    }
}
