public static Process RunExternalProcess(string filePath, string arguments, bool showWindow) {
    ProcessStartInfo startInfo = new ProcessStartInfo {
        FileName = filePath,
        Arguments = arguments,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        UseShellExecute = false,
        CreateNoWindow = !showWindow
    };

    using (Process process = new Process()) {
        process.StartInfo = startInfo;
        process.Start();

        string output = "";
        string error = "";

        using (AutoResetEvent outputEvent = new AutoResetEvent(false)) {
            process.OutputDataReceived += (sender, e) => {
                output += e.Data;
                outputEvent.Set();
            };
        }

        process.BeginOutputReadLine();

        using (AutoResetEvent errorEvent = new AutoResetEvent(false)) {
            process.ErrorDataReceived += (sender, e) => {
                error += e.Data;
                errorEvent.Set();
            };
        }

        process.BeginErrorReadLine();

        process.WaitForExit();

        outputEvent.WaitOne();
        errorEvent.WaitOne();

        process.CloseMainWindow();

        return process;
    }
}
