    public static SqlCommand CreateSqlCommand(string connectionString, string commandText, bool useStoredProcedure, List<SqlParameter> parameters)
    {
        SqlConnection connection = new SqlConnection(connectionString);
        SqlCommand command = new SqlCommand();

        try
        {
            connection.Open();
            command.Connection = connection;
            command.CommandText = commandText;
            command.CommandType = useStoredProcedure ? CommandType.StoredProcedure : CommandType.Text;

            foreach (var param in parameters)
