using System.Diagnostics;
using System.Threading;

public class ProcessHelper
{
    public int RunProcess(string executablePath, string[] arguments, int timeout, TextWriter output, TextWriter error)
    {
        output?.Write("Starting process: {0} {1}", executablePath, string.Join(" ", arguments));

        Process process = new Process();
        process.StartInfo.FileName = executablePath;
        process.StartInfo.Arguments = string.Join(" ", arguments);
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;

        process.OutputDataReceived += (sender, args) => output?.Write(args.Data);
        process.ErrorDataReceived += (sender, args) => error?.Write(args.Data);

        if (timeout > 0)
        {
            CancellationTokenSource cts = new CancellationTokenSource();
            process.Start();
            process.BeginOutputReadLine();
            process.BeginErrorReadLine();

            var waitHandle = process.WaitForExit(timeout);
            if (!waitHandle.IsSignaled)
            {
                process.Kill();
                output?.Write("Process took too long to finish, killing it.");
            }

            cts.Cancel();
        }
        else
        {
            process.Start();
            process.WaitForExit();
        }

        output?.Write("Process finished with exit code: {0}", process.ExitCode);

        return process.ExitCode;
    }
}
