    if (thread_state_size >= sizeof(yr_ppc_thread_state64_t))
      address = ((yr_ppc_thread_state64_t *) thread_state)->srr0;
    is64 = true;
    break;
  }

  default:
    return;
  }

  if (should_swap)
  {
    if (is64)
      address = yr_bswap64(address);
    else
      address = yr_bswap32(address);
  }

  if (context->flags & SCAN_FLAGS_PROCESS_MEMORY)
