using ObjCRuntime;

public interface IMobileDeviceTask
{
    void BeginInvokeOnMainThread(Action action);
    Ticker CreateTicker();
}

public class MobileDeviceTask : NSObject, IMobileDeviceTask
{
    [DllImport("__Internal")]
    private static extern void NSRunLoop_Main_BeginInvokeOnMainThread(IntPtr target, IntPtr _selectedSelector, IntPtr argument);

    public void BeginInvokeOnMainThread(Action action)
    {
        Selector selector = Selector.GetHandle("invoke_action");
        IntPtr target = this.Handle;
        IntPtr argument = ObjCRuntime.Object.Handle;

        NSRunLoop.Main.BeginInvokeOnMainThread(() =>
        {
            Invoke(selector, new NSObject[] { new NSObject(action) });
        });
    }

    [Export("init")]
    public MobileDeviceTask() : base(NSObject.Alloc(typeof(MobileDeviceTask)))
    {
    }

    [Export("initWithCoder:")]
    public MobileDeviceTask(NSCoder coder) : base(NSObject.Alloc(typeof(MobileDeviceTask).Handle))
    {
    }

    public Ticker CreateTicker()
    {
        return new CADisplayLinkTicker();
    }

    private class CADisplayLinkTicker : NSObject, NSTimer
    {
        private CADisplayLink _displayLink;
        private Action _callback;

        public CADisplayLinkTicker() : base(NSObject.Alloc(typeof(CADisplayLinkTicker)))
        {
            _displayLink = new CADisplayLink(() =>
            {
                if (_callback != null)
                    _callback();
            });

            _displayLink.Add(this, NSTimeInterval.FromSeconds(1.0));
        }

        [Export("initWithCoder:")]
        public CADisplayLinkTicker(NSCoder coder) : base(NSObject.Alloc(typeof(CADisplayLinkTicker).Handle))
        {
        }

        public void Start(Action callback)
        {
            _callback = callback;
            _displayLink.Start();
        }

        public void Stop()
        {
            _displayLink.Stop();
        }

        [Export("fireDate")]
        public NSDate FireDate
        {
            get { return new NSDate(NSDate.CurrentDate.TimeSince1970 + (NSTimeInterval)1.0); }
        }

        [Export("isValid")]
        public bool IsValid
        {
            get { return _displayLink.IsValid; }
        }

        [Export("invalidate")]
        public void Invalidated()
        {
            _displayLink.Invalidate();
        }

        [Export("scheduleWithRunLoop:forMode:")]
        public void Schedule(NSRunLoop runLoop, NSString mode)
        {
            runLoop.AddTimer(this, NSTimeInterval.FromSeconds(1.0), mode);
        }

        [Export("commonInit")]
        public static void CommonInit()
        {
        }
    }
}
