public static XElement GetFirstElement(XDocument document, string xPath)
{
    XElement element = null;
    XNode node = document.Root.SelectSingleNode(xPath);

    if (node == null)
        throw new Exception("No element found with the given name.");

    element = node as XElement;

    if (document.Root.Descendants(xPath).Count() > 1)
        throw new Exception("Multiple elements found with the given name.");

    return element;
