    public List<KeyValuePair<string, string>> GetSettingsFromFile(string filePath)
    {
        List<KeyValuePair<string, string>> settings = new List<KeyValuePair<string, string>>();

        XmlDocument doc = new XmlDocument();
        doc.Load(filePath);

        XmlNode configurationNode = doc.DocumentElement.SelectSingleNode("configuration"); //$NON-NLS-1$

        if (configurationNode != null)
        {
            foreach (XmlNode node in configurationNode.ChildNodes)
            {
                if (node.NodeType == XmlNodeType.Element)
                {
                    string key = node.Name;
                    string value = string.Empty;

                    foreach (XmlAttribute attribute in node.Attributes)
                    {
                        if (attribute.Name == "name") //$NON-NLS-1$
                        {
                            key = attribute.Value;
                            break;
                        }
                    }

                    value = node.InnerText;
                    settings.Add(new KeyValuePair<string, string>(key, value));
                }
            }
        }

        return settings;
    }
