using System.Threading.Tasks;

public class Program
{
    public static void Main(string[] args)
    {
        try
        {
            Process process = new Process();
            string fileName = "cmd.exe";
            string arguments = "/c dir"; // Example command
            string workingDir = @"C:\";

            process.StartInfo.FileName = fileName;
            process.StartInfo.Arguments = arguments;
            process.StartInfo.WorkingDirectory = workingDir;
            process.StartInfo.UseShellExecute = false;
            process.StartInfo.RedirectStandardOutput = true;
            process.StartInfo.RedirectStandardError = true;
            process.StartInfo.CreateNoWindow = true;
            process.StartInfo.WindowStyle = ProcessWindowStyle.Minimized;

            process.Start();

            Task<string> outputReader = process.StandardOutput.ReadToEndAsync();
            Task<string> errorReader = process.StandardError.ReadToEndAsync();
            Task processWaiter = Task.Run(() => process.WaitForExit());

            Task.WaitAll(processWaiter, outputReader, errorReader);

            string output = outputReader.Result;
            string error = errorReader.Result;
            int exitCode = process.ExitCode;

            if (exitCode != 0)
            {
                throw new Exception($"Process exited with code {exitCode}. Error: {error}");
            }

            Console.WriteLine("Process Output: " + output);
        }
        catch (Exception ex)
        {
            Console.WriteLine("Error: " + ex.Message);
        }
    }
}
