public void CopyFiles(string sourceDirectory, string targetDirectory, params string[] includeExtensions)
{
    Directory.CreateDirectory(targetDirectory); // create target directory if not exists

    string[] files = Directory.GetFiles(sourceDirectory, "*" + string.Join(";*", includeExtensions) + "*, all"); // get files with specified extensions

    foreach (string filePath in files)
    {
        string fileName = Path.GetFileName(filePath);
        string sourceFile = Path.Combine(sourceDirectory, fileName);
        string targetFile = Path.Combine(targetDirectory, fileName);

        Process.Start("xcopy", $"/Y {sourceFile} {targetFile}"); // copy file using xcopy command
    }

    string[] directories = Directory.GetDirectories(sourceDirectory); // get directories in source directory

    foreach (string dirPath in directories)
    {
        string dirName = Path.GetFileName(dirPath);
        string sourceDir = Path.Combine(sourceDirectory, dirName);
        string targetDir = Path.Combine(targetDirectory, dirName);

        CopyFiles(sourceDir, targetDir, includeExtensions); // recursively copy subdirectories
    }
}

public void ExcludeFiles(string sourceDirectory, string targetDirectory, params string[] excludeExtensions)
{
    CopyFiles(sourceDirectory, targetDirectory); // copy all files first

    string[] files = Directory.GetFiles(targetDirectory);

    foreach (string filePath in files)
    {
        string fileName = Path.GetFileName(filePath);
        string fileExtension = Path.GetExtension(filePath);

        if (excludeExtensions.Contains(fileExtension)) // exclude files with specified extensions
        {
            File.Delete(filePath);
        }
    }
