{
    if (string.IsNullOrEmpty(cmd))
        throw new ArgumentNullException(nameof(cmd));

    ProcessStartInfo startInfo = new ProcessStartInfo
    {
        FileName = "cmd.exe",
        Arguments = $"/c {cmd}",
        RedirectStandardInput = true,
        RedirectStandardOutput = true,
        RedirectStandardError = true,
        UseShellExecute = false,
        CreateNoWindow = true,
        StandardOutputEncoding = System.Text.Encoding.UTF8,
    };

    using (Process process = new Process())
    {
        process.StartInfo = startInfo;
        process.Start();

        if (logger != null)
        {
            process.OutputDataReceived += (sender, args) => logger.Write(args.Data);
            process.ErrorDataReceived += (sender, args) => logger.Write(args.Data);
        }

        process.BeginOutputReadLine();
        process.BeginErrorReadLine();

        string input = null;
        if (RedirectInput(process, ref input))
        {
            process.WaitForExit();
            return (process.ExitCode, process.StandardOutput.ReadToEnd(), process.StandardError.ReadToEnd());
        }

        process.StandardInput.WriteLine(input);
        process.StandardInput.Close();

        while (!process.HasExited)
            Thread.Sleep(100);

        return (process.ExitCode, process.StandardOutput.ReadToEnd(), process.StandardError.ReadToEnd());
    }

    bool RedirectInput(Process process, ref string input)
    {
        if (string.IsNullOrEmpty(cmd) || cmd.StartsWith("&"))
            return false;

        string[] args = cmd.Split(' ');
        if (args.Length > 0 && (args[0] == "/k" || args[0] == "/c"))
        {
            input = string.Join(" ", args.Skip(1).Take(args.Length - 1).ToArray());
            return true;
        }

        return false;
    }
}
