            {
                string output = string.Empty;
                string error = string.Empty;

                using (StreamReader readerOutput = process.StandardOutput.BaseStream.OpenText())
                {
                    output = readerOutput.ReadToEnd();
                }

                using (StreamReader readerError = process.StandardError.BaseStream.OpenText())
                {
                    error = readerError.ReadToEnd();
                }

                if (!string.IsNullOrEmpty(output))
                {
                    Console.WriteLine($"Output: {output}");
                }

                if (!string.IsNullOrEmpty(error))
                {
                    Console.WriteLine($"Error: {error}");
                }

                process.WaitForExit();
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred while executing the external process: {ex.Message}");
        }
    }

    static void CallRemoteService()
    {
