                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"An error occurred while calling the remote service: {ex.Message}");
                    }

                    if (retryCount > 1)
                    {
                        Console.WriteLine($"Retrying in {delayMilliseconds}ms...");
                        Thread.Sleep(delayMilliseconds);
                    }

                    retryCount--;
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred while calling the remote service: {ex.Message}");
        }
    }
}
