public static void RedirectProcessOutput(Stream outputStream, Stream errorStream, string processCommand)
{
    using (Process process = new Process())
    {
        process.StartInfo.FileName = "cmd.exe"; // or your preferred executable
        process.StartInfo.Arguments = "/c " + processCommand;
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;

        process.OutputDataReceived += (sender, args) =>
        {
            if (outputStream != null)
            {
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(args.Data);
                outputStream.Write(buffer, 0, buffer.Length);
            }
        };

        process.ErrorDataReceived += (sender, args) =>
        {
            if (errorStream != null)
            {
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(args.Data);
                errorStream.Write(buffer, 0, buffer.Length);
            }
        };

        process.Start();
        process.BeginOutputReadLine();
        process.BeginErrorReadLine();

        process.WaitForExit();
    }
}
