using System.Runtime.Serialization.Formatters.Binary;

public class SerializationHelper<T>
{
    public void SerializeToFile(T obj, string filePath)
    {
        using (FileStream file = File.Open(filePath, FileMode.Create))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            formatter.Serialize(file, obj);
        }
    }

    public T DeserializeFromFile<U>(Type type, string filePath) where U : new()
    {
        if (!File.Exists(filePath)) return default(T);

        using (FileStream file = File.Open(filePath, FileMode.Open))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            object obj = formatter.Deserialize(file);
            return (T)(object)Convert.ChangeType(obj, typeof(T));
        }
    }
}
