using System.Security.Cryptography;
using System.Text;

public static string EncryptStringSymmetric(string input, string key)
{
    byte[] encryptionKey;
    byte[] initializationVector;

    using (MD5 md5Algorithm = MD5.Create())
    {
        encryptionKey = md5Algorithm.ComputeHash(Encoding.UTF8.GetBytes(key));
        initializationVector = md5Algorithm.ComputeHash(Encoding.UTF8.GetBytes(key));
        md5Algorithm.Clear(); // Clear the MD5 cache
    }

    using (Aes aes = Aes.Create())
    {
        aes.Key = encryptionKey;
        aes.IV = initializationVector;

        ICryptoTransform encryptor = aes.CreateEncryptor();

        using (MemoryStream memoryStream = new MemoryStream())
        {
            using (CryptoStream cryptoStream = new CryptoStream(memoryStream, encryptor, CryptoStreamMode.Write))
            {
                using (StreamWriter streamWriter = new StreamWriter(cryptoStream))
                {
                    streamWriter.Write(input, 0, input.Length);
                }

                cryptoStream.FlushFinalBlock();

                byte[] encryptedData = memoryStream.ToArray();
                memoryStream.Close();

                return Convert.ToBase64String(encryptedData);
            }
        }
    }
}
