using System;
using System.Security.Cryptography;
using System.Text;

public static class TripleDesEncryption
{
    public static string Encrypt(string text, Guid key1, Guid key2)
    {
        if (string.IsNullOrEmpty(text)) return string.Empty;

        byte[] keyBytes = CombineGuidsToKey(key1, key2);
        byte[] iv = new byte[8]; // Initialization vector (IV) for TripleDES

        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = keyBytes;
            tdes.IV = iv;
            tdes.Mode = CipherMode.CBC;
            tdes.Padding = PaddingMode.PKCS7;

            byte[] textBytes = Encoding.UTF8.GetBytes(text);
            using (ICryptoTransform encryptor = tdes.CreateEncryptor())
            {
                byte[] encryptedBytes = encryptor.TransformFinalBlock(textBytes, 0, textBytes.Length);
                return Convert.ToBase64String(encryptedBytes);
            }
        }
    }

    private static byte[] CombineGuidsToKey(Guid guid1, Guid guid2)
    {
        byte[] guid1Bytes = guid1.ToByteArray();
        byte[] guid2Bytes = guid2.ToByteArray();
        byte[] combined = new byte[24];

        Buffer.BlockCopy(guid1Bytes, 0, combined, 0, 16);
        Buffer.BlockCopy(guid2Bytes, 0, combined, 16, 8);

        return combined;
    }
}
