using System.IO;
using System.Linq;
using System.Xml.Linq;
using System.Xml.XPath;

public class ConfigFileUpdater
{
    private XDocument _xmlDocument;

    public ConfigFileUpdater(XDocument xmlDocument)
    {
        _xmlDocument = xmlDocument;
    }

    public int RemoveSection(string xpath)
    {
        var elementsToRemove = _xmlDocument.XPathSelectElements(xpath).ToList();
        int count = elementsToRemove.Count;

        foreach (var element in elementsToRemove)
        {
            element.Remove();
        }

        return count;
    }

    public void Save(string path)
    {
        _xmlDocument.Save(path);
    }
}

public class ConfigFileHandler
{
    public static int UpdateConfigFile(string filePath, string xpath)
    {
        XDocument xmlFile = XDocument.Load(filePath);
        ConfigFileUpdater updater = new ConfigFileUpdater(xmlFile);

        int elementsRemoved = updater.RemoveSection(xpath);
        updater.Save(filePath);

        return elementsRemoved;
    }
}
