public static class SimpleHashCalculator
{
    private static readonly HashAlgorithm[] SupportedAlgorithms = new[] { new SHA1Algorithm(), new SHA256Algorithm(), new MD5Algorithm() };

    private SimpleHashCalculator(string algorithmName)
    {
        AlgorithmName = algorithmName;
        Algorithm = GetHashAlgorithm(algorithmName);
    }

    public string AlgorithmName { get; }
    public HashAlgorithm Algorithm { get; }

    public static SimpleHashCalculator Sha1()
    {
        return new SimpleHashCalculator("SHA1");
    }

    public static SimpleHashCalculator Sha256()
    {
        return new SimpleHashCalculator("SHA256");
    }

    public static SimpleHashCalculator Md5()
    {
        return new SimpleHashCalculator("MD5");
    }

    public byte[] CalculateHash(string input)
    {
        using var inputBytes = Encoding.UTF8.GetBytes(input);
        return Algorithm.ComputeHash(inputBytes);
    }

    private static HashAlgorithm GetHashAlgorithm(string algorithmName)
    {
        foreach (var algorithm in SupportedAlgorithms)
        {
            if (algorithm.GetType().Name.ToLower() == algorithmName)
            {
                return algorithm;
            }
        }

        throw new ArgumentException($"Unsupported hash algorithm: {algorithmName}");
    }
}
