public static string Decrypt(string cipherText, string key)
{
    try
    {
        key = key.PadRight(8, ' ').Substring(0, 8);
        byte[] keyBytes = Encoding.UTF8.GetBytes(key);
        byte[] cipherBytes = Convert.FromBase64String(cipherText);

