private static XmlNode GetParameterDocumentation(XmlReader xmlReader, string parameterName)
{
    try
    {
        // Create XML reader
        XmlReaderSettings settings = new XmlReaderSettings();
        settings.ProhibitDtd = true;
        settings.IgnoreProcessingInstructions = true;
        XmlReader xml = XmlReader.Create(xmlReader, settings);

        // Go to the method node
        xml.ReadToDescendant("method");

        // Go to the first parameter node
        xml.MoveToFirstChild();
        while (xml.NodeType != XmlNodeType.Element)
        {
            xml.Read();
        }

        XmlNode currentNode = xml;
        while (currentNode != null && currentNode.Name != "param")
        {
            xml.Read();
            currentNode = xml.ReadSubtree();
        }

        // Check if the current node is the parameter node with the given name
        if (currentNode != null && currentNode.Attributes["name"]?.Value == parameterName)
        {
            return currentNode;
        }

        // Parameter not found
        return null;
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error retrieving documentation for parameter '{parameterName}': {ex.Message}");
        return null;
    }
}
