    {
        throw new ArgumentException("cookiesFilePath cannot be null or empty.");
    }

    using (BinaryWriter writer = new BinaryWriter(File.OpenWrite(cookiesFilePath)))
    {
        // Write the number of cookies
        writer.Write(cookies.Count);

        // Write each cookie's key-value pairs
        foreach (String key in cookies.AllKeys)
        {
            byte[] keyBytes = Encoding.UTF8.GetBytes(key);
            byte[] valueBytes = Encoding.UTF8.GetBytes(cookies[key].Value);
            writer.Write(keyBytes.Length);
            writer.Write(keyBytes, 0, keyBytes.Length);
            writer.Write(valueBytes.Length);
            writer.Write(valueBytes, 0, valueBytes.Length);
        }
    }
