								NamedNodeMap optionAttrs = child.getAttributes();
								Node id = optionAttrs.getNamedItem("id"); //$NON-NLS-1$
								Node value = optionAttrs.getNamedItem("value"); //$NON-NLS-1$
								if (id != null && value != null)
