using System;
using System.Security.Cryptography;
using System.Text;

public class SymmetricEncryptionTest
{
    public static void TestEncryptionDecryption(SymmetricAlgorithm algorithm, byte[] key, string plaintext)
    {
        // Check key size
        if (key.Length * 8 != algorithm.KeySize)
        {
            throw new ArgumentException("Key size does not match the algorithm's expected key size.");
        }

        // Check effective key size
        if (algorithm.LegalKeySizes != null)
        {
            bool validKeySize = false;
            foreach (var keySize in algorithm.LegalKeySizes)
            {
                if (key.Length * 8 >= keySize.MinSize && key.Length * 8 <= keySize.MaxSize)
                {
                    validKeySize = true;
                    break;
                }
            }
            if (!validKeySize)
            {
                throw new ArgumentException("Key size is not within the valid range for the algorithm.");
            }
        }

        // Check block size
        if (plaintext.Length % (algorithm.BlockSize / 8) != 0)
        {
            throw new ArgumentException("Plaintext length is not a multiple of the block size.");
        }

        // Set key and mode
        algorithm.Key = key;
        algorithm.Mode = CipherMode.ECB;
        algorithm.Padding = PaddingMode.Zeros;

        // Create encryptor and decryptor
        ICryptoTransform encryptor = algorithm.CreateEncryptor();
        ICryptoTransform decryptor = algorithm.CreateDecryptor();

        // Encrypt the plaintext
        byte[] plaintextBytes = Encoding.UTF8.GetBytes(plaintext);
        byte[] encryptedBytes = encryptor.TransformFinalBlock(plaintextBytes, 0, plaintextBytes.Length);

        // Decrypt the ciphertext
        byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

        // Convert decrypted bytes back to string
        string decryptedText = Encoding.UTF8.GetString(decryptedBytes);

        // Check if decrypted text matches original plaintext
        if (decryptedText != plaintext)
        {
            throw new Exception("Decrypted text does not match the original plaintext.");
        }

        // Check if encrypted message is the same as the original plaintext message
        if (Encoding.UTF8.GetString(encryptedBytes) == plaintext)
        {
            throw new Exception("Encrypted message is the same as the original plaintext message.");
        }
    }
}
