import java.util.*;
import java.util.Random;

public class GaussianMutation {

    private final int low;
    private final int high;

    public GaussianMutation(int low, int high) {
        this.low = low;
        this.high = high;
    }

    public double mutatedValue(Random rng, double value, float stdDevFactor) {
        double r = rng.nextGaussian() * ((high - low) * stdDevFactor);
        return Math.min(Math.max(this.low, value + r), this.high);
    }

    public List<Double> getDiscreteValues() {
        List<Double> values = new LinkedList<>();
        for (int i = this.low; i <= this.high; i++) {
            values.add((double) i);
        }
        return values;
    }
}
