import java.security.SecureRandom;
import java.util.Random;

public static String generatePassword(int length, int restrictionLength) {
    if (length <= 0 || restrictionLength < 0 || length - restrictionLength < 0) {
        throw new IllegalArgumentException("Invalid password length or restriction length.");
    }

    char[] password = new char[length];
    SecureRandom random = new SecureRandom();

    for (int i = 0; i < length - restrictionLength; i++) {
        password[i] = (char) (random.nextInt(94) + 33); // ASCII printable characters
    }

    Random rand = new Random();
    for (int i = length - restrictionLength; i < length; i++) {
        int randomIndex;
        char restrictedChar;

        do {
            randomIndex = rand.nextInt(26); // Only last 'restrictionLength' characters have restrictions
            restrictedChar = (char) ('a' + randomIndex);
        } while (password[i - restrictionLength] == restrictedChar);

        password[i] = restrictedChar;
    }

    return new String(password);
