public void compareNumericFields(String indexPath, String docId1, String docId2, String fieldName) throws IOException {
    IndexReader reader = IndexReader.open(FSDirectory.open(new File(indexPath)), true);
    Document doc1 = reader.document(Integer.parseInt(docId1));
    Document doc2 = reader.document(Integer.parseInt(docId2));

