    MatcherAssert.assertThat(doc2.getFields(), Is.notNullValue());

    Field field1 = doc1.getField(fieldName);
    Field field2 = doc2.getField(fieldName);

    MatcherAssert.assertThat(field1, IsInstanceOf(NumericDocValuesField.class));
    MatcherAssert.assertThat(field2, IsInstanceOf(NumericDocValuesField.class));

    MatcherAssert.assertThat(field1.numValues(), Is.is(field2.numValues()));

    NumericDocValuesField numericField1 = (NumericDocValuesField) field1;
    NumericDocValuesField numericField2 = (NumericDocValuesField) field2;

    for (int i = 0; i < numericField1.numValues(); i++) {
        double value1 = numericField1.doubleValue(i);
        double value2 = numericField2.doubleValue(i);

        MatcherAssert.assertThat(value1, Is.closeTo(value2, 0.001)); // adjust tolerance as needed
    }
}
