    public static void movePair(List<Pair> pairs, double percentage) {
        int processedPairs = 0;
        int listSize = pairs.size();

        for (int i = listSize - 1; i >= 0 && processedPairs < percentage * listSize; i--) {
            Pair currentPair = pairs.get(i);
            Pair previousPair;

            if (i == 0) {
                printMessage("Last pair: (" + currentPair.randomInt + ", " + currentPair.booleanValue + ")");
            } else {
                previousPair = pairs.get(random.nextInt(i));
