import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.FSDataOutputStream;
import org.apache.hadoop.fs.Path;

import java.io.IOException;
import java.util.Random;

public class RandomBinaryDataWriter {

    public static FileStateHandle generateAndWriteRandomBinaryData(FileSystem fs, Path folder, String fileName, int length) throws IOException {
        final Random rnd = new Random();
        final byte[] data = new byte[length];
        rnd.nextBytes(data); // Fill the array with random bytes

        final FileStateHandle handle;
        try (FSDataOutputStream stream = fs.create(new Path(folder, fileName))) {
            for (int i = 0; i < data.length; ) {
                if (rnd.nextBoolean()) {
                    stream.write(data[i++]);
                } else {
                    int len = rnd.nextInt(Math.min(data.length - i, 32));
                    stream.write(data, i, len);
                    i += len;
                }
            }
            handle = closeAndGetResult(stream);
        }
        return handle;
    }

    private static FileStateHandle closeAndGetResult(FSDataOutputStream stream) throws IOException {
        stream.close();
        return new FileStateHandle(stream.getPos(), stream.getWrappedStream().getPos());
    }

    static class FileStateHandle {
        private final long pos;
        private final long wrappedPos;

        public FileStateHandle(long pos, long wrappedPos) {
            this.pos = pos;
            this.wrappedPos = wrappedPos;
        }

        public long getPos() {
            return pos;
        }

        public long getWrappedPos() {
            return wrappedPos;
        }
    }
}
