import java.util.Function;

public class ArrayTransformer {

    public static <T, U> U[] transformArray(T[] inputArray, Function<T, U> method) {
        if (inputArray == null || inputArray.length == 0) {
            return new U[0];
        }

        U[] outputArray = (U[]) new Object[inputArray.length];

        for (int i = 0; i < inputArray.length; i++) {
            outputArray[i] = method.apply(inputArray[i]);
        }

        return outputArray;
