public static byte[] generateAESKeyAndPerformEncDec(String password, byte[] salt, byte[] data, boolean encrypt) throws Exception {
    byte[] key = new byte[AES_BLOCK_SIZE];
    SecretKeyFactory factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA1");
    PBEKeySpec spec = new PBEKeySpec(password.toCharArray(), salt, 10000, AES_BLOCK_SIZE * 8);
    SecretKey tmp = factory.generateSecret(spec);
    key = tmp.getEncoded();

    Cipher cipher = Cipher.getInstance("AES/CBC/NoPadding");
    IvParameterSpec iv = new IvParameterSpec(new byte[AES_BLOCK_SIZE]);

    byte[] encryptedData = null;
    byte[] decryptedData = null;

    cipher.init(encrypt ? Cipher.ENCRYPT_MODE : Cipher.DECRYPT_MODE, new SecretKeySpec(key, "AES"), iv);

    if (encrypt) {
        byte[] encrypted = cipher.doFinal(data);
        encryptedData = new byte[data.length + AES_BLOCK_SIZE];
        System.arraycopy(data, 0, encryptedData, 0, data.length);
        System.arraycopy(encrypted, 0, encryptedData, data.length, encrypted.length);
    } else {
        decryptedData = cipher.doFinal(data);
    }

    return encrypt ? encryptedData : decryptedData;
}
