private Bitmap themeBitmap;
private String defaultThemeDirectory;

public void manageThemeCache() {
    if (themeBitmap != null && !themeBitmap.isRecycled()) {
        themeBitmap.recycle();
        themeBitmap = null;
    }

    if (defaultThemeDirectory == null) {
        defaultThemeDirectory = "default_theme_directory";
    }

    File cacheDir = initCacheDir();
    if (cacheDir == null) {
        return;
    }

    File themeFile = new File(cacheDir, "theme.png");
    if (!themeFile.exists()) {
        InputStream inputStream = getResources().openRawResource(R.raw.theme); // Replace R.raw.theme with the actual resource ID
        BitmapFactory.Options options = new BitmapFactory.Options();
        options.inJustDecodeBounds = false;
        themeBitmap = BitmapFactory.decodeStream(inputStream, null, options);
        inputStream.close();

        FileOutputStream outputStream = new FileOutputStream(themeFile);
        themeBitmap.compress(Bitmap.CompressFormat.PNG, 100, outputStream);
        outputStream.close();
    }
}

