import org.apache.lucene.index.LeafReaderContext;
import org.apache.lucene.index.SortedBinaryDocValues;
import org.apache.lucene.util.BytesRef;
import org.apache.lucene.util.BytesRefBuilder;
import org.elasticsearch.index.fielddata.IndexFieldData;
import org.elasticsearch.index.fielddata.AtomicFieldData;

import java.util.Random;

public class FieldDataComparator {

    public static SortedBinaryDocValues compareFieldData(Random random, LeafReaderContext context, IndexFieldData<?> fieldData1, IndexFieldData<?> fieldData2, Preprocessor pre) throws Exception {
        AtomicFieldData data1 = random.nextBoolean() ? fieldData1.load(context) : fieldData1.loadDirect(context);
        AtomicFieldData data2 = random.nextBoolean() ? fieldData2.load(context) : fieldData2.loadDirect(context);

        SortedBinaryDocValues values1 = data1.getBytesValues();
        SortedBinaryDocValues values2 = data2.getBytesValues();
        BytesRefBuilder spare1 = new BytesRefBuilder();
        BytesRefBuilder spare2 = new BytesRefBuilder();

        int numDocs = context.reader().maxDoc();
        for (int i = 0; i < numDocs; i++) {
            values1.setDocument(i);
            values2.setDocument(i);
            int numValues = values1.count();
            assert numValues == values2.count();

            for (int j = 0; j < numValues; j++) {
                spare1.copyBytes(values1.valueAt(j));
                spare2.copyBytes(values2.valueAt(j));
                BytesRef value1 = spare1.get();
                BytesRef value2 = spare2.get();

                int comparison = pre.compare(value1, value2);
                if (comparison != 0) {
                    return comparison < 0 ? values1 : values2;
                }
            }
        }

        return values1;
    }
}
