import java.util.ArrayList;
import java.util.List;
import java.util.AtomicInteger;

class GraphNode {
    int id;
    List<GraphNode> neighbors;

    GraphNode(int id) {
        this.id = id;
        this.neighbors = new ArrayList<>();
    }
}

class Graph {
    List<GraphNode> nodes;

    Graph() {
        this.nodes = new ArrayList<>();
    }

    void addNode(GraphNode node) {
        this.nodes.add(node);
    }
}

class GraphTraversalThread extends Thread {
    private final AtomicInteger vertices = new AtomicInteger();
    private final AtomicInteger edges = new AtomicInteger();
    private final AtomicInteger threads = new AtomicInteger();
    private final Graph graph;
    private final int startNodeId;

    GraphTraversalThread(Graph graph, int startNodeId) {
        this.graph = graph;
        this.startNodeId = startNodeId;
    }

    @Override
    public void run() {
        GraphNode startNode = graph.nodes.get(startNodeId);
        dfs(startNode);

        threads.incrementAndGet();
    }

    private void dfs(GraphNode node) {
        if (node == null) return;

        vertices.incrementAndGet();
        int currentNodeId = node.id;

        for (GraphNode neighbor : node.neighbors) {
            edges.incrementAndGet();
            GraphTraversalThread neighborThread = new GraphTraversalThread(graph, neighbor.id);
            neighborThread.start();
            dfs(neighbor);
        }
    }
}

public class Main {
