import java.io.IOException;
import java.net.Socket;
import java.util.concurrent.locks.ReentrantLock;

public class ServiceStarter {
    private int port;
    private boolean serviceRunning;
    private Socket socket;
    private ReentrantLock lock;

    public ServiceStarter(int port) {
        this.port = port;
        this.serviceRunning = false;
        this.socket = null;
        this.lock = new ReentrantLock();
    }

    public void startService() {
        this.serviceRunning = true;

        try {
            this.socket = new Socket("localhost", this.port);
            this.socket.setBlocking(false); // make socket non-blocking
            this.socket.setKeepAlive(true);
            this.socket.setTcpNoDelay(true);

            if (this.socket.isConnected()) {
                this.lock.lock();
                try {
                    // Notify any waiting threads that the service is now ready
                    this.lock.notifyAll();
                } finally {
                    this.lock.unlock();
                }
            }
        } catch (IOException e) {
            System.err.println("Error starting service on port " + this.port + ": " + e.getMessage());
        }
    }

    public boolean isServiceRunning() {
        return this.serviceRunning;
    }

    public int getPort() {
        return this.port;
    }
}
