public ProcessRunInfo executeCommand(String command) {
    ProcessProcessBuilder processBuilder = new ProcessProcessBuilder();
    Process process;
    try {
        process = processBuilder.start(new String[] { "sh", "-c", command });
    } catch (IOException e) {
        return new ProcessReturnInfo(-1, "", "", e.getMessage());
    }

    int timeout = 60000; // 1 minute
    try {
        process.waitFor(timeout, TimeUnit.MILLISECONDS);
    } catch (InterruptedException e) {
        process.destroy();
        return new ProcessReturnInfo(-2, "", "", e.getMessage());
    }

    if (process.exitValue() != 0) {
        process.destroy();
        return new ProcessReturnInfo(process.exitValue(), "", "", "");
    }

    StringBuilder outputBuilder = new StringBuilder();
    StringBuilder errorBuilder = new StringBuilder();

    try (InputStreamReader isrOutput = new InputStreamReader(process.getInputStream());
         BufferedReader brOutput = new BufferedReader(isrOutput)) {
        String line;
        while ((line = brOutput.readLine()) != null) {
            outputBuilder.append(line).append("\n");
        }
    } catch (IOException e) {
        process.destroy();
        return new ProcessReturnInfo(process.exitValue(), "", "", e.getMessage());
    }

    try (InputStreamReader isrError = new InputStreamReader(process.getErrorStream());
         BufferedReader brError = new BufferedReader(isrError)) {
        String line;
        while ((line = brError.readLine()) != null) {
            errorBuilder.append(line).append("\n");
        }
    } catch (IOException e) {
        process.destroy();
        return new ProcessReturnInfo(process.exitValue(), "", "", e.getMessage());
    }

