    @Nonnull
    private static Object[] toJson(@Nonnull Object object, boolean isObject) {
        if (object instanceof String) {
            return new String[] { new JSONObject().put("type", "string").put("value", (String) object) .toString() };
        } else if (object instanceof Number) {
            return new String[] { new JSONObject().put("type", "number").put("value", object.toString()) .toString() };
        } else if (object instanceof Boolean) {
            return new String[] { new JSONObject().put("type", "boolean").put("value", object.toString()) .toString() };
        } else if (object instanceof Object[]) {
            JSONArray jsonArray = new JSONArray();
            for (Object element : (Object[]) object) {
                jsonArray.put(toJson(element, true)[0]);
            }
            return new String[] { jsonArray.toString() };
        } else {
            if (isObject) {
                JSONObject jsonObject = new JSONObject();
                for (Object key : object.class.getDeclaredFields()) {
                    try {
                        Field field = object.getClass().getDeclaredField((String) key);
                        field.setAccessible(true);
                        Object value = field.get(object);
                        jsonObject.put(key.toString(), toJson(value, false)[0]);
                    } catch (NoSuchFieldException | IllegalAccessException e) {
                        e.printStackTrace();
                    }
                }
                return new String[] { jsonObject.toString() };
            } else {
                throw new UnsupportedOperationException("Cannot convert array to JSON");
            }
        }
    }
}
