public static <T> HashMap<T, Double> normalizeWeights(List<WeightedItem> items, Function<WeightedItem, Double> normalizer) {
    double totalWeight = 0;
    HashMap<T, Double> normalizedItems = new HashMap<>();

    for (WeightedItem item : items) {
        double normalizedWeight = normalizer.apply(item);
        totalWeight += normalizedWeight;
        normalizedItems.put(item.item, normalizedWeight);
    }

    for (T key : normalizedItems.keySet()) {
        normalizedItems.put(key, normalizedItems.get(key) / totalWeight);
    }

    return normalizedItems;
}
