import java.util.DisjointSet;
import java.util.RandomAccessFile;

public class DisjointPairs {
    public static long countDisjointPairs(int[] arr) {
        int n = arr.length;
        DisjointSet<Integer> set = new DisjointSet<>();
        long pairCount = 0;

        for (int i = 0; i < n; i++) {
            int root = set.findSet(arr[i]);
            if (set.findSet(arr[i] + 1) != root) {
                set.union(arr[i], arr[i] + 1);
                pairCount++;
            }
        }

        return pairCount;
    }

    public static void main(String[] args) throws Exception {
        int[] arr = new int[100000];
        for (int i = 0; i < arr.length; i++) {
