import java.io.*;
import java.net.*;
import java.nio.channels.*;

public class RemoteConnection {
    private static final int CONNECTED = 1;
    private static final int DISCONNECTED = 0;
    private static final int CONNECTION_ERROR = -1;

    private String server;
    private int port;
    private String user;
    private String password;
    private SelectionKey key;
    private SocketChannel channel;

    public int connect(String server, int port, String user, String password) {
        this.server = server;
        this.port = port;
        this.user = user;
        this.password = password;

        try {
            this.channel = SocketChannel.open();
            SocketAddress address = new InetSocketAddress(server, port);
            this.key = this.channel.register(SelectionKey.OP_CONNECT, this);
            this.channel.connect(address);

            if (this.channel.isConnected()) {
                byte[] passwordBytes = this.password.getBytes();
                OutputStream output = this.channel.socket().getOutputStream();
                output.write(user.getBytes());
                output.write(0); // null terminator
                output.write(passwordBytes);
                output.flush();

                InputStream input = this.channel.socket().getInputStream();
                int response = input.read();
                if (response == -1) {
                    return CONNECTION_ERROR;
                }

                this.key.interestOps(SelectionKey.OP_READ);
                System.out.println("Connected to " + server + ":" + port);
                return CONNECTED;
            } else {
                return CONNECTION_ERROR;
            }
        } catch (IOException e) {
            System.err.println("Error connecting to " + server + ":" + port + ": " + e.getMessage());
            return CONNECTION_ERROR;
        }
    }

    public void handle(SelectionKey key) throws IOException {
        if (key.isReadable()) {
            SocketChannel channel = (SocketChannel) key.channel();
            ByteArrayOutputStream buffer = new ByteArrayOutputStream();
            int bytesRead;
            byte[] data = new byte[1024];

            while ((bytesRead = channel.read(data)) > 0) {
                buffer.write(data, 0, bytesRead);
            }

            String message = new String(buffer.toByteArray());
            System.out.println("Received message: " + message);

            // Handle the received message here

            buffer.reset();
        }
    }
}
