        this.weakActivityReference = new WeakReference<>(activity);
    }

    @Nullable private final LiveData<Activity> activityLiveData = new MutableLiveData<>();

    public void sendEmail(@NonNull String subject) {
        new Thread(() -> {
            if (weakActivityReference.get() != null) {
                Intent emailIntent = new Intent(Intent.ACTION_SENDTO, Uri.parse("mailto:"));
                emailIntent.putExtra(Intent.EXTRA_SUBJECT, subject);
                activityLiveData.postValue(weakActivityReference.get());
                weakActivityReference.get().startActivity(emailIntent);
            }
        }).start();

        new Handler(Looper.getMainLooper()).post(() -> {
            activityLiveData.setValue(activity);
        });
    }

    @NonNull public LiveData<Activity> getActivityLiveData() {
        return activityLiveData;
    }
}
