import java.io.*;

public class FileObjectReader {
    public static Object readObjectFromFile(String filePath, int objectId) throws IOException, ClassNotFoundException {
        FileInputStream inputStream = null;
        ObjectInputStream objectInputStream = null;
        Object readObject = null;

        try {
            inputStream = new FileInputStream(filePath);
            objectInputStream = new ObjectInputStream(inputStream);

            // Seek to the object's position in the file
            long filePointer = inputStream.getChannel().position();
            inputStream.seek(getObjectStartPosition(filePointer, objectInputStream));

            // Read the object
            readObject = objectInputStream.readObject();

        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            try {
                if (objectInputStream != null) {
                    objectInputStream.close();
                }
            } finally {
                try {
                    if (inputStream != null) {
                        inputStream.close();
                    }
                }
            }
        }

        return readObject;
    }

    private static long getObjectStartPosition(long filePointer, ObjectInputStream objectInputStream) throws IOException {
        long position = filePointer;
        long objectSize = 0;

        byte[] buffer = new byte[1024];

        while (objectSize == 0) {
            int bytesRead = objectInputStream.read(buffer, 0, buffer.length);

            if (bytesRead < 0) {
                throw new IOException("Failed to read object size from file.");
            }

            byte[] sizeBytes = new byte[4];
            System.arraycopy(buffer, bytesRead - 4, sizeBytes, 0, 4);
            objectSize = ByteBuffer.wrap(sizeBytes).getLong();

            position += bytesRead + objectSize;
        }

        return position;
    }
}
