    public static List<SensorData> generateSensorData(List<LocationTime> locationTimes, List<double[]> stdDeviations, double stepPerSecond) {
        List<SensorData> sensorDataList = new ArrayList<>();
        Random random = new Random();

        for (LocationTime locationTime : locationTimes) {
