    private static double generateRandomAccelerometerReading(double standardDeviation, double stepPerSecond) {
        double mean = 0.0;
        double accelerationRange = 5.0; // Maximum acceleration range

        double randomValue = random.nextGaussian() * standardDeviation + mean;
        double acceleration = randomValue * stepPerSecond;

        if (Math.abs(acceleration) > accelerationRange) {
            randomValue = Math.signum(randomValue) * accelerationRange;
            randomValue += new Random().nextDouble() * standardDeviation * 2 - standardDeviation;
            acceleration = randomValue * stepPerSecond;
        }

        return acceleration;
    }
}

