public class KerberosDelegationToken {

    public static boolean getDelegationToken(String kerberosRealm, String userPrincipal, String serverPrincipal, int port) {
        boolean hasToken = false;
        try {
            KerberosContext initialContext = new KerberosContext();
            initialContext.setUseInitialContext(true);
            initialContext.init();

            KerberosPrincipal userPrincipal = new KerberosPrincipal(userPrincipal);
            KerberosPrincipal serverPrincipal = new KerberosPrincipal(serverPrincipal);

            PrivilegedExceptionAction<Void> action = () -> {
                KerberosContext delegationContext = initialContext.getDelegationContext(userPrincipal, new String[]{serverPrincipal.getName()}, new String[]{"/host/*"}, new String[]{"rcp"}, null, KerberosFlag.INIT_USE_TGT_ONLY);
                if (delegationContext != null) {
                    Ticket ticket = delegationContext.getTicket(serverPrincipal);
                    if (ticket != null && ticket.getFlags().contains(TicketFlag.FORWARD_RELIABLE)) {
