import java.security.MessageDigest;

public String hashAndFormatDateInterval(String dateRange) {
    String[] parts = dateRange.split("/");
    String start = parts[0];
    String end = parts[1];

    String hashKey = start + end;
    String formattedInterval = start + "/" + end;

    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] messageDigest = md.digest(hashKey.getBytes());
        StringBuilder hashValue = new StringBuilder();
        for (byte b : messageDigest) {
            hashValue.append(String.format("%02x", b));
        }

        formattedInterval = hashValue.toString() + "/" + formattedInterval;
    } catch (Exception e) {
        e.printStackTrace();
    }

    return formattedInterval;
}
