public byte[] md5MD2Hash(byte[] inputData) throws NoSuchAlgorithmException, InvalidKeyException {
    byte[] md5Hash = new byte[16];
    byte[] md2Hash = new byte[16];

    Mac md5Hmac = Mac.getInstance("MD5");
    SecretKeySpec md5Key = new SecretKeySpec(Arrays.copyOfRange(inputData, 0, 16), "HmacMD5");
    md5Hmac.init(md5Key);
    md5Hmac.doFinal(md5Hash, 0);

    Mac md2Hmac = Mac.getInstance("MD2");
    SecretKeySpec md2Key = new SecretKeySpec(Arrays.copyOfRange(inputData, 0, 16), "HmacMD2");
    md2Hmac.init(md2Key);
    md2Hmac.doFinal(md2Hash, 0);

    byte[] result = new byte[32];
    System.arraycopy(md5Hash, 0, result, 0, 16);
    System.arraycopy(md2Hash, 0, result, 16, 16);

    return result;
}
