    public static URI downloadFile(String urlString, String localFilePath) {
        try {
            URL url = new URL(urlString);
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            connection.setRequestProperty("Accept-Encoding", "identity");
            connection.setConnectTimeout(5000); // Set connect timeout to 5 seconds

            int responseCode = connection.getResponseCode();
            if (responseCode != HttpURLConnection.HTTP_OK) {
                System.out.println("Download failed: response code = " + responseCode);
                return null;
            }

            InputStream inputStream = connection.getInputStream();
            OutputStream outputStream = new FileOutputStream(localFilePath);

            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                outputStream.write(buffer, 0, bytesRead);
            }

            outputStream.close();
            inputStream.close();
            connection.disconnect();

            System.out.println("Download completed: " + localFilePath);
            return new URI(localFilePath);
        } catch (IOException | URISyntaxException e) {
            System.err.println("Error downloading file: " + e.getMessage());
            return null;
        }
    }
}
