public class CommandExecutor {
    private static final String ERROR_MESSAGE = "Error message to exit on";

    public static void main(String[] args) {
        String command = "command-line-application.sh"; // replace with your command-line application

        ProcessBuilder processBuilder = new ProcessBuilder(command);
        Process process;

        try {
            process = processBuilder.start();

            Thread outputThread = new Thread(() -> {
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        System.out.println("Output: " + line);
                    }
                } catch (Exception e) {
                    System.err.println("Error reading output: " + e.getMessage());
                }
            });
            outputThread.start();

            Thread errorThread = new Thread(() -> {
                try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        System.out.println("Error: " + line);
                        if (line.contains(ERROR_MESSAGE)) {
                            System.out.println("Error message found, exiting...");
                            process.destroy();
                            System.exit(1);
                        }
                    }
                } catch (Exception e) {
                    System.err.println("Error reading error: " + e.getMessage());
                }
            });
            errorThread.start();

            process.waitFor();

            System.out.println("Process finished with exit value: " + process.exitValue());
        } catch (Exception e) {
            System.err.println("Error starting process: " + e.getMessage());
        }
    }
}
