import java.io.*;
import java.util.ArrayList;
import java.util.HashMap;

public class FileFilter {
    public static void main(String[] args) {
        String directoryPath = "path/to/directory";
        String dataType = "your_data_type";
        ArrayList<String> output = new ArrayList<>();

        File directory = new File(directoryPath);
        File[] files = directory.listFiles();

        if (files == null) {
            System.out.println("The directory is either empty or the listFiles() method returned null.");
            return;
        }

        HashMap<String, Object> dataMap = new HashMap<>();

        for (File file : files) {
            try {
                FileInputStream fileInput = new FileInputStream(file);
                ObjectInputStream objectInput = new ObjectInputStream(fileInput);

                Object object = objectInput.readObject();

                if (object != null && object.getClass().getName().equals(dataType)) {
                    output.add(file.getName());
                    dataMap.put(file.getName(), object);
                }

                objectInput.close();
                fileInput.close();
            } catch (FileNotFoundException e) {
                System.out.println("File: " + file.getName() + " not found.");
            } catch (IOException e) {
                System.out.println("Error reading file: " + file.getName());
            } catch (ClassNotFoundException e) {
                System.out.println("Invalid data type in file: " + file.getName());
            }
        }

        System.out.println("Files containing the specified data type:");
        for (String file : output) {
            System.out.println(file);
        }

        System.out.println("Data stored in Hashtable:");
        for (String key : dataMap.keySet()) {
            System.out.println(key + ": " + dataMap.get(key));
        }
    }
}
