import java.io.*;

public void deepCopy(Object obj) throws IOException {
    ByteArrayOutputStream byteArrayOS = new ByteArrayOutputStream();
    ObjectOutputStream objectOS = new ObjectOutputStream(byteArrayOS);

    try {
        objectOS.writeObject(obj);
    } catch (Exception e) {
        System.err.println("Error writing object to ByteArrayOutputStream: " + e.getMessage());
        return;
    }

    ByteArrayInputStream byteArrayIS = new ByteArrayInputStream(byteArrayOS.toByteArray());
    ObjectInputStream objectIS = new ObjectInputStream(byteArrayIS);

    try {
        Object deepCopy = objectIS.readObject();
        System.out.println("Deep copy created successfully: " + deepCopy.getClass().getName());
        return deepCopy;
    } catch (Exception e) {
        System.err.println("Error reading object from ByteArrayInputStream: " + e.getMessage());
    }

    // Don't forget to close the streams
    objectOS.close();
    byteArrayOS.close();
    objectIS.close();
    byteArrayIS.close();
}
