public class BytesToStreamInput {

    public static StreamInput bytesToStreamInput(BytesReference bytesRef) throws IOException {
        if (bytesRef instanceof ByteBuffer) {
            ByteBuffer byteBuffer = (ByteBuffer) bytesRef;
            return new StreamInput(new ByteArrayInputStream(byteBuffer.array(), 0, (int) byteBuffer.limit()));
