public class CanalConsumer {
    private static final String BOOTSTRAP_SERVERS = "127.0.0.1:11111";
    private static final String DATABASE = "testDB";
    private static final String TABLE = "testTable";
    private static final int BATCH_SIZE = 10;

    public static void main(String[] args) throws Exception {
        CanalProperties properties = new CanalProperties();
        properties.setBootstrapServers(BOOTSTRAP_SERVERS);
        properties.setConsumerId("testConsumer");
        properties.setDatabase(DATABASE);
        properties.setTable(TABLE);

        CanalConnector connector = CanalConnector.newSingleConnector(
                new InetSocketAddress(properties.getBootstrapServers()),
                properties);

        connector.connect();
        connector.subscribe();

        // Rollback to the beginning of the topic
        connector.rollback();

        int offset = 0;
        int batchCount = 0;
        List<CanalMessage> messages = new ArrayList<>();

        while (batchCount < Integer.MAX_VALUE) {
            CanalMessage message = connector.getWithoutAck(BATCH_SIZE);
            if (message == null) {
                break;
            }

            if (message.getType() == MessageType.TRANSACTIONBEGIN) {
                connector.rollback();
                offset = 0;
                continue;
            }

            messages.add(message);
            offset += message.getProperties().getRowsData().length;
            batchCount++;
        }

        System.out.println("Received " + batchCount + " messages in batches.");

        for (CanalMessage msg : messages) {
            // Process the received messages here
            System.out.println("Received message: " + new String(msg.getProperties().getRowsData()));
        }

        connector.commitSync();
        connector.disconnect();
    }
}
