public class YouTubePlayer implements EntryPoint {

    private static final String API_KEY = "YOUR_API_KEY";
    private static final String VIDEO_ID = "VIDEO_ID";

    public void onModuleLoad() {
        initPlayer();
    }

    private void initPlayer() {
        final Widget container = new FlowPanel();
        RootPanel.get().add(container);

        final YouTubePlayerApi player = new YouTubePlayerApi(API_KEY);
        player.setPlayerSize(360, 270);
        player.setPlayerVars("autoplay=1&rel=0");
        player.setPlayerVersion("3");

        player.load("https://www.youtube.com/embed/" + VIDEO_ID, new LoadCallback() {
            @Override
            public void onLoad(Player player) {
                player.cueVideoByID(VIDEO_ID);

                player.addListener(new EventListener() {
                    @Override
                    public void onBrowserEvent(Event event) {
                        if (event instanceof DragEvent) {
                            DragEvent dragEvent = (DragEvent) event;
                            if (dragEvent.getDragActions() == DragEvent.DRAG_MOVE) {
                                int left = container.getElement().getAbsoluteLeft();
                                int top = container.getElement().getAbsoluteTop();
                                container.getElement().setStyleName("dragging");
                                Element.getDocument().getBody().setStyleProperty("cursor", "move");
                                Element.getDocument().getBody().setStyleProperty("user-select", "none");
                                Element.getDocument().getBody().setStyleProperty("pointer-events", "none");
                                Element.getDocument().getBody().setStyleProperty("touch-action", "none");
                                player.setPosition(left, top);
                            }
                        }
                    }
                });
            }
        });

        player.setContainer(container);
    }
