import java.io.*;
import java.net.Socket;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;

public class RemoteServerCaller {

    private String serverAddress;
    private int serverPort;

    public RemoteServerCaller(String serverAddress, int serverPort) {
        this.serverAddress = serverAddress;
        this.serverPort = serverPort;
    }

    public Object callRemoteMethod(String methodName, Object[] arguments) throws IOException {
        Socket socket = new Socket(serverAddress, serverPort);

        ObjectOutputStream outputStream = new ObjectOutputStream(socket.getOutputStream());
        ObjectInputStream inputStream = new ObjectInputStream(socket.getInputStream());

        // Serialize request
        Callable request = new Callable(methodName, arguments);
        outputStream.writeObject(request);
        outputStream.flush();

        // Receive response
        Object response = inputStream.readObject();

        outputStream.close();
        inputStream.close();
        socket.close();

        // Unwrap result if necessary
        if (response instanceof Callable) {
            response = processCallableResponse((Callable) response);
        }

        return response;
    }

    private Object processCallableResponse(Callable callable) throws IOException, ClassNotFoundException {
        Object result = callable.getResult();
        if (result instanceof Serializable) {
            return result;
        } else {
            throw new RuntimeException("Remote method call returned non-serializable result");
        }
    }

    static class Callable implements Serializable {
        private String methodName;
        private Object[] arguments;

        public Callable(String methodName, Object[] arguments) {
            this.methodName = methodName;
            this.arguments = arguments;
        }

        private Object getResult() throws Exception {
            Class<?> targetClass = Class.forName("target.package.YourRemoteClass");
            Object targetObject = targetClass.newInstance();
            Method method = targetClass.getMethod(methodName, arguments.getClass());
            InvocationHandler handler = new InvocationHandler() {
                public Object invoke(Object proxy, Method method, Object[] args) throws Throwable {
                    return method.invoke(targetObject, args);
                }
            };
            Object proxyInstance = Proxy.newProxyInstance(targetClass.getClassLoader(), new Class[] {targetClass}, handler);
            return method.invoke(proxyInstance, arguments);
        }
    }
}
