    private static final int KEEP_ALIVE_TIME = 60000; // 1 minute
    private static final int KEEP_ALIVE_INTERVAL = 5000; // 5 seconds

    public static int connectAndSendMessage(String host, int port, byte[] messageBuffer) {
        Socket socket = null;
        OutputStream outputStream = null;
        try {
            socket = new Socket(host, port);
            socket.setKeepAlive(true);
            socket.setTcpNoDelay(true);

            outputStream = socket.getOutputStream();
            outputStream.write(messageBuffer, 0, messageBuffer.length);
            outputStream.flush();

            int keepAlive = socket.getKeepAlive();
            socket.setKeepAliveTime(KEEP_ALIVE_TIME);
            socket.setKeepAliveInterval(KEEP_ALIVE_INTERVAL);

            if (keepAlive != socket.getKeepAlive()) {
                System.out.println("Successfully enabled keepalive.");
            }

            // Handle flush requests by re-sending the message buffer
            while (true) {
                int bytesRead = 0;
                byte[] buffer = new byte[messageBuffer.length];
                int serverResponse = socket.read(buffer, 0, messageBuffer.length);
                if (serverResponse > 0) {
                    String response = new String(buffer, 0, serverResponse);
                    if (response.contains("flush")) {
                        outputStream.write(messageBuffer, 0, messageBuffer.length);
                        outputStream.flush();
                    } else {
                        break;
                    }
                } else if (serverResponse == -1) {
                    System.out.println("Connection closed by peer.");
                    break;
                } else {
                    System.out.println("Error reading from server: " + serverResponse);
                    break;
                }
            }

            return socket.getPort();
        } catch (IOException e) {
            System.err.println("Error connecting to remote host: " + e.getMessage());
            return -1;
        } finally {
            try {
                if (outputStream != null) {
                    outputStream.close();
                }
            } catch (IOException e) {
                System.err.println("Error closing output stream: " + e.getMessage());
            }
            try {
                if (socket != null) {
                    socket.close();
                }
            } catch (IOException e) {
                System.err.println("Error closing socket: " + e.getMessage());
            }
        }
    }
}
