import java.io.File;
import java.io.IOException;
import java.math.BigInteger;
import java.security.MessageDigest;

public static BigInteger getMD5Checksum(String filePath, String readType) throws IOException {
    File file = new File(filePath);
    MessageDigest md = MessageDigest.getInstance("MD5");
    byte[] buffer = new byte[1024];
    long fileSize = file.length();
    FileInputStream inputStream = new FileInputStream(file);

    try {
        long bytesRead = 0;
        int read;

        if (readType.equalsIgnoreCase("buffer")) {
            while ((read = inputStream.read(buffer)) > 0) {
                md.update(buffer, 0, read);
                bytesRead += read;
            }
        } else if (readType.equalsIgnoreCase("fileEntity")) {
            while (bytesRead < fileSize) {
                int size = (int) Math.min(buffer.length, fileSize - bytesRead);
                inputStream.read(buffer, 0, size);
                md.update(buffer, 0, size);
                bytesRead += size;
            }
        } else {
            throw new IllegalArgumentException("Invalid read type: " + readType);
        }

        byte[] digest = md.digest();
        BigInteger checksum = new BigInteger(1, digest);
        return checksum;
    } finally {
        inputStream.close();
    }
}
