import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.lang.reflect.InvocationTargetException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class ProcessExecutor {
    private static final Logger logger = Logger.getLogger(ProcessExecutor.class.getName());

    public static boolean executeCommand(String command, List<String> arguments) {
        logger.log(Level.INFO, "Executing command: {0}", command);

        if (arguments != null && !arguments.isEmpty()) {
            String[] cmdArray = new String[arguments.size() + 1];
            cmdArray[0] = command;
            for (int i = 0; i < arguments.size(); i++) {
                cmdArray[i + 1] = arguments.get(i);
            }

            Process process;
            try {
                process = Runtime.getRuntime().exec(cmdArray);
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error executing command: {0}", e.getMessage());
                return false;
            }

            Thread watchdogThread = new Thread(() -> {
                try {
                    process.waitFor();
                } catch (InterruptedException e) {
                    logger.log(Level.SEVERE, "Interrupted while waiting for process to finish: {0}", e.getMessage());
                } finally {
                    process.destroy();
                }
            });
            watchdogThread.start();

            try (BufferedReader input = new BufferedReader(new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
                StringBuilder output = new StringBuilder();
                String line;
                while ((line = input.readLine()) != null) {
                    output.append(line).append("\n");
                    logger.log(Level.INFO, "Output: {0}", line);
                }
            } catch (IOException e) {
                logger.log(Level.SEVERE, "Error reading output stream: {0}", e.getMessage());
            }

            int exitValue;
            try {
                exitValue = process.exitValue();
            } catch (IllegalThreadStateException e) {
                logger.log(Level.SEVERE, "Error getting exit value: {0}", e.getMessage());
                return false;
            }

            logger.log(Level.INFO, "Command execution completed with exit value: {0}", exitValue);
            return exitValue == 0;
        } else {
            logger.log(Level.SEVERE, "Invalid command or empty arguments");
            return false;
        }
    }
}
