public class FileSigner {

    public static void main(String[] args) throws Exception {
        String inputFilePath = "path/to/input/file.txt";
        String outputFilePath = "path/to/output/signed/file.txt";
        String password = "password"; // Optional, use null for no password

        File fileToSign = new File(inputFilePath);
        FileChannel inputChannel = new FileInputStream(fileToSign).getChannel();
        FileChannel outputChannel = new FileOutputStream(new File(outputFilePath)).getChannel();

        Signature signature = null;
        if (password != null) {
            KeyStore keyStore = KeyStore.getInstance("PKCS12");
            keyStore.load(new FileInputStream("path/to/keystore.p12"), password.toCharArray());
            PrivateKey privateKey = (PrivateKey) keyStore.getKey("alias", password.toCharArray());
            signature = Signature.getInstance("SHA1withRSA");
            signature.initSign(privateKey);
        } else {
            KeyPairGenerator keyPairGenerator = KeyPairGenerator.getInstance("RSA");
            keyPairGenerator.initialize(2048);
            KeyPair keyPair = keyPairGenerator.generateKeyPair();
            PrivateKey privateKey = keyPair.getPrivate();
            PublicKey publicKey = keyPair.getPublic();
            signature = Signature.getInstance("SHA1withRSA");
            signature.initSign(privateKey);
            // Save the key pair for later use
            FileOutputStream privateKeyFile = new FileOutputStream("path/to/private/key.pem");
            OutputStreamWriter writer = new OutputStreamWriter(privateKeyFile);
            writer.write(keyPair.getPrivate().getEncoded());
            writer.close();
            FileOutputStream publicKeyFile = new FileOutputStream("path/to/public/key.pem");
            OutputStreamWriter writer2 = new OutputStreamWriter(publicKeyFile);
            writer2.write(keyPair.getPublic().getEncoded());
            writer2.close();
        }

        byte[] inputBytes = new byte[1024];
        int bytesRead;
        while ((bytesRead = inputChannel.read(inputBytes)) > 0) {
            signature.update(inputBytes, 0, bytesRead);
        }
        inputChannel.close();

        byte[] signatureBytes = signature.sign();

        OutputStream os = outputChannel;
        os.write(signatureBytes);
        os.close();

        System.out.println("File signed successfully: " + outputFilePath);
    }
}
