public Map<String, byte[]> mergeMapAndStream(Map<String, String> map, InputStream inputStream) throws IOException {
    Map<String, byte[]> byteMap = new HashMap<>();
    byte[] buffer = new byte[2048];

    // Deserialize binary data stream into a map of string keys to byte values
    ByteArrayDataSource dataSource = new ByteArrayDataSource();
    DataInputStream input = new DataInputStream(new BufferedInputStream(inputStream, 2048));
    while (input.available() > 0) {
        String key = dataSource.getName();
        int size = input.readInt();
        byte[] value = new byte[size];
        input.readFully(value);
        byteMap.put(key, value);
    }
    input.close();

    // Merge the two maps into a single map of string keys to byte values
    Map<String, byte[]> mergedMap = new HashMap<>(map);
    mergedMap.putAll(byteMap);

    return mergedMap;
}

