            case "mac":
                cmdArray = new String[]{"sh", "-c", command};
                break;
            case "windows":
                cmdArray = new String[]{"cmd.exe", "/c", command};
                break;
            default:
                throw new UnsupportedOperationException("Unsupported operating system: " + osName);
        }
    }

    try {
        proc = Runtime.getRuntime().exec(cmdArray);
    } catch (Exception e) {
        throw new RuntimeException("Error executing command: " + command, e);
    }

    try (BufferedReader reader = new BufferedReader(new InputStreamReader(proc.getInputStream()))) {
        String line;
        while ((line = reader.readLine()) != null) {
            output.add(line);
        }
    } catch (IOException e) {
        throw new RuntimeException("Error reading output from command: " + command, e);
    }

    try {
        proc.waitFor();
    } catch (InterruptedException e) {
        throw new RuntimeException("Error waiting for command to finish: " + command, e);
