import javax.crypto.spec.DESKeySpec;
import javax.crypto.spec.Ives2Parameters;

public void generateDESKey(String seed) throws Exception {
    byte[] keyBytes = seed.getBytes();

    KeyGenerator keyGen = KeyGenerator.getInstance("DES");
    keyGen.init(new DESKeySpec(keyBytes));
    SecretKey key = keyGen.generateKey();

    Cipher cipher = Cipher.getInstance("DES/ECB/NoPadding");
    Ives2Parameters iv = new Ives2Parameters(key.getEncoded());

    System.out.println("Generated DES key: " + bytesToHex(key.getEncoded()));
    System.out.println("Generated IV: " + bytesToHex(iv.getIV()));
}

private static String bytesToHex(byte[] bytes) {
    StringBuilder result = new StringBuilder();
    for (byte b : bytes) {
        result.append(String.format("%02x", b));
    }
    return result.toString();
}
