public static WalkMap readFileAndCreateWalkMap(String filePath) {
    File file = new File(filePath);
    String fileName = file.getName();
    WalkMap walkMap = null;

    if (!file.exists()) {
        throw new IOException("File does not exist: " + filePath);
    }

    if (!isValidFormat(fileName)) {
        throw new IOException("Invalid file format: " + filePath);
    }

    if (fileName.toLowerCase().endsWith(".objv")) {
        walkMap = new ViewMap();
    } else if (fileName.toLowerCase().endsWith(".objp")) {
        walkMap = new PathsMap();
    } else {
        try (FileInputStream inputStream = new FileInputStream(file);
             ObjectInputStream objectInputStream = new ObjectInputStream(inputStream)) {
            walkMap = (WalkMap) objectInputStream.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new IOException("Error reading file: " + filePath, e);
        }
    }

    if (fileName.toLowerCase().endsWith(".jrd3m")) {
        byte[] fileContent = Files.readAllBytes(Paths.get(filePath));
        try (ByteArrayInputStream byteInputStream = new ByteArrayInputStream(fileContent);
             ObjectInputStream objectInputStream = new ObjectInputStream(byteInputStream)) {
            walkMap = (WalkMap) objectInputStream.readObject();
        } catch (IOException | ClassNotFoundException e) {
            throw new IOException("Error reading file: " + filePath, e);
        }
    }

