        String timeLow = Long.toHexString(Double.doubleToLongBits(Math.abs(Math.random() * 0x1000000000000000L))).substring(0, 8);
        String timeMid = Long.toHexString((int) (Math.random() * 0x10000)).substring(0, 4);
        String timeHiAndVersion = Long.toHexString((int) (1L << 12 | 0x2b)).substring(0, 6);
