        md.update(timeMid.getBytes());
        md.update(timeHiAndVersion.getBytes());
        md.update(clockSeqAndNode.getBytes());

        md.digest(digest);

        byte[] timeLowBytes = Arrays.copyOfRange(digest, 0, 4);
        byte[] timeMidBytes = Arrays.copyOfRange(digest, 4, 6);
        byte[] timeHiAndVersionBytes = Arrays.copyOfRange(digest, 6, 8);
        byte[] clockSeqAndNodeBytes = Arrays.copyOfRange(digest, 8, 16);

