import java.util.Hashtable;

public class SaxParserPrefixExtractor extends DefaultHandler {
    private Hashtable<String, Integer> prefixFrequencies;

    public SaxParserPrefixExtractor() {
        prefixFrequencies = new Hashtable<>();
    }

    @Override
    public void startElement(String uri, String localName, String qName, Attributes attributes) throws SAXException {
        String prefix = "";
        if (attributes != null) {
            for (int i = 0; i < attributes.getLength(); i++) {
                String attrName = attributes.getLocalName(i);
                if (attrName.startsWith("{http://www.w3.org/2000/xmlns/"})) {
                    prefix = attrName.substring(attrName.lastIndexOf(":") + 1);
                    break;
                }
            }
        }
        if (!prefixFrequencies.containsKey(prefix)) {
            prefixFrequencies.put(prefix, 0);
        }
        prefixFrequencies.put(prefix, prefixFrequencies.get(prefix) + 1);
    }

    @Override
    public void endDocument() throws SAXException {
        for (String prefix : prefixFrequencies.keySet()) {
            System.out.println(prefix + ": " + prefixFrequencies.get(prefix));
        }
    }

    public static void main(String[] args) {
        try {
            SAXParserFactory factory = SAXParserFactory.newInstance();
            SAXParser saxParser = factory.newSAXParser();
            SaxParserPrefixExtractor handler = new SaxParserPrefixExtractor();
            saxParser.parse(new File("file.xml"), handler);
