    byte[] hash = md.digest(data);

    return new BigInteger(1, hash);
}

private static String getPathWithSymlinks(Map<String, String> paths, String moduleName, boolean createSymlinks) {
    String path = paths.getOrDefault(moduleName, "");
    if (createSymlinks) {
        String linkedPath = paths.getOrDefault(path, "");
        if (!linkedPath.isEmpty()) {
            path = linkedPath;
        }
    }
    return path;
}

private static String createHeaderMapString(Map<String, String> paths, boolean createHeaderMap) {
    if (createHeaderMap) {
        StringBuilder headerMap = new StringBuilder();
        for (Map.Entry<String, String> entry : paths.entrySet()) {
            headerMap.append(entry.getKey()).append(":").append(entry.getValue()).append("\n");
        }
        return headerMap.toString();
    } else {
        return "";
    }
}
