    }

    double[] actualCoordinates = new double[]{Double.parseDouble(coordinateArray[0]), Double.parseDouble(coordinateArray[1])};
    if (!Arrays.deepEquals(new double[]{expectedX, expectedY}, actualCoordinates)) {
