import java.io.*;
import java.lang.reflect.InvocationTargetException;

public class SingletonLoader {

    @SuppressWarnings("unchecked")
    public static <T> T getInstance(Class<T> clazz) {
        File file = new File("singleton.ser");
        T instance = null;

        try {
            if (file.exists()) {
                FileInputStream fileInput = new FileInputStream(file);
                ObjectObjectOutput objectOutput = new ObjectOutputStream(fileInput);
                instance = (T) objectOutput.readObject();
                objectOutput.close();
                fileInput.close();
            } else {
                instance = clazz.newInstance();
                saveToFile(instance, clazz);
            }
        } catch (FileNotFoundException e) {
            System.err.println("File not found: " + e.getMessage());
        } catch (IOException e) {
            System.err.println("Error reading file: " + e.getMessage());
        } catch (ClassNotFoundException e) {
            System.err.println("Error deserializing class: " + e.getMessage());
        } catch (InstantiationException e) {
            System.err.println("Error instantiating class: " + e.getMessage());
        } catch (IllegalAccessException e) {
            System.err.println("Error accessing class: " + e.getMessage());
        }

        return instance;
    }

    private static <T> void saveToFile(T object, Class<T> clazz) {
        File file = new File("singleton.ser");

        try {
            FileOutputStream fileOutput = new FileOutputStream(file);
            ObjectObjectOutput objectOutput = new ObjectOutputStream(fileOutput);
            objectOutput.writeObject(object);
            objectOutput.close();
            fileOutput.close();
        } catch (IOException e) {
