import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import javax.crypto.Base64;
import java.util.Random;

public class EncryptionUtil {
    public static String blowfishEncrypt(String plainText, String secretKey, String iv) throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance("Blowfish");
        keyGen.init(128);
        SecretKey secret = keyGen.generateKey();

        SecretKeySpec keySpec = new SecretKeySpec(secret.getEncoded(), "Blowfish");
        Cipher cipher = Cipher.getInstance("Blowfish/CBC/PKCS5Padding");
        IvParameterSpec ivSpec = new IvParameterSpec(iv.getBytes());

        byte[] plainTextBytes = plainText.getBytes();
        byte[] encryptedText = null;

        if (plainTextBytes.length % 8 != 0) {
            int paddingLength = 8 - (plainTextBytes.length % 8);
            plainTextBytes = new byte[plainTextBytes.length + paddingLength];
            System.arraycopy(plainTextBytes, 0, plainTextBytes, 0, plainTextBytes.length - paddingLength);
            plainTextBytes[plainTextBytes.length - paddingLength] = (byte) paddingLength;
        }

        cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec);
        encryptedText = cipher.doFinal(plainTextBytes);

        byte[] base64EncryptedText = Base64.getEncoder().encode(encryptedText);
        return new String(base64EncryptedText);
    }
}
