public class XPathEvaluator {
    public String evaluateXPath(String xmlString, String xpathExpression) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            Document document = factory.newDocumentBuilder().parse(new InputSource(new StringReader(xmlString)));

            XPathFactory xPathfactory = XPathFactory.newInstance();
            XPath xpath = xPathfactory.newXPath();

            Node resultNode = (Node) xpath.compile(xpathExpression).evaluate(document, XPathConstants.NODE);

            if (resultNode == null) {
                return "XPath expression returned false.";
            }

            return null;
        } catch (Exception e) {
            e.printStackTrace();
            return "Error occurred while evaluating XPath expression.";
        }
    }
}
