public class NFASerialization {

    public static void main(String[] args) throws Exception {
        int windowLength = 10;
        NFA<Event> originalNFA = createNFA(windowLength);

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ObjectOutputStream oos = new ObjectOutputStream(baos);
        oos.writeObject(originalNFA);

        ByteArrayInputStream bais = new ByteArrayInputStream(baos.toByteArray());
        ObjectInputStream ois = new ObjectInputStream(bais);

        @SuppressWarnings("unchecked")
        NFA<Event> deserializedNFA = (NFA<Event>) ois.readObject();

        if (originalNFA.equals(deserializedNFA)) {
            System.out.println("Original and deserialized NFAs are equal.");
        } else {
            System.out.println("Original and deserialized NFAs are not equal.");
        }
    }

    private static NFA<Event> createNFA(int windowLength) {
        NFA<Event> nfa = new NFA<>(Event.createTypeSerializer(), windowLength, false);
        State startingState = new State("startingState");
        State startState = new State("startState");
        State endState = new State("endState");

        nfa.addState(startingState);
        nfa.addState(startState);
        nfa.addState(endState);

        return nfa;
    }
