import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.util.Base64;

public String encryptMD5(String message, String encodingScheme, boolean toUppercase) throws NoSuchAlgorithmException, InvalidKeyException {
    MessageDigest md = MessageDigest.getInstance("MD5");
    byte[] messageBytes;

    if (toUppercase) {
        message = message.toUpperCase();
    }

    messageBytes = message.getBytes();
    md.update(messageBytes);
    byte[] digest = md.digest();

    String encryptedMessage = bytesToHex(digest);
    return encryptedMessage;
}

private String bytesToHex(byte[] bytes) {
    byte[] hexBytes = new byte[2 * bytes.length];
    for (int i = 0; i < bytes.length; i++) {
        int v = bytes[i] & 0xFF;
        hexBytes[2 * i] = (byte) (v >>> 4);
        hexBytes[2 * i + 1] = (byte) (v & 0x0F);
    }
    return Base64.getEncoder().encodeToString(hexBytes);
}
