public void runCommand(String[] cmd) {
    Process process;
    try {
        process = Runtime.getRuntime().exec(cmd);
    } catch (Exception e) {
        System.err.println("Error executing command: " + e.getMessage());
        return;
    }

    StringJoiner outputJoiner = new StringJoiner("\n");
    StringJoiner errorJoiner = new StringJoiner("\n");

    try (BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
         BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

        String line;
        while ((line = outputReader.readLine()) != null) {
            outputJoiner.add(line);
            System.out.println("Output: " + line);
        }

        while ((line = errorReader.readLine()) != null) {
            errorJoiner.add(line);
            System.err.println("Error: " + line);
        }
    } catch (Exception e) {
        System.err.println("Error reading streams: " + e.getMessage());
        return;
    }

    int exitValue;
    try {
        exitValue = process.waitFor();
    } catch (InterruptedException e) {
        System.err.println("Interrupted while waiting for process to finish: " + e.getMessage());
        return;
    }

    if (exitValue != 0) {
        System.err.println("Process finished with non-zero exit value: " + exitValue);
        return;
    }

    String output = outputJoiner.toString();
    String error = errorJoiner.toString();

    System.out.println("Output:\n" + output);
    System.err.println("Error:\n" + error);

    runCommand(cmd) ; // Call the method recursively to read the output line by line if the process terminates
}
