import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class MD5Filter implements Filter {
    private int frequency;
    private byte[] filteredData;

    public MD5Filter(int frequency) {
        this.frequency = frequency;
    }

    @Override
    public byte[] filter(byte[] inputData) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(inputData);
            byte[] md5Hash = md.digest();

            if (md5Hash.length != 16) {
                throw new RuntimeException("MD5 hash length should be 16");
            }

            int count = 0;
            for (byte b : md5Hash) {
                count += (b & 0xFF) + 1;
                if (count > frequency) {
                    filteredData = new byte[16];
                    System.arraycopy(md5Hash, 0, filteredData, 0, 16);
                    break;
                }
            }

        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not supported", e);
        }

        return filteredData;
    }
}

interface Filter {
    byte[] filter(byte[] inputData);
}
