        try {
            CloseableHttpResponse response = httpClient.execute(httpPost);
            int statusCode = response.getStatusLine().getStatusCode();

            if (statusCode >= 200 && statusCode < 300) {
                uploadSuccess = true;
            } else {
                System.err.println("Failed to upload file: HTTP error code: " + statusCode);
                retries++;

                if (retries < 3) {
                    Thread.sleep(1000 * 5); // wait 5 seconds before retrying
                    System.out.println("Retrying upload...");
                }
            }

            EntityUtils.consume(response.getEntity());
            response.close();
        } catch (Exception e) {
            System.err.println("Error during file upload: " + e.getMessage());
            retries++;

            if (retries < 3) {
                Thread.sleep(1000 * 5); // wait 5 seconds before retrying
                System.out.println("Retrying upload...");
            }
        }
    }

    if (uploadSuccess) {
        System.out.println("File uploaded successfully.");
    } else {
        System.err.println("Failed to upload file after 3 retries.");
    }

