import org.apache.http.HttpHost;
import org.apache.http.auth.BasicScheme;
import org.apache.http.client.CredentialsProvider;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpGet;
import org.apache.http.conn.registry.Registry;
import org.apache.http.conn.socket.ConnectionSocketFactory;
import org.apache.http.conn.socket.PlainConnectionSocketFactory;
import org.apache.http.conn.socket.SSLConnectionSocketFactory;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

public class Main {
    public static void main(String[] args) {
        String url = "http://example.com";
        String proxyHost = "proxy.example.com";
        int proxyPort = 8080;
        String username = "proxy_user";
        String password = "proxy_password";

        // Create a custom RequestConfig with a proxy server
        RequestConfig requestConfig = RequestConfig.custom()
                .setProxy(new HttpHost(proxyHost, proxyPort))
                .build();

        // Create a BasicCredentialsProvider with a username and password
        CredentialsProvider credentialsProvider = CredentialsProvider.create();
        credentialsProvider.setCredentials(AuthScope.ANY, new UsernamePasswordCredentials(username, password));

        // Create a Registry and a RegistryBuilder to register the SSLConnectionSocketFactory and the PlainConnectionSocketFactory
        Registry localRegistry = RegistryBuilder.create().build();
        localRegistry.register("http", PlainConnectionSocketFactory.getSocketFactory());
        localRegistry.register("https", SSLConnectionSocketFactory.getSocketFactory());

        // Create a CloseableHttpClient using the HttpClientBuilder
        CloseableHttpClient httpClient = HttpClients.custom()
                .setDefaultRequestConfig(requestConfig)
                .setDefaultCredentialsProvider(credentialsProvider)
                .setRegistry(localRegistry)
                .build();

        try {
            // Create and execute a GET request
            HttpGet httpGet = new HttpGet(url);
            CloseableHttpResponse response = httpClient.execute(httpGet);

            // Retrieve the response entity and convert it to a string
            String responseString = EntityUtils.toString(response.getEntity());
            System.out.println(responseString);
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            // Close the resources
            try {
                httpClient.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }
}
