import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.io.UnsupportedEncodingException;
import java.nio.charset.StandardCharsets;

public class CommandExecutor {

    public static Process executeCommand(String command) {
        StringBuilder cmdBuilder = new StringBuilder();
        cmdBuilder.append(System.getProperty("os.name").contains("Windows") ? "cmd /c " : "");
        cmdBuilder.append(escapedCommand(command));

        try {
            Process process = Runtime.getRuntime().exec(cmdBuilder.toString());
            if (process.waitFor() && process.exitValue() == 0) {
                return process;
            } else {
                throw new RuntimeException("Command execution failed with error code: " + process.exitValue());
            }
        } catch (IOException | InterruptedException e) {
            throw new RuntimeException("Error executing command: " + command, e);
        }
    }

    private static String escapedCommand(String command) {
        StringBuilder cmd = new StringBuilder();
        for (int i = 0; i < command.length(); i++) {
            char c = command.charAt(i);
            switch (c) {
                case '&':
                    cmd.append("^&");
                    break;
                case ';':
                    cmd.append("^;");
                    break;
                case '(':
                    cmd.append("^(");
                    break;
                case ')':
                    cmd.append("^)");
                    break;
                case '|':
                    cmd.append("^|");
                    break;
                case '<':
                    cmd.append("^<");
                    break;
                case '>':
                    cmd.append("^>");
                    break;
                case '`':
                    cmd.append("^`");
                    break;
                case '!':
                    cmd.append("^!");
                    break;
                case '"':
                    cmd.append("^\"");
                    break;
                case '\'':
                    cmd.append("^'");
                    break;
                case '\\':
                    cmd.append("^\\");
                    break;
                case '%':
                    if (System.getProperty("os.name").contains("Windows")) {
                        cmd.append("%");
                    } else {
                        cmd.append("\\%");
                    }
                    break;
                default:
                    cmd.append(c);
            }
        }
        return cmd.toString();
    }

    public static String getOutput(Process process) {
        StringBuilder output = new StringBuilder();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                output.append(line);
                output.append("\n");
            }
        } catch (IOException e) {
            throw new RuntimeException("Error reading command output", e);
        }
        return output.toString();
    }

    public static void main(String[] args) {
        String command = "echo Hello, World!";
        Process process = executeCommand(command);
        try {
            process.waitFor();
            if (process.exitValue() == 0) {
                System.out.println("Command output: " + getOutput(process));
            } else {
                throw new RuntimeException("Command execution failed with error code: " + process.exitValue());
            }
        } catch (InterruptedException | IOException e) {
            throw new RuntimeException("Error executing command: " + command, e);
        }
    }
}
