        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Edge)) return false;
            Edge edge = (Edge) o;
            return key.equals(edge.key);
        }

        @Override
        public int hashCode() {
            return key.hashCode();
        }
    }
}
