        SecretKeySpec keySpec = new SecretKeySpec(keyBytes, "AES");
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.ENCRYPT_MODE, keySpec);

        byte[] dataBytes = data.getBytes();
        int ivLength = cipher.getBlockSize();
        byte[] iv = new byte[ivLength];
        Arrays.fill(iv, (byte) ivLength);

        int dataLength = data.length();
        int paddingLength = ivLength - (dataLength % ivLength);
        byte[] paddedData = new byte[dataLength + paddingLength];
        System.arraycopy(dataBytes, 0, paddedData, 0, dataLength);
        Arrays.fill(paddedData, dataLength, paddedData.length, (byte) paddingLength);

        int outputLength = 0;
        encryptedData = cipher.doFinal(paddedData, 0, paddedData.length);
        outputLength = encryptedData.length;

        String base64EncryptedData = new String(Base64.getEncoder().encode(encryptedData));
        cipher.doFinal();

        return base64EncryptedData;
    } catch (Exception e) {
        e.printStackTrace();
        return null;
    }
}
