import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

public String generateRandomHash(double seed) {
    byte[] hash;
    try {
        SecretKeySpec secretKey = new SecretKeySpec("JAvaSecretKey".getBytes(), "HmacSHA256");
        Mac sha256Hmac = Mac.getInstance("HmacSHA256");
        sha256Hmac.init(secretKey);
        byte[] input = Double.toString(seed).getBytes();
        hash = sha256Hmac.doFinal(input);
    } catch (Exception e) {
        throw new RuntimeException(e);
    }

    StringBuilder sb = new StringBuilder();
    for (byte b : hash) {
        sb.append(String.format("%02x", b));
    }
    return sb.toString().substring(0, 64); // return 32-digit hexadecimal string
}
