public class MergedInterval {

    public static String mergeSegments(List<Segment> segments) {
        LocalDateTime mergedStart = segments.get(0).getStart();
        LocalDateTime mergedEnd = mergedStart;

        for (Segment segment : segments) {
            if (segment.getStart().isBefore(mergedEnd)) {
                mergedEnd = LocalDateTime.max(mergedEnd, segment.getEnd());
