const fs = require('fs');
let cachedModules = new Map();

function loadModule(filename, options) {
  if (cachedModules.has(filename)) {
    return cachedModules.get(filename);
  }

  const moduleContent = fs.readFileSync(filename, 'utf-8');
  const module = new Function(`${options.exportsVar} = require("${options.moduleName}");\n${moduleContent}`)();

  cachedModules.set(filename, module);
  return module;
}

function requireSync(filename, options) {
  if (options && options.exports) {
    options.exportsVar = '__exports__';
  }

  const module = loadModule(filename, options);
  return module.default || module.__exports__;
}

