function asyncReduce(arr, initialValue, callback) {
  return new Promise((resolve, reject) => {
    let accumulator = initialValue;
    let index = 0;

    function reduceNext() {
      if (index >= arr.length) {
        return resolve(accumulator);
      }

      callback(accumulator, arr[index], (acc, current) => {
        accumulator = acc;
        index++;
        reduceNext();
      });
    }

    reduceNext();
  });
}

