```javascript
const fs = require('fs');
const path = require('path');
const stylus = require('stylus');

function generateCSSFile(inputFilePaths, outputFilePath, destinationDir) {
  return new Promise((resolve, reject) => {
    const inputFiles = inputFilePaths.map(filePath => fs.readFileSync(filePath, 'utf8'));
    const stylusStream = stylus(inputFiles.join(''));

    stylusStream.on('error', err => {
      reject(err);
    });

    stylusStream.on('end', () => {
      const outputFile = path.join(destinationDir, outputFilePath);
      fs.writeFileSync(outputFile, stylusStream.css.toString());
      resolve(outputFile);
    });
  });
}

function ensureDirectoryExists(filePath) {
  return new Promise((resolve, reject) => {
    fs.access(filePath, fs.constants.F_OK, err => {
      if (err) {
        fs.mkdir(filePath, err => {
          if (err) {
            reject(err);
          } else {
            resolve(filePath);
          }
        });
      } else {
        resolve(filePath);
      }
    });
  });
}

function generateCSS(inputFilePaths, outputFilePath, destinationDir) {
  return ensureDirectoryExists(destinationDir).then(() => generateCSSFile(inputFilePaths, outputFilePath, destinationDir));
}

