const fs = require('fs-extra');
const path = require('path');

async function checkExists() {
  let currentPath = process.cwd();
  const requiredFilesAndDirs = ['file1.js', 'file2.js', 'dir1', 'dir2'];

  for (const item of requiredFilesAndDirs) {
    const fullPath = path.join(currentPath, item);

    try {
      if (fs.statSync(fullPath).isDirectory()) {
        await checkExistsRecursively(fullPath);
      } else if (fs.existsSync(fullPath)) {
        continue;
      } else {
        throw new Error(`${item} does not exist.`);
      }
    } catch (err) {
      console.error(err.message);
      return false;
    }
  }

  console.log('All required files and directories exist.');
  return true;
}

async function checkExistsRecursively(dirPath) {
  const files = await fs.readdir(dirPath);

  for (const file of files) {
    const filePath = path.join(dirPath, file);

    if (fs.statSync(filePath).isDirectory()) {
      await checkExistsRecursively(filePath);
    } else if (file === 'file1.js' || file === 'file2.js') {
      continue;
    }
  }
}

