const fs = require('fs');

function readFileSync(filePath) {
  const fileStats = fs.statSync(filePath);
  if (fileStats.isFile()) {
    return fs.readFileSync(filePath, 'utf-8');
  } else {
    throw new Error(`${filePath} is not a file`);
  }
}

function readDirectorySync(directoryPath) {
  const files = fs.readdirSync(directoryPath);
  return files;
}

function findFileSync(directoryPath, fileName) {
  const files = readDirectorySync(directoryPath);
  for (const file of files) {
    const filePath = `${directoryPath}/${file}`;
    const stats = fs.lstatSync(filePath);
    if (stats.isFile() && file === fileName) {
      return readFileSync(filePath);
    }
  }
  throw new Error(`File ${fileName} not found in ${directoryPath}`);
}

module.exports = { readFileSync, readDirectorySync, findFileSync };
