const fs = require('fs');
const path = require('path');

function validateAndCreateDirectoryTree(fs, dirPath, options = { create: true, validate: true }) {
    try {
        const stats = fs.statSync(dirPath);
        if (!stats.isDirectory()) {
            return false;
        }
    } catch (err) {
        if (err.code === 'ENOENT' && options.create) {
            fs.mkdirSync(dirPath, { recursive: true });
        } else {
            return false;
        }
    }

    const entries = fs.readdirSync(dirPath);
    for (const entry of entries) {
        const fullPath = path.join(dirPath, entry);
        try {
            const stats = fs.statSync(fullPath);
            if (stats.isDirectory()) {
                if (!validateAndCreateDirectoryTree(fs, fullPath, options)) {
                    return false;
                }
            } else if (options.validate && !stats.isFile()) {
                return false;
            }
        } catch (err) {
            return false;
        }
    }

    return true;
}
