```javascriptasync function createAndLeaveChannel(guildId, channelId, newChannelName, existingRoleId) {
  const Discord = require('discord.js');
  const { Client, Intents } = Discord;
  const client = new Client({ intents: [Intents.FLAGS.GUILDS, Intents.FLAGS.CHANNELS] });

  client.once('ready', () => {
    console.log('Ready!');
  });

  async function createNewChannel(guildId, newChannelName) {
    const guild = await client.guilds.fetch(guildId);
    const ticketRole = guild.roles.cache.find(r => r.id === existingRoleId);
    const categoryChannel = guild.channels.cache.find(c => c.type === 'GUILD_CATEGORY');

    if (!categoryChannel) {
      console.log('Error: Category channel not found.');
      return;
    }

    const n1 = Math.pow(10, 10);
    const n2 = n1 * 10 - 1;
    const ticketId = Math.floor(Math.random() * (n2 - n1 + 1) + n1);
    const newChannel = await guild.channels.create(newChannelName, {
      type: 'TEXT',
      parent: categoryChannel.id,
    });

    await newChannel.setPermissions(ticketRole, {
      readMessages: true,
      sendMessages: true,
    });

    await newChannel.setPermissions(client.user, {
      readMessages: true,
      sendMessages: true,
      manageChannels: true,
    });

    await newChannel.edit({
      topic: `New ticket ${ticketId} created by ${client.users.cache.get(channelId).tag}`,
    });

    const existingChannel = guild.channels.cache.find(c => c.id === channelId);
    if (existingChannel) {
      await existingChannel.members.cache.get(guild.id).leave();
    }
  }

  createNewChannel(guildId, newChannelName);
}
