function checkFileExistsInDirectory(path, file) {
  fs.stat(path, (err, stats) => {
    if (err) {
      if (err.code === 'ENOENT') {
        // Directory does not exist, check if it's a parent directory and recursively call
        if (path.dirname(path) !== path) {
          checkFileExistsInDirectory(path.dirname(path), file, () => {});
