function generateRandomStar(canvas, ctx) {
  const width = canvas.width;
  const height = canvas.height;

  // Generate random position, velocity, and radius
  const x = Math.floor(Math.random() * width);
  const y = Math.floor(Math.random() * height);
  const velocityX = Math.random() * 5 - 2.5;
  const velocityY = Math.random() * 5 - 2.5;
  const radius = Math.floor(Math.random() * 10) + 5;

  // Clear the canvas
  ctx.clearRect(0, 0, width, height);

  // Set the fill style to a radial gradient
  const grad = ctx.createRadialGradient(x, y, 0, x, y, radius);
  grad.addColorStop(0, 'rgba(255, 255, 255, 1)'); // White star core
  grad.addColorStop(1, 'rgba(255, 255, 255, 0)'); // Transparent star edges

  // Draw the star using the arc method
  ctx.fillStyle = grad;
  ctx.lineWidth = 0;
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2, false);
  ctx.fill();

  // Update the star position for the next frame
  x += velocityX;
  y += velocityY;

  // Redraw the star at the updated position
  generateRandomStar(canvas, ctx, x, y);
}

