function depthFirstSearch(grid, x, y, maxNodes) {
  const visited = new Set();
  let nodesPlanted = 0;

  function dfs(x, y) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[0].length) return;
    if (visited.has(x + '_' + y)) return;

    visited.add(x + '_' + y);
    grid[x][y].state = 'visited';
