        const array = [];
        if (arrayLength === 0xFF) {
          do {
            array.push(decodeTag());
          } while (array.length < 1000000);
        } else {
          for (let i = 0; i < arrayLength; i++) {
            array.push(decodeTag());
          }
        }
        return array;

      case 0x05: // Map
        const map = {};
        const mapLength = readByte();
