const FileUploader = require('file-uploader'); // Assuming you have installed the library
const Logger = require('winston'); // Assuming you have installed the Logger library
const Bluebird = require('bluebird');

function uploadFileFromUrl(url) {
  return Bluebird.resolve()
    .then(() => {
      // Create a new FileUploader instance
      const uploader = new FileUploader({
        tempFolder: './uploads/temp', // Set your desired temp folder
        destFolder: './uploads/processed' // Set your desired processed folder
      });

      return uploader.use(FileUploader.parse(url))
        .then(result => {
          if (result.error) {
            Logger.error(`Error uploading file from URL: ${result.error}`);
            throw new Error(`Error uploading file from URL: ${result.error}`);
          }

          return uploader.process(result.files[0].path, result.files[0].originalname, null, null)
            .then(response => {
              if (response.error) {
                Logger.error(`Error processing file: ${response.error}`);
                throw new Error(`Error processing file: ${response.error}`);
              }

              Logger.info(`File uploaded successfully: ${result.files[0].originalname}`);
              return response.file.path; // Return the URL of the uploaded file
            })
        })
    })
}
```

