```javascript
const gulp = require('gulp');
const sass = require('gulp-sass');
const typescript = require('gulp-typescript');
const html = require('gulp-html');
const concat = require('gulp-concat');

// Set the base directory for the build
const basePath = './src';

// Define the paths for the build
const scssPath = `${basePath}/scss/**/*.scss`;
const tsPath = `${basePath}/typescript/**/*.ts`;
const htmlPath = `${basePath}/templates/**/*.html`;
const outputPath = './dist';

// Compile Sass files
function compileSass() {
  return gulp.src(scssPath)
    .pipe(sass().on('error', sass.logError))
    .pipe(gulp.dest(`${outputPath}/css`));
}

// Compile TypeScript files
function compileTypescript() {
  const tsProject = new typescript.project();
  const tsSources = gulp.src(tsPath).pipe(typescript(tsProject));
  return tsSources.js.pipe(gulp.dest(`${outputPath}/js`));
}

// Process HTML templates
function processHtml() {
  return gulp.src(htmlPath)
    .pipe(html())
    .pipe(gulp.dest(`${outputPath}/html`));
}

// Concatenate and minify the files
function concatFiles() {
  return gulp.src([`${outputPath}/css/**/*.css`, `${outputPath}/js/**/*.js`])
    .pipe(concat('bundle.js'))
    .pipe(gulp.dest(`${outputPath}/js`));
}

// Default task to run the build
function defaultTask(cb) {
  gulp.series(compileSass, compileTypescript, processHtml, concatFiles)(cb);
}

// Run the build
gulp.task('default', defaultTask);
