    } else {
      resolve();
    }
  });
}

function buildPackage(src, dest) {
  return new Promise((resolve, reject) => {
    const args = ['npm', 'run', 'build', '--source-map=false'];
    const packChild = child_process.spawnSync('npm', args, { cwd: src, encoding: 'buffer' });

    if (packChild.status !== 0) {
      reject(new Error(`Failed to build package: ${packChild.stderr.toString()}`));
    } else {
      fs.copy(path.join(src, 'dist'), dest, (err) => {
