function traverseDOMAndMatchSelector(root, selector, testFunction) {
  const stack = [root];
  const matchedElements = [];

  while (stack.length > 0) {
    const currentElement = stack.pop();

    if (currentElement.matches && currentElement.matches(selector)) {
