const fs = require('fs');
const path = require('path');
const child_process = require('child_process');

function executeCommand(command, inputFiles, callback) {
  if (inputFiles && inputFiles.length > 0) {
    inputFiles.forEach(file => {
      if (!fs.existsSync(file)) {
        console.log(`Error: Input file '${file}' does not exist.`);
        callback(new Error(`Input file '${file}' does not exist.`));
        return;
      }
    });
  }

  const options = {
    cwd: process.cwd(), // Change the current working directory if needed
    shell: true,
    encoding: 'utf8' // Set the output encoding to UTF-8
  };

  child_process.exec(command, options, (error, stdout, stderr) => {
    if (error) {
      console.error(`Error executing command '${command}':`, error);
      callback(error);
      return;
    }

    let output = stdout;
    if (stderr) {
      output += '\n' + stderr;
    }

    callback(null, output);
  });
}

// Usage example:
