function listenToIframeEvents(iframe) {
  iframe.addEventListener('load', () => {
    const iframeSrc = iframe.src;
    const dataAutoplay = iframe.getAttribute('data-autoplay');

    function sendMessage() {
      const message = dataAutoplay
        ? iframeSrc.includes('video.html')
          ? 'playVideo'
          : iframeSrc.includes('slide.html')
            ? 'slide:start'
            : 'play'
        : 'messageHere'; // default message

      iframe.contentWindow.postMessage(message, '*');
    }

    if (dataAutoplay) {
      sendMessage();
    }

    iframe.addEventListener('message', (event) => {
      if (event.origin === '*') {
        console.log('Message received from iframe:', event.data);
      }
    });

    iframe.addEventListener('error', () => {
      console.error('Error loading iframe:', iframe.src);
    });
  });
}

// Usage:
const iframe = document.getElementById('myIframe');
listenToIframeEvents(iframe);
