    this.length = 0;
    this.__proto__ = Uint8Array.prototype;
  }

  BufferClass.prototype.write = function(buffer, offset, length) {
    if (offset < 0 || length < 0 || this.length + length > this.length) {
      throw new RangeError('Error writing Buffer');
    }

    Uint8Array.prototype.set.call(this, Uint8Array.prototype.subarray.call(buffer, offset, offset + length), this.length);
    this.length += length;

