use Doctrine\DBAL\Connection;

static function truncateTable(Connection $connection, string $tableName) {
    try {
        // Disable foreign key checks
        $connection->executeStatement('SET FOREIGN_KEY_CHECKS = 0 FOR TABLE ' . $tableName);

        // Truncate the table
        $connection->executeStatement('TRUNCATE TABLE ' . $tableName);

        // Reset auto-incrementing ID column
        $connection->executeStatement('ALTER TABLE ' . $tableName . ' AUTO_INCREMENT = 1');

        // Enable foreign key checks
        $connection->executeStatement('SET FOREIGN_KEY_CHECKS = 1');
    } catch (\Exception $e) {
        // Handle exceptions if needed
    }
}
