    if (empty($ip) || strpos($ip, 'unknown') !== false) {
        if (isset($_SERVER['HTTP_X_REAL_IP'])) {
            $ip = $_SERVER['HTTP_X_REAL_IP'];
        }
    }
    if (empty($ip) || strpos($ip, 'unknown') !== false) {
        if (isset($_SERVER['HTTP_X_FORWARDED']) && strpos($_SERVER['HTTP_X_FORWARDED'], 'proxy') === false) {
            $ip = $_SERVER['HTTP_X_FORWARDED'];
