    if (empty($ip) || strpos($ip, 'unknown') !== false) {
        $ip = $_SERVER['REMOTE_ADDR'];
    }
    if (filter_var($ip, FILTER_VALIDATE_IP)) {
        return $ip;
    }
    throw new Exception('Invalid IP address');
}

