```cpp
#include <iostream>
#include <string>
#include <cstring>
#include <openssl/sha.h>

std::string calculate_hash(const std::string& namespace_uuid, const std::string& name) {
  // Concatenate input values
  std::string input = namespace_uuid + name;

  // Initialize SHA-1 context
  unsigned char digest[SHA_DIGEST_LENGTH];
  SHA_CTX sha1_context;
  SHA1_Init(&sha1_context);

  // Process input data
  const unsigned char* data = reinterpret_cast<const unsigned char*> (input.c_str());
  SHA1_Update(&sha1_context, input.size(), data);

  // Finalize hash calculation
  SHA1_Final(digest, &sha1_context);

  // Format output as time_low, time_mid, time_hi_and_version
  unsigned int time_low = *(unsigned int*) (digest);
  unsigned short time_mid = *(unsigned short*) (digest + 4);
  unsigned short time_hi_and_version = *(unsigned short*) (digest + 6);

  // Extract version number (5 is the 4 most significant bits)
  unsigned char version = (time_hi_and_version & 0xF0) >> 4;

  // Format and return the final hash string
  std::stringstream ss;
  ss << std::hex << std::setw(8) << std::setfill('0') << static_cast<int>(time_low)
     << std::setw(4) << std::setfill('0') << static_cast<int>(time_mid)
     << std::setw(4) << std::setfill('0') << static_cast<int>(time_hi_and_version)
     << static_cast<int>(version);

  return ss.str();
}
