interface LockerInterface {
    public function write(string $hash);
}

class MockLocker implements LockerInterface {
    private $storedHashes = [];

    public function write(string $hash) {
        $this->storedHashes[] = $hash;
    }

    public function getStoredHashes() {
        return $this->storedHashes;
    }
}

function setupComposerAutoloaderWithMockLocker() {
    $mockLocker = new MockLocker();

    spl_autoload_register(function ($class) use ($mockLocker) {
        if (strpos($class, 'ComposerAutoload') === 0) {
            $reflector = new ReflectionClass($class);
            $constructor = $reflector->getConstructor();
            if ($constructor !== null && $constructor->getNumberOfParameters() > 0) {
                $args = $constructor->getArguments();
                if (is_array($args[0]) && isset($args[0]['locker'])) {
                    $args[0]['locker'] = $mockLocker;
                }
            }
            $reflector->newInstanceArgs($args);
        }
    });

    $autoload = new \Composer\Autoload\ClassLoader();
    $composer = new \Composer\Composer();
    $composer->setAutoloader($autoload);
    $composer->setLocker($mockLocker);
    $composer->install();
}
