function processRequest(&$requestBody, $contentLength, $boundary) {
    $chunkSize = 1024; // Define the chunk size
    $currentPosition = 0;
    $generatedBoundary = hash('sha256', microtime(true) . '_' . uniqid() . '_'); // Generate a new boundary string

    if ($generatedBoundary === false) {
        throw new Exception('Failed to generate boundary string.');
    }

    if ($boundary !== '') {
        if (substr($requestBody, 0, strlen($boundary) + 2) !== ($boundary . "\r\n")) {
            throw new Exception('Invalid boundary string in the request body.');
        }
        $currentPosition += strlen($boundary) + 2;
    }

    while ($currentPosition < $contentLength) {
        $nextChunk = substr($requestBody, $currentPosition, $chunkSize);
        $processedChunk = processChunk($nextChunk);
        $requestBody = substr_replace($requestBody, $processedChunk, $currentPosition, strlen($nextChunk));
        $currentPosition += strlen($processedChunk);
    }

    return $requestBody;

