        // Your custom processing logic for the chunk goes here
        // For example, you can add the chunk to a buffer, validate it, or generate a response

        // Generate the Content-Type header with the new boundary string
        $contentType = "multipart/form-data; boundary={$generatedBoundary}";

        // Return the processed chunk with the new Content-Type header
        return "--{$generatedBoundary}\r\nContent-Type: {$contentType}\r\n\r\n{$chunk}--{$generatedBoundary}\r\n";
    }
}
