function checkAndGetDiskUsage() {
    if (!function_exists('shell_exec') || !preg_match('/^df$/', trim(shell_exec('which df 2>/dev/null'))) {
        throw new Exception('The "df" command is not installed or not available in your system PATH.');
    }

    $output = shell_exec('df --human-readable');
    $lines = explode("\n", $output);
    $headerLineIndex = array_search('/^Total/, $lines);

    if ($headerLineIndex === false) {
        throw new Exception('Error getting disk usage information.');
    }

    $headerLine = $lines[$headerLineIndex];
    $header = explode(' ', $headerLine);

    $diskUsageInfo = [];
    for ($i = $headerLineIndex + 1; $i < count($lines); $i++) {
        $line = trim($lines[$i]);
        if (empty($line)) {
            continue;
        }

        $parts = explode(' ', $line);
        $mountPoint = $parts[0];
        $usage = [];

        for ($j = 1; $j < count($header); $j++) {
            $columnName = $header[$j];
            $columnValue = str_replace('%', '', $parts[$j]);
            $usage[$columnName] = $columnValue;
        }

        $diskUsageInfo[$mountPoint] = $usage;
    }

    return $diskUsageInfo;
}
