function authenticate_user($secret_string) {
    session_start();
    $remote_address = $_SERVER['REMOTE_ADDR'];
    $user_agent = $_SERVER['HTTP_USER_AGENT'];
    $secure_id = md5($secret_string . session_id() . $remote_address . $user_agent);

