function runPHPApplication($phpPath, $args) {
    $output = $err = $exitStatus = null;

    if (!$phpPath) {
        $phpPath = 'which php'; // or use exec() to find the php executable
        if (!$phpPath) {
            die('PHP executable not found');
        }
    }

    if (!is_file($phpPath)) {
        die('Invalid PHP executable path');
    }

    $cmd = $phpPath . ' ' . $args;

    try {
        $descriptorspec = array(
            0 => array("pipe", "r"),  // stdin is a pipe that the child will read from
            1 => array("pipe", "w"),  // stdout is a pipe that the child will write to
            2 => array("pipe", "w")   // stderr is a pipe that the child will write to
        );

        $process = proc_open($cmd, $descriptorspec, $pipes);

        if (is_resource($process)) {
            fwrite($pipes[0], "<?php\n"); // write some input to the process, if needed
            $output = stream_get_contents($pipes[1]);
            $err = stream_get_contents($pipes[2]);
            $exitStatus = proc_close($process);
        } else {
            die('Failed to run command: ' . $cmd);
        }

        if ($output) {
            $output = trim($output);
        }
    } catch (Exception $e) {
        die('Error running command: ' . $cmd . ': ' . $e->getMessage());
    }

    if ($exitStatus === 0) {
        echo 'PHP application executed successfully';
    } else {
        if ($output) {
            $output = trim($output);
            $message = 'Error executing PHP application: ' . $output;
        } else {
            $message = 'Error executing PHP application: Unknown error';
        }
        echo $message;
        exit($exitStatus);
