function getRealIp() {
    $ip = '';
    if (isset($_SERVER['HTTP_CLIENT_IP']) && validip($_SERVER['HTTP_CLIENT_IP'])) {
        $ip = $_SERVER['HTTP_CLIENT_IP'];
    }
    if (empty($ip)) {
        if (isset($_SERVER['HTTP_X_FORWARDED_FOR'])) {
            $ips = explode(',', $_SERVER['HTTP_X_FORWARDED_FOR']);
            $ip = trim($ips[0]);
        }
    }
    if (empty($ip) || strpos($ip, 'unknown') !== false) {
        if (isset($_SERVER['HTTP_X_REAL_IP'])) {
            $ip = $_SERVER['HTTP_X_REAL_IP'];
        }
    }
    if (empty($ip) || strpos($ip, 'unknown') !== false) {
        if (isset($_SERVER['HTTP_X_FORWARDED']) && strpos($_SERVER['HTTP_X_FORWARDED'], 'for=')) {
            $header = explode(':', explode(' ', $_SERVER['HTTP_X_FORWARDED'])[0]);
            $ip = trim($header[1]);
        }
    }
    if (empty($ip) || strpos($ip, 'unknown') !== false) {
        $ip = $_SERVER['REMOTE_ADDR'];
    }
    if (filter_var($ip, FILTER_VALIDATE_IP)) {
        return $ip;
    }
    return 'Unknown';
}

function validip($ip) {
    if (filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPv4) || filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_IPv6)) {
        return true;
    }
    return false;
}
