function perform_pingback($remote_url, $post_ID, $pagelinkedfrom) {
    global $wpdb;

    // Check if the URL is pingback-enabled
    if (!pings_open($post_ID)) {
        return 'The specified target URL cannot be used as a target. It either doesn\'t exist, or it is not a pingback-enabled resource.';
    }

    // Check if the remote site already pinged this entry
    if ($wpdb->get_results($wpdb->prepare("SELECT * FROM $wpdb->comments WHERE comment_post_ID = %d AND comment_author_url = %s", $post_ID, $pagelinkedfrom))) {
        return 'The pingback has already been registered.';
    }

    // Sleep for 1 second
    sleep(1);

    // Get remote IP address
    $remote_ip = preg_replace('/[^0-9a-fA-F:., ]/', '', $_SERVER['REMOTE_ADDR']);

    // Get user agent
    $user_agent = apply_filters('http_headers_useragent', 'WordPress/' . $GLOBALS['wp_version'] . '; ' . get_bloginfo('url'));

    // Prepare HTTP request arguments
    $http_api_args = array(
        'timeout' => 10,
        'redirection' => 0,
        'limit_response_size' => 153600, // 150 KB
        'user-agent' => $user_agent,
        'headers' => array(
            'X-Forwarded-For' => $remote_ip,
        ),
    );

    // Perform the HTTP request
    $response = wp_remote_get($remote_url, $http_api_args);

    // Check for errors in the response
    if (is_wp_error($response)) {
        return 'Error occurred while trying to ping the remote URL: ' . $response->get_error_message();
    }

    // Check if the response code is 200 (OK)
    if (wp_remote_retrieve_response_code($response) != 200) {
        return 'The remote URL did not return a valid response.';
    }

    // If everything is fine, return success
    return 'Pingback performed successfully.';
}
