function loadScriptsAndSetupSharingButton(cdn1, file1, cdn2, file2, apiKey, publisher, options) {
  const head = document.getElementsByTagName('head')[0];

  // Create and insert script tag for the first CDN file
  const script1 = document.createElement('script');
  script1.src = cdn1 + file1;
  head.appendChild(script1);

  // Create and insert script tag for the second CDN file and setup mapping API
  const script2 = document.createElement('script');
  script2.src = cdn2 + file2;
  script2.async = true;
  script2.onload = () => {
    // Initialize mapping API with provided API key
    if (apiKey) {
      (window as any).initMapbox = () => {
        (window as any).mapboxgl.accessToken = apiKey;
      };
    }
  };
  head.appendChild(script2);

  // Setup sharing button with provided publisher and options
  const script3 = document.createElement('script');
  script3.src = 'https://platform.social.com/assets/js/social.js';
  script3.async = true;
  script3.onload = () => {
    (window as any).Social.init({
      publisher: publisher,
      options: options,
    });
  };
  head.appendChild(script3);
}
