function shuffleList(list, seed = null) {
  let rng;
  if (seed) {
    rng = new Math.seedrandom(seed);
  } else {
    rng = Math.random; // Default seed
  }

  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [list[i], list[j]] = [list[j], list[i]];
  }

  return list;
}
