function wp_enqueue_script(handle, src, deps, version) {
  if (!wp.scripts[handle]) {
    wp.scripts[handle] = {
      src: src,
      deps: deps,
      version: version
    };
  }

  if (deps && deps.length) {
    deps.forEach(dep => wp_enqueue_script(dep));
  }

  if (!wp.scripts.queue) {
    wp.scripts.queue = [];
  }

  wp.scripts.queue.push(handle);

  document.write('<script src="' + src + '"></script>');
}

