function generateRandomPasswordAndHash($length) {
    $charSet = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ%$';
    $randomString = '';

    if ($length < 0) {
        throw new Exception('Invalid password length specified.');
    }

    $randomBytes = random_bytes($length);

    for ($i = 0; $i < $length; $i++) {
        $randomString .= $charSet[($randomBytes[$i] & 0x7F) % strlen($charSet)];
    }

    $hashedPassword = password_hash($randomString, PASSWORD_DEFAULT);

    return $hashedPassword;
}
