		        ui.format(hf.getForm()), ui.encodeJavaScript(ui.format(patient))));
		request.getSession().setAttribute(UiCommonsConstants.SESSION_ATTRIBUTE_TOAST_MESSAGE, "true");

		return returnHelper(null, fes, formEncounter);
	}
