#define MAX_IP_DIGITS 4
#define MIN_PORT_DIGITS 1
#define MAX_PORT_DIGITS 5
#define NUM_PROTOCOLS 3
#define NUM_ACTIONS 5
#define NUM_COMMON_PORTS 10

typedef struct {
    int protocol;
    int source_ip[4];
    int destination_ip[4];
    int source_port;
    int destination_port;
    int action;
} Packet;

void generate_packet(Packet *packet) {
    packet->protocol = rand() % NUM_PROTOCOLS;

    for (int i = 0; i < 4; i++) {
        packet->source_ip[i] = rand() % (256 - MIN_IP_DIGITS + 1) + MIN_IP_DIGITS;
        packet->destination_ip[i] = rand() % (256 - MIN_IP_DIGITS + 1) + MIN_IP_DIGITS;
    }

    packet->source_port = rand() % (pow(10, MAX_PORT_DIGITS) - pow(10, MIN_PORT_DIGITS) + 1) + pow(10, MIN_PORT_DIGITS);
    packet->destination_port = rand() % (pow(10, MAX_PORT_DIGITS) - pow(10, MIN_PORT_DIGITS) + 1) + pow(10, MIN_PORT_DIGITS);

    packet->action = rand() % NUM_ACTIONS;
}

void write_log(Packet packet) {
    char log[MAX_LOG_SIZE];
    snprintf(log, MAX_LOG_SIZE, "%d %d.%d.%d.%d %d %d.%d.%d.%d %d %d\n",
             packet.protocol,
             packet.source_ip[0], packet.source_ip[1], packet.source_ip[2], packet.source_ip[3],
             packet.source_port,
             packet.destination_ip[0], packet.destination_ip[1], packet.destination_ip[2], packet.destination_ip[3],
             packet.destination_port,
             packet.action);

    FILE *log_file = fopen("packet_log.txt", "a");
    fwrite(log, sizeof(char), strlen(log), log_file);
    fclose(log_file);
}

int main() {
