import hashlib

def read_chunk(file_like_object, chunk_size=32768):
    """Read a chunk of given size from file-like object."""
    return file_like_object.read(chunk_size)

def sha1_file_hash(file_like_object):
    """Return SHA1 hash of file-like object's contents."""
    hash_obj = hashlib.sha1()
    while True:
        data = read_chunk(file_like_object)
        if not data:
            break
        hash_obj.update(data)
    return hash_obj.hexdigest()

