import subprocess
import sys

def run_command(command, args=None, log_output=False):
    """
    Execute the given command with optional arguments using subprocess.
    Returns a tuple containing the exit code and output (or error message).
    """
    if args is None:
        cmd = command
    else:
        cmd = f"{command} {' '.join(args)}"

    try:
        if not log_output:
            output, error = subprocess.getstatusoutput(cmd)
            return output.splitlines(), int(error) if error else None

        process = subprocess.Popen(
            cmd,
            shell=False,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            universal_newlines=True,
        )

        output = ""
        while process.poll() is None:
            line = process.stdout.readline().decode("utf-8")
            output += line

        exit_code = process.poll()
        return output.splitlines(), exit_code

    except FileNotFoundError:
        return "Command not found.", 127
    except subprocess.CalledProcessError as e:
