CREATE OR REPLACE FUNCTION create_and_drop_table() RETURNS VOID AS $$
DECLARE
    table_name TEXT;
    conn TEXT;
    query TEXT;
BEGIN
    -- Create table
    table_name := 'temp_table';
    query := 'CREATE TABLE ' || table_name || ' (id INT PRIMARY KEY, value TEXT)';
    EXECUTE query;

    -- Insert data
    query := 'INSERT INTO ' || table_name || ' VALUES (1, ''example1''), (2, ''example2'')';
    EXECUTE query;

    -- Cursor to drop table
    DECLARE drop_table CURSOR FOR SELECT name FROM pg_catalog.pg_tables WHERE tablename = table_name;
    OPEN drop_table;

    -- Drop table
    DECLARE done BOOLEAN;
    DECLARE cont CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    LOOP
        FETCH drop_table INTO table_name;
        IF NOT done THEN
            query := 'DROP TABLE ' || table_name;
            EXECUTE query;
        END IF;
        EXIT WHEN done;
    END LOOP;
    CLOSE drop_table;

    -- Close connection
    conn := 'dbname=your_database user=your_user password=your_password';
    PERFORM pg_terminate_backend(pg_stat_activity.pid) WHERE pg_stat_activity.datname = 'your_database' AND pg_stat_activity.query LIKE '%create_and_drop_table%';
    PERFORM pg_sleep(1); -- Wait for the connection to be closed
    PERFORM pg_connect(conn);
    PERFORM pg_terminate_backend(pg_backend_pid()); -- Terminate the current connection
END;
$$ LANGUAGE plpgsql;
