import os
import hashlib

def read_file(file_path):
    with open(file_path, 'r') as file:
        return file.read()

def write_file(file_path, content):
    with open(file_path, 'w') as file:
        file.write(content)

def compute_file_hash(file_path):
    with open(file_path, 'rb') as file:
        return hashlib.md5(file.read()).hexdigest()

def process_files(column_file, row_file):
    columns = [line.strip().split(',') for line in read_file(column_file).splitlines()]
    rows = [line.strip().split(',') for line in read_file(row_file).splitlines()]

    differences = []

    for column in columns:
        for row in rows:
            if column not in rows:
                differences.append(f"Column {column} not found in rows.")
                continue
            if row not in columns:
                differences.append(f"Row {row} not found in columns.")
                continue
            if hashlib.md5(read_file(os.path.join('input', column[0])).read()).hexdigest() != row[0]:
                differences.append(f"Mismatch between column {column[0]} and row {row[0]}.")

    return differences

def remove_files(file_paths):
    for file_path in file_paths:
        if os.path.exists(file_path) and 'to_remove' in file_path:
            os.remove(file_path)

def create_directory(directory_path):
    os.makedirs(directory_path, exist_ok=True)

def main():
