import os
import subprocess

def copy_file(src_file, dest_file, basedir):
 try:
  subprocess.check_call(["cp", src_file, os.path.join(basedir, dest_file)])
 except subprocess.CalledProcessError as e:
  print(f"Error copying file {src_file} to {dest_file}: {e}")
  raise Exception(f"Failed to copy file {src_file} to {dest_file}")

def modify_file(file_path, search, replace, basedir):
 try:
  with open(os.path.join(basedir, file_path), "r+") as file:
    content = file.read()
    file.seek(0)
    file.truncate()
    new_content = content.replace(search, replace)
    file.write(new_content)
 except FileNotFoundError:
  print(f"File {os.path.join(basedir, file_path)} not found")
  raise Exception(f"File {file_path} not found")
 except Exception as e:
  print(f"Error modifying file {file_path}: {e}")
  raise Exception(f"Failed to modify file {file_path}")

def set_timezone(basedir, timezone):
 try:
  subprocess.check_call(["ln", "-sf", timezone, "/etc/localtime"])
 except subprocess.CalledProcessError as e:
  print(f"Error setting timezone to {timezone}: {e}")
  raise Exception(f"Failed to set timezone to {timezone}")

def main():
 basedir = "/path/to/kickstart"
 hostname = subprocess.check_output(["hostname", "-s"], universal_newlines=True)

 try:
  copy_file("ks.cfg.template", "ks.cfg", basedir)
  modify_file("ks.cfg", "HOSTNAME", hostname, basedir)
  modify_file("ks.cfg", "BASEURL", "http://kickstart.server/content/", basedir)
  set_timezone(basedir, "/usr/share/zoneinfo/America/New_York")
  print("Configuration file created successfully.")
 except Exception as e:
  print("Error creating configuration file:")
  print(e)
  raise e

if __name__ == "__main__":
 main()
