import hashlib

class HashObject:
    def __init__(self, data, algorithm="sha256"):
        self.data = data
        self.algorithm = algorithm
        self.hash = self.compute_hash()

    def clone(self):
        return HashObject(self.data, self.algorithm)

    def compute_hash(self):
        hash_obj = hashlib.new(self.algorithm)
        hash_obj.update(self.data.encode())
