import numpy as np
import scipy.stats as stats

def percentile_function(distribution_name, values):
    try:
        if distribution_name in ["normal", "uniform", "expon", "weibull", "poisson"]:
            ppf = getattr(stats, distribution_name).ppf
        else:
            raise ValueError("Invalid distribution name")

        percentiles = np.array(values)
        return np.array([ppf(x) for x in percentiles])

    except AttributeError:
        def custom_percentile(x, q):
            if q < 0 or q > 1:
                raise ValueError("Invalid percentile")

            if len(values) == 0:
                return np.nan

            # Sort the values in ascending order
            sorted_values = np.sort(values)

            # Determine the index of the value at the desired percentile
            index = int(np.searchsorted(sorted_values, q, side="right") - 1)

            # Interpolate if the desired percentile is between two values
            if q > np.round(q, decimals=3):
                index += 1
                value = sorted_values[index]
                next_value = sorted_values[index + 1]
                ppf = (value + next_value) / 2

            return ppf

        percentiles = np.array(values)
        return np.array([custom_percentile(x, q) for x, q in zip(percentiles, values)])
