import subprocess
import re
import string
from collections import defaultdict

def extract_text_from_pdf(pdf_file):
    try:
        result = subprocess.check_output(["pdftotext", "-layout", pdf_file], universal_newlines=True)
        return result
    except subprocess.CalledProcessError as e:
        print(f"Error extracting text from PDF: {e}")
        return ""

def tokenize(text):
    tokens = re.findall(r'\w+|[.,!?;:()]', text.lower())
    return [token for token in tokens if token in string.punctuation or token.isalpha()]

def create_bag_of_words(tokens):
    bag = defaultdict(int)
    for token in tokens:
        bag[token] += 1
    return dict(bag)

def save_to_file(bag, filename):
    with open(filename, 'w') as f:
        for word, count in bag.items():
            f.write(f"{word}:{count}\n")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python script.py <pdf_file>")
        sys.exit(1)

    pdf_file = sys.argv[1]
    text = extract_text_from_pdf(pdf_file)
    tokens = tokenize(text)
    bag = create_bag_of_words(tokens)
    save_to_file(bag, "bag_of_words.txt")
```

