import warnings

def deprecate(old_name, new_name, version=1):
    def warn(self, *args, **kwargs):
        warnings.warn(
            f"The '{old_name}' attribute is deprecated, "
            f"use '{new_name}' instead (version {version})",
            DeprecationWarning,
            stacklevel=2,
        )

    def getter(self):
        return self.__getattribute__(new_name)

    def setter(self, value):
        self.__setattr__(new_name, value)

    property.__decorator__ = property
    new_property = property(getter=getter, setter=setter)

    class DeprecatedAttribute:
        def __init__(self, obj, name):
            self.obj = obj
            self.name = name

        def __getattr__(self, item):
            return getattr(self.obj, old_name)

        def __setattr__(self, key, value):
            setattr(self.obj, new_name, value)
            self.obj.__dict__[old_name] = value

    return DeprecatedAttribute(self, old_name), new_property

def deprecate_attribute(cls, old_name, new_name, version=1):
    old_attr, new_attr = deprecate(old_name, new_name, version)
    setattr(cls, old_name, property(fget=old_attr.__get__))
    setattr(cls, new_name, new_attr)
