CREATE FUNCTION create_and_lock_table(lock_name VARCHAR) RETURNS INT AS $$
DECLARE
  unique_name1 VARCHAR = 'unique_name_1';
  unique_name2 VARCHAR = 'unique_name_2';
  duplicate_name VARCHAR = 'duplicate_name';
  pk INT PRIMARY KEY AUTOINCREMENT;
  table_name VARCHAR;
  rows_affected INT;
BEGIN
  table_name := 'your_table_name';
  CREATE TABLE IF NOT EXISTS your_table_name (
    pk INT PRIMARY KEY AUTOINCREMENT
  );

