  BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  FOR i IN (SELECT 1 FROM your_table_name FOR UPDATE OF your_table_name WHERE name NOT IN (SELECT name FROM your_table_name WHERE name IN (unique_name1, unique_name2)) LOCK IN COMPATIBILITY MODE) LOOP
    IF NOT EXISTS (SELECT 1 FROM your_table_name WHERE name = lock_name) THEN
      INSERT INTO your_table_name (name) VALUES (lock_name);
      COMMIT;
      EXIT;
    END IF;
  END LOOP;

  -- Insert two rows with unique names
  INSERT INTO your_table_name (name) VALUES (unique_name1);
  INSERT INTO your_table_name (name) VALUES (unique_name2);
  SET rows_affected = rows_affected + ROW_COUNT();

  -- Insert a third row with a non-unique name and raise an OperationalError if attempting to do so without the lock
  IF lock_name IS NOT NULL THEN
    BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
    FOR i IN (SELECT 1 FROM your_table_name FOR UPDATE OF your_table_name WHERE name = duplicate_name LOCK IN COMPATIBILITY MODE) LOOP
      IF NOT EXISTS (SELECT 1 FROM your_table_name WHERE name = lock_name) THEN
        INSERT INTO your_table_name (name) VALUES (duplicate_name);
        COMMIT;
        EXIT;
      END IF;
    END LOOP;
    RAISE OPERATIONAL ERROR 'Cannot insert row with non-unique name without the lock';
  END IF;

  -- Release the lock
  COMMIT;

  RETURN rows_affected;
END;
$$ LANGUAGE plpgsql;
