import os
import pickle

class FileSystemOperations:
    def __init__(self, filename):
        self.filename = filename
        self.file = None
        self.data = None
        self.exception = None

    def create_file(self):
        try:
            self.file = open(self.filename, 'wb')
        except IOError as e:
            self.exception = e

    def read_file(self):
        if not self.file:
            return
        self.data = self.file.read()
        self.file.close()

    def raise_exception(self):
        del self.file
        os.remove(self.filename)
        raise IOError("File does not exist")

    def pickle_file(self):
        if not self.file:
            self.create_file()
        self.data = "Pickled data"
        try:
            with open(self.filename, 'wb') as f:
                pickle.dump(self.data, f)
        except Exception as e:
            self.exception = e

    def __del__(self):
        if self.file:
            self.file.close()
        if self.data:
            del self.data
        if self.exception:
            raise self.exception
        os.remove(self.filename)

if __name__ == "__main__":
    file_ops = FileSystemOperations("test.txt")
    file_ops.create_file()
    file_ops.pickle_file()
    file_ops.read_file()
    print(file_ops.data)
    file_ops.raise_exception()
