def parse_template(template, tokens):
    pattern = re.compile(r'(\{\{(.*?)(\|(.*?))?\}})|(\$(\{([\w]+)(?:(\[(\d+)\])|(?:(\[(\w+)\]))?))?)')

    def convert_token(token):
        if token[0] == '$':
            name, index = token[1:]
            return ' locals["{}"]'.format(name) if index is None else ' locals["{}"][]'.format(name)
        return '{}'.format(token[1])

    syntax_rules = {
        'print': 'print',
        'sum': 'lambda _n: sum(_n)',
        'len': 'len'
    }

    def compile_lambda(tokens):
        body = []
        i = 0

        while i < len(tokens):
            match = pattern.match(template[i:])
            if not match:
                raise Exception('Invalid template string')

            token = match.group(1)
            if token[0] == '{' and token[1:].startswith('{'):
                sub_tokens = []
                i += len(match.group(0))
                while i < len(template) and not template[i].isalnum():
                    i += 1
                sub_template = template[i - len(match.group(0)):i]
                sub_tokens += parse_template(sub_template, [])
                body.append('({})'.format(' '.join(map(convert_token, sub_tokens))))
                i += len(sub_template)
            else:
                body.append(convert_token(token))
                i += len(match.group(0))

            if token[0] == '}' and token[1:] in syntax_rules:
                body.insert(0, syntax_rules[token[1:]])

        return 'lambda _n: {}({})'.format(' '.join(body), '_n')

    parsed_tokens = re.findall(pattern, template)
    tokens += parsed_tokens

    return compile_lambda(tokens)

def safe_eval_lambda(template, locals={}):
    compiled_lambda = parse_template(template, [])
    return eval(compiled_lambda, locals)
