import sqlite3

def get_row_counts(table_names):
    try:
        conn = sqlite3.connect(":memory:")  # Create an in-memory database

        for table_name in table_names:
            table = conn.cursor().execute(f"CREATE TABLE {table_name}(id INTEGER PRIMARY KEY)").table_info()
            if not table:
                raise ValueError(f"Table '{table_name}' not found")

            row_count = conn.cursor().execute(f"SELECT COUNT(*) FROM {table_name}").fetchone()[0]

            if row_count == 0:
                raise ZeroDivisionError(f"Table '{table_name}' has zero rows")

        row_counts = [(table_name, row_count) for table_name, row_count in ((table_name, row_count) for table_name in table_names if row_count > 0)]
        return row_counts

    except sqlite3.Error as e:
        raise e

    finally:
        conn.close()
