import os
import re
import shelve
import stemmer
import urllib.parse

class Indexer:
    def __init__(self, directory_path):
        self.directory_path = directory_path
        self.shelves = {}

    def startIndexer(self):
        self.shelves = {
            'invertedIndex': shelve.open(f'{self.directory_path}/invertedIndex.db'),
            'forwardIndex': shelve.open(f'{self.directory_path}/forwardIndex.db'),
            'idToUrl': shelve.open(f'{self.directory_path}/idToUrl.db')
        }

    def finishIndexer(self):
        for shelf in self.shelves.values():
            shelf.close()

    def build_index(self):
        for file in os.listdir(self.directory_path)::
            if not file.endswith('.txt'):
                continue
            file_path = os.path.join(self.directory_path, file)
            text = open(file_path, 'r').read()
            url = urllib.parse.urlparse(file).path
            document_id = file

            self.shelves['forwardIndex'][document_id] = text
            self.shelves['idToUrl'][document_id] = url

            words = re.findall(r'\w+', text.lower())
            stemmed_words = [stemmer.stem(word) for word in words]

            for word in stemmed_words:
                if not self.shelves['invertedIndex'].get(word, None):
                    self.shelves['invertedIndex'][word] = []
                self.shelves['invertedIndex'][word].append(document_id)

# Example usage:
indexer = Indexer('/path/to/text/documents')
indexer.startIndexer()
indexer.build_index()
indexer.finishIndexer()
