import os
import bundleresolver.bundle_context as bundle_context

CACHE_FILE = "cache.txt"

def read_cache():
    if not os.path.exists(CACHE_FILE):
        return {}
    with open(CACHE_FILE, "r") as file:
        cache = {}
        for line in file:
            bundle_name, image_types = line.strip().split(":")
            cache[bundle_name] = image_types.split(",")
        return cache

def write_cache(cache):
    with open(CACHE_FILE, "w") as file:
        for bundle_name, image_types in cache.items():
            file.write(f"{bundle_name}:{','.join(image_types)}\n")

def search_images(bundle_name, image_types):
    cache = read_cache()
    bundle_context_instance = bundle_context.BundleContext()
    images = []

    if bundle_name not in cache:
        cache[bundle_name] = image_types
        write_cache(cache)

    for entry in bundle_context_instance.get_entries(bundle_name):
        path = entry.path
        ext = os.path.splitext(path)[1]
        if ext.lower() in image_types:
            images.append(path)

    return images
