import hashlib

def generate_md5_hash(request, delta=None):
    if not isinstance(request, dict):
        raise TypeError("Expected request object to be a dictionary")

    params = {k: v for k, v in request.items() if not k.startswith("_")}
    sorted_params = dict(sorted(params.items()))
    params_str = ", ".join(sorted_params.keys())
    message = params_str.encode() + delta.encode() if delta else params_str.encode()
    hash_object = hashlib.md5(message)
    return hash_object.hexdigest()

    # Optional delta parameter implementation
    if delta:
        import time
        return generate_md5_hash(request, int(time.time() * 1000))
