import subprocess

def execute_command(command, mode="r", timeout=None):
    if not command:
        return

    try:
        process = subprocess.Popen(
            args=command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            shell=True,
            universal_newlines=True,
        )

        if timeout is not None:
            process.communicate(timeout=timeout)

        if process.returncode != 0:
            raise RuntimeError(f"Command '{command}' returned non-zero exit status ({process.returncode})")

        if mode == "r":
            return process.stdout
        elif mode == "w":
            process.stdin = open(mode, "w+")
            process.communicate(input="your_input_here\n")
            process.stdin.close()
            return process.stdout
        else:
            raise ValueError("Invalid mode: {}".format(mode))

    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Command '{command}' returned error: {e}")
