import hashlib

def calculate_file_sha1(file_path, buffer_size=65536):
    hasher = hashlib.sha1()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(buffer_size), b''):
            hasher.update(chunk)
    return hasher.hexdigest()
