class InputIterator:
    def __init__(self, file_path=None, bucket_name=None, fail_on_missing=False):
        self.file_path = file_path
        self.bucket_name = bucket_name
        self.fail_on_missing = fail_on_missing
        self.iterator = None
        self.s3 = None

    def load_from_file(self):
        if self.file_path is None:
            if self.fail_on_missing:
                raise ValueError("File path is None")
            return
        with open(self.file_path, 'r') as file:
            self.iterator = self._json_iterator(json.load(file))

    def load_from_s3(self):
        if self.bucket_name is None:
            if self.fail_on_missing:
                raise ValueError("Bucket name is None")
        self.s3 = boto3.client('s3')
        obj = self.s3.get_object(Bucket=self.bucket_name, Key=self.file_path)
        self.iterator = self._json_iterator(json.loads(obj['Body'].read().decode()))

    def _json_iterator(self, data):
        return (item for item in data)

    def to_json(self, obj):
        return json.dumps(obj)

    def to_json_string(self, obj):
        return json.dumps(obj, ensure_ascii=False).encode()

    def __iter__(self):
        if self.iterator is None:
            raise ValueError("Iterator not initialized")
        return self.iterator
