import sys
from PyQt5.QtWidgets import QInputDialog, QApplication
import os

def get_ffmpeg_command():
    initial_value = "ffmpeg -i input.mp4 output.mp4"
    text, ok = QInputDialog.getText(None, 'Command', 'Command:', text=initial_value)
    if ok:
        return text

def run_command(command):
    os.system(command)

def remove_files(patterns):
    for pattern in patterns:
        for file in glob.glob(pattern):
            os.remove(file)

def update_counter(files):
    counter = 0
    for file in files:
        counter += 1
        yield counter

def process_files(patterns):
    files = []
    for pattern in patterns:
        for file in glob.glob(pattern):
            files.append(file)
    return files

def main():
    patterns = ['*.mp4', '*.avi']
    for pattern in patterns:
        remove_files(pattern)

    command = get_ffmpeg_command()
    run_command(command)

    files = process_files(patterns)
    counter = update_counter(files)
    print('Processing files...')
    for i in counter:
        print(f'Frame {i} processed')

if __name__ == '__main__':
    QApplication.instance().quit()
    main()
