import hashlib
import random

class RegistrationProfile:
    def __init__(self, user, activation_key):
        self.user = user
        self.activation_key = activation_key

def create_registration_profile(user, salt=None):
    if not salt:
        salt = ''.join(str(random.randint(0, 9)) for _ in range(10))

    username = user['username']
    activation_key = hash_and_generate_activation_key(username, salt)

    return RegistrationProfile(user, activation_key)

def hash_and_generate_activation_key(username, salt):
    data = username.encode('utf-8') + salt.encode('utf-8')
    hash_object = hashlib.sha1(data)
    activation_key = hash_object.hexdigest()
    return activation_key
```

