CONF_URL = "https://api-m.sandbox.paypal.com/v1/oauth2/token/authorize"

app.config["PAYPAL_CLIENT_ID"] = "your_client_id"
app.config["PAYPAL_SECRET"] = "your_secret"

paypal = requests.auth.HTTPBasicAuth(app.config["PAYPAL_CLIENT_ID"], app.config["PAYPAL_SECRET"])

def get_paypal_access_token(code):
    token_url = "https://api-m.sandbox.paypal.com/v1/oauth2/token"
    data = {
        "grant_type": "authorization_code",
        "code": code,
    }
    response = requests.post(token_url, auth=paypal, data=data)
    if response.status_code != 200:
        logger.warning("Failed to get access token from PayPal")
        return None
    return response.json()

@paypal_bp.route("/<client_id>/paypal", methods=["GET"])
def paypal_form(client_id):
    return render_template("paypal_form.html", client_id=client_id)

@paypal_bp.route("/paypal/process", methods=["POST"])
def process_payment():
    client_id = request.form["client_id"]
    code = request.form["code"]

    access_token = get_paypal_access_token(code)
    if access_token is None:
        abort(500)

    response = requests.get(
        "https://api-m.sandbox.paypal.com/v1/payments/payment/create",
        auth=paypal,
        headers={"Content-Type": "application/json"},
        json={
            "intent": "sale",
            "payer": {
                "payment_method_specified": True,
                "payment_method": {
                    "type": "paypal",
                },
            },
            "transactions": [
                {
                    "item_list": {
                        "items": [
                            {
                                "name": "Your product name",
                                "sku": "Your product SKU",
                                "price": "Your product price",
                                "currency": "USD",
                                "quantity": 1,
                            },
                        ],
                    },
                    "amount": {
                        "currency": "USD",
                        "total": "Your product price",
                    },
                },
            ],
        },
    )

    if response.status_code != 201:
        abort(500)

    payment_id = response.json()["id"]

    # Redirect user to PayPal for login and payment completion
    redirect_url = response.json()["links"][1]["href"]
    return redirect(redirect_url)

@paypal_bp.route("/paypal/success/<payment_id>")
def payment_success(payment_id):
    response = requests.get(
        f"https://api-m.sandbox.paypal.com/v1/payments/payment/{payment_id}",
        auth=paypal,
    )

    if response.status_code != 200:
        abort(500)

    if response.json()["state"] != "approved":
        abort(403)

    flash("Payment successful!")
    return "Payment successful!"

app.register_blueprint(paypal_bp)
