import importlib.util, os, sys, importlib

class CustomExtension:
    def __init__(self, filepath):
        self.filepath = filepath

    def load(self):
        try:
            spec = importlib.util.spec_from_file_location(self.filepath.stem, self.filepath)
            self.module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(self.module)
        except FileNotFoundError:
            print(f"Error: Extension file '{self.filepath}' not found.")
            self.module = None
        except Exception as e:
            print(f"Error loading extension '{self.filepath}': {e}")
            self.module = None

    def extend_path(self, pythonpath, root_dir):
        if self.module and hasattr(self.module, 'Extend'):
            try:
                extended_path = self.module.Extend(pythonpath, root_dir)
                return extended_path
            except Exception as e:
                print(f"Error executing extension function: {e}")
        return pythonpath

def load_extension(filepath, pythonpath, root_dir):
    extension = CustomExtension(filepath)
    pythonpath = extension.extend_path(pythonpath, root_dir)
    return pythonpath
