import hashlib
import os
import random

def hash_message(message, hash_function='sha256', salt=None):
    if salt is None:
        salt = os.urandom(16)

    if hash_function in ['md5', 'sha1', 'sha256']:
        if hash_function == 'md5':
            hash_obj = hashlib.md5()
        elif hash_function == 'sha1':
            hash_obj = hashlib.sha1()
        else:
            hash_obj = hashlib.sha256()

        if salt:
            message = message.encode() + salt
            hash_obj.update(message)
            result = hash_obj.hexdigest()
        else:
            hash_obj.update(message.encode())
            result = hash_obj.hexdigest()

    else:
        raise ValueError(f"Invalid hash function: {hash_function}")

    return result
