use std::result::Result;
use std::sync::mpsafe::Sync;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

#[derive(Debug)]
struct SendError<T>(T);

struct OneshotChannel<T> {
    sender: Arc<Sync<Option<thread::Sender<T>>>>,
    receiver: Arc<Sync<Option<thread::Receiver<T>>>>,
}

impl<T> OneshotChannel<T> {
    fn new() -> Self {
        let (sender, receiver) = thread::channel();
        OneshotChannel {
            sender: Arc::new(Sync::from(Some(sender))),
            receiver: Arc::new(Sync::from(Some(receiver))),
        }
    }

    fn send(&self, value: T) -> Result<(), SendError<T>> {
        match self.sender.take() {
            Some(sender) => {
                if sender.send(value).is_err() {
                    Err(SendError(value))
                } else {
                    self.receiver.take().map(|receiver| receiver.recv()).map_err(|_| SendError(value))
                }
            }
            None => Err(SendError(value)),
        }
    }
}

impl<T> Drop for OneshotChannel<T> {
    fn drop(&mut self) {
        if let Some(sender) = self.sender.take() {
            drop(sender);
        }
    }
}

fn oneshot_channel<T>() -> OneshotChannel<T> {
    OneshotChannel::new()
}
