fn create_joystick_state(button_caps: Vec<(&String, &String)>, value_caps: Vec<(&String, f32)>) -> JoystickState {
    let mut buttons: Vec<JoystickButton> = Vec::new();
    let mut hat_switch = JoystickHatSwitch {
        up: false,
        down: false,
        left: false,
        right: false,
    };

    for (button_name, button_state) in button_caps {
        buttons.push(JoystickButton {
            name: button_name.to_string(),
            state: button_state.parse::<bool>().unwrap(),
        });
    }

    for (axis_name, axis_value) in value_caps {
        match axis_name {
            "X" => {
                hat_switch.x = axis_value;
            }
            "Y" => {
                hat_switch.y = axis_value;
            }
            "HatSwitchUp" => {
                hat_switch.up = axis_value > 0.5;
            }
            "HatSwitchDown" => {
                hat_switch.down = axis_value < -0.5;
            }
            "HatSwitchLeft" => {
                hat_switch.left = axis_value < -0.5;
            }
            "HatSwitchRight" => {
                hat_switch.right = axis_value > 0.5;
            }
            _ => {}
        }
    }

    JoystickState {
        axis: JoystickAxis {
            x: hat_switch.x,
            y: hat_switch.y,
        },
        buttons,
        hat_switch,
    }
}
