class DatabaseWithColumnFamilies {
private:
    std::string db_path;
    std::string column_family_name;
    std::unique_ptr<rocksdb::DB> db;
    std::unique_ptr<rocksdb::ColumnFamilyDescriptor> cf_desc;
    std::unique_ptr<rocksdb::ColumnFamilyHandle> cf;

public:
    DatabaseWithColumnFamilies(const std::string& db_path, const std::string& column_family_name)
        : db_path(db_path), column_family_name(column_family_name) {}

    void create() {
        rocksdb::Status status;
        db = std::make_unique<rocksdb::DB>(db_path.c_str(), nullptr);
        if (!db) {
            std::cerr << "Failed to create database: " << status.ToString() << std::endl;
            return;
        }

        cf_desc = std::make_unique<rocksdb::ColumnFamilyDescriptor>(column_family_name.c_str());
        cf = std::make_unique<rocksdb::ColumnFamilyHandle>(db.get(), cf_desc.get());
        if (!cf) {
            std::cerr << "Failed to create column family: " << status.ToString() << std::endl;
            db.reset();
            return;
        }
    }

    ~DatabaseWithColumnFamilies() {
        if (cf) {
            cf.reset();
        }
        if (db) {
            db.reset();
        }
    }
};

int main(int argc, char** argv) {
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <database_path> <column_family_name>" << std::endl;
        return 1;
    }

    std::string db_path = argv[1];
    std::string column_family_name = argv[2];

    DatabaseWithColumnFamilies db_cf(db_path, column_family_name);
    db_cf.create();

    // Use the database and column family here

    db_cf.~DatabaseWithColumnFamilies();

    return 0;
}
