use std::ffi::CStr;

fn get_library_version(library: &CStr) -> (u64, String) {
    let version_ptr = library.as_ptr().add(library.as_bytes().len() - 10); // assuming version number is in format "X.Y.Z" and is located at the end of the library name
    let version_str = unsafe { CStr::from_ptr(version_ptr) };
    let version_vec: Vec<&str> = version_str.splitn(3, ".").collect();

    let mut major = 0;
    let mut minor = 0;
    let mut patch = 0;

    if version_vec.len() >= 1 {
        major = version_vec[0].parse::<u64>().unwrap_or(0);
    }
    if version_vec.len() >= 2 {
        minor = version_vec[1].parse::<u64>().unwrap_or(0);
    }
    if version_vec.len() >= 3 {
        patch = version_vec[2].parse::<u64>().unwrap_or(0);
    }

    let hex_version = (major as u64) << 16 | (minor as u64) << 8 | patch as u64;
    let string_version = format!("{}.{}.{}", major, minor, patch);

    (hex_version, string_version)
}
