unsafe fn UINT16_Marshal<T: Copy>(value: &T, buffer: *mut u8, size: *mut isize) -> isize {
    let value = value as u16;
    let len = std::mem::size_of::<u16>();
    let ptr = buffer.add(std::mem::size_of::<u16>() * (*size as isize) / std::mem::size_of::<u16>());
    std::ptr::copy_nonoverlapping(std::mem::transmute_const(&value as *const u16), ptr, len);
    *size += len;
    len as isize
}

unsafe fn TPM2B_Marshal<T: Copy>(value: &[T], buffer: *mut u8, size: *mut isize) -> isize {
    let len = std::mem::size_of::<T>() * value.len();
    let ptr = buffer.add(*size as isize + len);
    std::ptr::copy_nonoverlapping(value.as_ptr(), ptr, len);
    *size += len;
    len as isize
}

