use std::fs;
use std::path::Path;
use std::io::{self, Write};

fn append_file_contents(args: Vec<String>, file_path: &str) -> String {
    let path = Path::new(file_path);
    if !path.is_file() {
        panic!("Supplied file does not exist");
    }

    let file_contents = fs::read_to_string(path).expect("Failed to read file");
    let mut output = file_contents;

    for arg in args.iter().skip(1) {
        output.push_str(&format!(" {}", arg));
    }

    output
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <file_path> [additional_args...]", args[0]);
        std::process::exit(1);
    }

    let file_path = &args[1];
    let result = append_file_contents(args, file_path);
    println!("{}", result);
}
