use std::io::{Result as IoResult, Error};
use std::os::unix::io::AsRawFd;
use std::ptr;

pub unsafe fn run_with_io_context<F, T>(closure: F) -> IoResult<T> where F: FnOnce() -> Option<IoResult<T>> {
    match closure() {
        Some(result) => result,
        None => {
            let local_task = std::thread::current();
            let io_factory = std::sync::Arc::new(unsafe { libc::io_context_create(0) });

            let mut task = mem::transmute::<_, libc::task_t>(local_task);
            task.io_context = io_factory.as_raw();

            let result = match closure() {
                Some(res) => res,
                None => {
                    let io_result = closure();
                    if io_result.is_err() {
                        return io_result.unwrap_err();
                    }
                    io_result.unwrap()
                }
            };

            task.io_context = ptr::null_mut();
            libc::io_context_destroy(task.io_context);

            result
        }
    }
}

// Example usage:
fn example_closure() -> Option<IoResult<i32>> {
    let file = unsafe { libc::open("/dev/null", libc::O_RDONLY) };
    if file < 0 {
        return Err(Error::last_os_error());
    }

    let result = unsafe { libc::read(file, &mut [0; 1], 1) };
    if result < 0 {
        return Err(Error::last_os_error());
    }

    Some(Ok(result as i32))
}

fn main() {
    let result = unsafe { run_with_io_context(example_closure) };
    println!("Result: {:?}", result);
}
