use std::env;
use std::error::Error;
use std::process;
use std::sync::Arc;

use dist::http::{Http, Response, Request, ServerHandle, Server};
use net::TcpListener;
use net::TcpStream;

struct ServerId {
    ip: String,
    port: String,
}

fn create_server(server_id: ServerId) -> Result<ServerHandle, Box<dyn Error>> {
    let (ip, port) = (server_id.ip, server_id.port);

    // Set environment variable and initialize logger
    let _ = env::set_var("RUST_LOG", "sccache=trace");
    let _ = env_logger::init();

    // Fork a new process to run the server in the background
    let pid = match fork() {
        Ok(0) => process.id(),
        Err(_) => {
            return Err(Box::new(Error::new(
                std::io::ErrorKind::Other,
                "Failed to fork process",
            )));
        }
    };

    // Create HTTP server in the child process
    let server = Arc::new(Server::new((ip.parse().unwrap(), port.parse().unwrap())));
    let handle = match Http::new(server) {
        Ok(handle) => handle,
        Err(e) => {
            return Err(Box::new(e));
        }
    };

    // Listen for incoming connections
    let listener = TcpListener::bind((ip, port)).unwrap();
    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let request = Request::new(stream)?;
                let response = Response::new(request, &handle)?;
                response.send(&mut stream)?;
            }
            Err(e) => {
                eprintln!("Error handling connection: {}", e);
            }
        }
    }

    // Exit the child process
    unsafe {
        libc::exit(0);
    }

    // Wait for the child process to finish
    let _ = waitpid(pid, None);

    Ok(handle)
}
