use std::env;
use std::fs;
use std::path::{Path, PathBuf};

fn system_root() -> Result<PathBuf, Box<dyn std::error::Error>> {
    let current_exe_path = env::current_exe()?;
    let current_exe_dir = current_exe_path.parent()?;

    let mut root_path = if current_exe_dir.is_absolute() {
        current_exe_dir
    } else {
        // Try to follow symbolic links to get the absolute path of the current directory
        let mut parent = current_exe_dir;
        while let Some(link) = fs::read_link(&parent)?.ok() {
            parent = link.path();
        }
        parent
    };

    // Follow the root symbolic link
    let mut root = root_path;
    while root.starts_with("/.") {
        root.pop_front();
        root.push("/");
        root_path = fs::read_link(&root)??.into_meta_data().unwrap().parent().unwrap();
    }

    Ok(root)
}
