static SQLRETURN set_handle_attribute(SQLHANDLE handle, const char *attr_name, const char *attr_value) {
    SQLINTEGER attr;
    SQLINTEGER size;
    SQLRETURN ret;

    // Find the attribute number based on its name
    ret = SQLGetInfo(handle, SQL_HANDLE_ENV, SQL_ATTR_KEYWORDS, NULL, &size, NULL);
    if (ret != SQL_SUCCESS || size <= 0) {
        return ret;
    }

    char** keywords = (char**) malloc(size * sizeof(char*));
    if (!keywords) {
        return SQL_ERROR;
    }

    ret = SQLGetInfo(handle, SQL_HANDLE_ENV, SQL_ATTR_KEYWORDS, keywords, size * sizeof(char*), NULL);
    if (ret != SQL_SUCCESS) {
        free(keywords);
        return ret;
    }

    for (int i = 0; keywords[i] != NULL; ++i) {
        if (strcmp(keywords[i], attr_name) == 0) {
            attr = i + 1;
            break;
        }
    }

    free(keywords);

    if (attr <= 0) {
        return SQL_ERROR;
    }

    // Set the attribute value
    size = strlen(attr_value) + 1; // include null terminator
    ret = SQLSetConnectAttr(handle, attr, attr_value, (SQLINTEGER)size);

    return ret;
}
