use std::process::Command;

fn run_compiler(input: &[&str], closure: Box<dyn FnOnce() + Send + Sync>, output: &mut i32) {
    let output_process = Command::new("rustc")
        .args(input)
        .output()
        .expect("Failed to run compiler");

    let status = output_process.status;
    if status.success() {
        closure();
        *output = 0;
    } else {
        *output = status.code().unwrap_or(1);
    };
