fn update_cargo_toml(directory: &str, verbose: bool, quiet: bool, color: bool, frozen: bool, locked: bool, manifest_path: Option<&str>) -> Result<(), Box<dyn std::error::Error>> {
    let current_dir = std::env::current_dir()?;
    let project_dir = PathBuf::from(directory);

    let mut context = Context::new(".")?;
    context.load_directory(&project_dir)?;

    let manifest_path = manifest_path.map_or(PathBuf::from("Cargo.toml"), |path| PathBuf::from(path));
    let mut toml = Toml::from_file(&manifest_path)?;

    if frozen {
        toml.freeze()?;
    }

    if locked {
        toml.lock()?;
    }

    let mut update_required = false;

    if verbose {
        println!("Updating Cargo.toml in {}", project_dir.display());
    }

    if quiet {
        std::io::stdout().flush()?;
    }

    if color {
        context.color_output(true)?;
    }

    let dependencies = toml.dependencies_mut();

    for dep in dependencies.iter_mut() {
        if dep.version.is_none() {
            update_required = true;
            break;
        }
    }

    if update_required {
        context.install()?;
        toml = Toml::from_file(&manifest_path)?;
    }

    toml.save(&manifest_path)?;

    if verbose {
        println!("Cargo.toml updated in {}", project_dir.display());
    }

    Ok(())
}
