fn main() {
    let port: u16 = 8080;
    let listener = TcpListener::bind("127.0.0.1": port).unwrap();
    println!("Listening on 127.0.0.1:{}", port);

    let num_cpus = num_cpus();
    let thread_pool = thread::Scope::new().unwrap().thread_pool().new(num_cpus);

    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let encoder = GzEncoder::new(Vec::new(), Compression::Optimal);
                thread_pool.spawn(move || {
                    let mut buffer = [0; 1024];
                    loop {
                        let bytes_read = stream.read(&mut buffer).unwrap();
                        if bytes_read == 0 {
                            break;
                        }
                        let mut compressed_data = Vec::new();
                        encoder.write(&mut compressed_data, &buffer[..bytes_read]).unwrap();
                        stream.write_all(&compressed_data).unwrap();
                    }
                    stream.close().unwrap();
                });
            }
            Err(e) => eprintln!("Error accepting connection: {}", e),
        }
    }
}

fn num_cpus() -> usize {
    num_cpus::get()
}
