use std::sync::Logger; // Import Logger and LogBuilder from std::sync
use std::env; // Import env variable parsing functions
use std::fmt; // Import fmt for formatting logs
use std::error::Error; // Import Error for error handling

struct CustomLogger {
    logger: Logger,
    log_level: LogLevel,
    formatter: Box<dyn FnMut(LogRecord) -> String>,
}

enum LogLevel {
    Trace,
    Debug,
    Info,
    Warning,
    Error,
    Panic,
}

impl LogLevel {
    fn level_value(&self) -> u32 {
        match self {
            LogLevel::Trace => LogLevelFilter::Trace as u32,
            LogLevel::Debug => LogLevelFilter::Debug as u32,
            LogLevel::Info => LogLevelFilter::Info as u32,
            LogLevel::Warning => LogLevelFilter::Warning as u32,
            LogLevel::Error => LogLevelFilter::Error as u32,
            LogLevel::Panic => LogLevelFilter::Panic as u32,
        }
    }
}

impl From<&str> for LogLevel {
    fn from(value: &str) -> Self {
        match value {
            "trace" => LogLevel::Trace,
            "debug" => LogLevel::Debug,
            "info" => LogLevel::Info,
            "warning" => LogLevel::Warning,
            "error" => LogLevel::Error,
            "panic" => LogLevel::Panic,
            _ => LogLevel::Info, // Default to info if unknown level is provided
        }
    }
}

struct LogRecord {
    level: LogLevel,
    args: Vec<fmt::Argument>,
}

impl LogRecord {
    fn to_string(&self, formatter: &Box<dyn FnMut(LogRecord) -> String>) -> String {
        let formatted_args: Vec<String> = self.args.iter().map(|arg| arg.to_string()).collect();
        formatter(LogRecord { level: self.level, args: formatted_args })
    }
}

fn init_logger() -> Result<CustomLogger, Box<dyn Error>> {
    let log_level_str = env::var("LOG_LEVEL")?;
    let log_level = LogLevel::from(&log_level_str);

    let formatter = Box::new(move |record: LogRecord| {
        format!("[{}] {}", record.level, record.args.join(" "))
    });

    let mut log_builder = Logger::builder("my_logger", LogLevelFilter::Info as u32);
    log_builder.filter(log_level.level_value(), LogLevelFilter::LogLevel);
    log_builder.format(|record, _| record.to_string(&formatter));

    Ok(CustomLogger {
        logger: log_builder.build(),
        log_level,
        formatter,
    })
}
