use std::env;
use std::path::PathBuf;

fn create_unique_dir(base_name: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let current_dir = env::current_dir()?;
    let root_dir = current_dir.to_str().unwrap();
    let root_dir_ends_with_deps = root_dir.ends_with("deps");

    if root_dir_ends_with_deps {
        current_dir.pop();
    }

    let mut base_path = PathBuf::from(&current_dir);
    base_path.push(base_name);
    base_path.push(format!("{}", uuid::Uuid::new_v4().to_string().as_str()));

    std::fs::create_dir_all(&base_path)?;

    Ok(base_path)
}
