use base64::decode;

struct Secret {
    data: String,
}

fn decrypt(encrypted_blob: &str) -> Option<Secret> {
    let device_id = "device_id"; // replace with actual device ID
    let username = "username"; // replace with actual username

    let mut key = [0; 32]; // SHA-1 produces a 160-bit hash, so we need a 32-byte key
    let device_id_hash = Sha1::new().chain(device_id.as_bytes()).result();
    let username_hash = Sha1::new().chain(username.as_bytes()).result();

    key[..device_id_hash.len().min(32)].clone_from_slice(&device_id_hash);
    key[..username_hash.len().min(32)].clone_from_slice(&username_hash);

    let decoded_blob = decode(encrypted_blob).ok()?;
    let mut hmac = Hmac::<Sha1>::new(key);

    let slice: &[u8] = &decoded_blob;
    let len = slice.len();

    if len < hmac.output_len() {
        return None;
    }

    let expected_digest = hmac.compute(slice);
    if expected_digest != slice[len - hmac.output_len()..] {
        return None;
    }

    let decrypted_data = String::from_utf8_lossy(&slice[..len - hmac.output_len()]);

    Some(Secret { data: decrypted_data.into() })
}
