fn generate_fdset(protobuf_file_path: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let temp_file_name = format!("{}.temp.proto", PathBuf::new(protobuf_file_path).file_name().unwrap().to_str().unwrap());
    let temp_file_path = PathBuf::from(temp_file_name);

    // Write protobuf file to temporary file
    let mut temp_file = File::create(&temp_file_path)?;
    File::write_all(protobuf_file_path, &[0; 0])?; // Empty the original file
    File::copy(protobuf_file_path, &mut temp_file)?;

    // Run protoc compiler on temporary file to generate fdset
    let mut compiler = ProtobufCompiler::new();
    let fdset_path = compiler.compile(&temp_file_path, "fdset")?;

    Ok(fdset_path)
}
