fn create_web_server(address: &str) -> Manager {
    let mut config = Configuration::new();
    let mut mounts = MountPoint::new();

    // Mount static directory
    let static_dir = PathBuf::from("./static");
    mounts.mount("/", File::new(static_dir), FileResponse::default());

    // Mount API handler
    let api_handler = move |req: &Request, _res: &mut Response| {
        let method = req.method();
        let body = req.body();

        let response_body = match (method, body) {
            (&Method::Get, Some(_)) => "Hello, this is a static file server!".to_string(),
            (&Method::Post, Some(_)) => {
                let data = body.collect::<Vec<u8>>();
                format!("Received POST request with body length: {} bytes", data.len())
            }
            _ => "Invalid request method or body".to_string(),
        };

        Response::with_status(StatusCode::Ok, response_body)
    };
    mounts.mount("/api", Box::new(api_handler), chain!(
        StatusHandler::new(StatusCode::MethodNotAllowed),
        BodyResponse::html("<h1>Method Not Allowed</h1>"),
    ));

    config.handle_error(|err, _| {
        println!("Error occurred: {:?}", err);
        Response::with_status(StatusCode::InternalServerError, "Internal Server Error")
    });

    let socket_addr = SocketAddr::try_from(address).unwrap();
    let mut manager = Manager::new(config);
    manager.listen(socket_addr).unwrap();

    manager
}
