pub fn create_process(process_metadata: Arc<ProcessMetadata>, command_runner: CommandRunner, nailgun_enabled: bool) -> Box<dyn CommandRunner> {
    let local_command_runner = LocalCommandRunner::new(
        command_runner,
        Arc::new(Executor::new()),
        "/path/to/process/temp/files"
    );

    let nailgun_command_runner = if nailgun_enabled {
        Some(Box::new(NailgunCommandRunner::new(
            Arc::downgrade(&local_command_runner),
            process_metadata.clone(),
            "/path/to/process/temp/files"
