```rust use std::fs::Metadata; use std::path::Path;

fn copy_directory(source: &Path, destination: &Path) -> Result<(), Box<dyn std::error::Error>> {
    if source == destination {
        return Ok(());
    }

    if source.is_file() {
        let source_file_name = source.file_name().unwrap().to_string_lossy().to_string();
        let destination_file_path = destination.join(source_file_name);

        if destination_file_path.exists() {
            println!("Skipping file copy: {} exists in destination", source_file_name);
            return Ok(());
        }

        let source_file_data = fs::read_to_string(source)?;
        fs::write(destination_file_path, source_file_data)?;

        println!("Copied file: {} from {} to {}", source_file_name, source.display(), destination.display());
    } else if source.is_dir() {
        fs::create_dir_all(destination)?;

        for entry in source.read_dir()? {
            let entry_path = entry?;
            let entry_name = entry_path.file_name().to_string_lossy().to_string();
            let destination_path = destination.join(entry_name);

            if entry_path.is_dir() {
                copy_directory(&entry_path, &destination_path)?;
            } else {
                copy_file(&entry_path, &destination_path)?;
            }
        }

        println!("Copied directory: {} from {} to {}", source.file_name().unwrap().to_string_lossy().to_string(), source.display(), destination.display());
    } else {
        return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Neither a file nor a directory",
        )));
    }

    Ok(())
}

fn copy_file(source: &Path, destination: &Path) -> Result<(), Box<dyn std::error::Error>> {
    if source.is_file() {
        let source_file_name = source.file_name().unwrap().to_string_lossy().to_string();
        let destination_file_path = destination.join(source_file_name);

        if destination_file_path.exists() {
            println!("Skipping file copy: {} exists in destination", source_file_name);
            return Ok(());
        }

        fs::copy(source, destination)?;

        println!("Copied file: {} from {} to {}", source_file_name, source.display(), destination.display());

        let metadata = fs::metadata(destination)?;
        fs::set_permissions(destination, metadata.perm());

        Ok(())
    } else {
        return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Source is not a file",
        )));
    }
}

fn main() {
    let source = Path::new("/path/to/source");
    let destination = Path::new("/path/to/destination");

    copy_directory(source, destination).unwrap();
}
```

