        if let Ok(line) = line {
            lines += 1;
        }
    }

    let mut cmdline = env::args();
    cmdline.drain(..1); // Drain the program name
    cmdline.extend(args);

    config.set_cargo_toml_path(None);
    config.set_crate_name(crate_name);
    config.add_source_file(file_path);

    for lib in libraries {
        config.add_library(lib);
    }

    for dep in dependencies {
        config.add_dependency(dep);
    }

    config.build_target("main", &mut diagnostic).unwrap();

    lines
}
