```rust use mach::{header::mach_header, load_command, segment_command, segment_command_64, Arch, MachError};

fn parse_binary_file(path: &str) -> Result<(), MachError> {
    let file = std::fs::File::open(path)?;
    let data = Vec::new();
    let mut reader = std::io::BufReader::new(file);
    data.extend_from_slice(&mut reader.bytes().collect::<Vec<u8>>()?);

    let header_size = if is_32bit(&data[..]) {
        MachHeader32::size()
    } else {
        MachHeader64::size()
    };

    let mut header = if is_32bit(&data[..]) {
        let mut buf = [0; MachHeader32::size()];
        data.copy_within(0, buf.as_mut_slice().as_mut().as_mut().offset()..);
        unsafe { MachHeader32::from_raw(buf.as_ptr()) }
    } else {
        let mut buf = [0; MachHeader64::size()];
        data.copy_within(0, buf.as_mut_slice().as_mut().as_mut().offset()..);
        unsafe { MachHeader64::from_raw(buf.as_ptr()) }
    };

    let should_swap = swap_bytes(&header.magic);

    if should_swap {
        header.swap();
    }

    println!("Magic: {:x?}", header.magic);
    println!("Architecture: {:?}", Arch::from_cputype(header.cputype));
    println!("File type: {:?}", header.filetype);

    let seg_count = parse_segments(&data, header.ncmds, should_swap)?;

    println!("Number of segments: {}", seg_count);

    Ok(())
}

fn parse_segments(data: &[u8], cmds_count: usize, should_swap: bool) -> Result<usize, MachError> {
    let mut seg_count = 0;

    for i in 0..cmds_count {
        let cmd_offset = header_command_offset(data, i);
        let command = load_command(&data[cmd_offset..])?;

        if should_swap {
            command.swap();
        }

        match command.command() {
            CommandType::Segment { .. } | CommandType::Segment64 { .. } => {
                seg_count += 1;
                parse_segment(&data[cmd_offset..], seg_count)?;
            }
            _ => {}
        }
    }

