int create_temp_file_descriptors(int *fd_read, int *fd_write) {
    int temp_file_fd;
    int new_fd_read, new_fd_write;

    temp_file_fd = mkstemp("/tmp/temp_XXXXXX.txt");
    if (temp_file_fd < 0) {
        perror("Error creating temporary file");
        return 1;
    }

    if (fcntl(temp_file_fd, F_SETFL, O_BINARY) < 0) {
        perror("Error setting O_BINARY flag");
        close(temp_file_fd);
        return 1;
    }

    if (fcntl(temp_file_fd, F_SETFD, FD_CLOEXEC) < 0) {
        perror("Error setting O_NOINHERIT flag");
        close(temp_file_fd);
        return 1;
    }

    new_fd_read = open(getcwd() "/tmp/temp_XXXXXX.txt", O_RDONLY | O_BINARY);
    if (new_fd_read < 0) {
        perror("Error opening file for reading");
        close(temp_file_fd);
        return 1;
    }

    new_fd_write = temp_file_fd;

    *fd_read = new_fd_read;
    *fd_write = new_fd_write;

    return 0;
}
