use std::process::Command;
use std::env;
use std::error::Error;

fn open_file(path: &str) -> Result<String, String> {
    let browser = env::var("BROWSER").unwrap_or_else(|_| String::from(""));
    if !browser.is_empty() {
        let output = Command::new(&browser)
            .arg(path)
            .output()
            .map_err(|e| format!("Failed to execute command: {}", e))?;
        if output.status.success() {
            return Ok(format!("Opened file '{}' using '{}'", path, browser));
        }
    }

    let alternatives = vec!["xdg-open", "gnome-open", "kde-open"];
    for alternative in alternatives {
        let output = Command::new(alternative)
            .arg(path)
            .output()
            .map_err(|e| format!("Failed to execute command: {}", e))?;
        if output.status.success() {
            return Ok(format!("Opened file '{}' using '{}'", path, alternative));
        }
    }

    Err(format!("Failed to open file '{}' using any of the following methods: {:?}", path, alternatives))
}
