#include <filesystem>
#include <nlohmann/json.hpp> // For JSON manipulation

namespace fs = std::filesystem;
using json = nlohmann::json;

std::string CreateGenesisTransactionFile(const std::string& poolName, const std::vector<json>& nodes, const std::vector<json>& transactions) {
    std::string genesisTransactionFile = poolName + "_genesis.json";
    fs::path path(poolName);
    if (!fs::exists(path)) {
        fs::create_directory(path);
    }
    path /= genesisTransactionFile;

    json genesisTransaction;
    genesisTransaction["pool_name"] = poolName;
    genesisTransaction["nodes"] = nodes;
    genesisTransaction["transactions"] = transactions;

    std::ofstream file(path.string());
    file << std::setw(4) << genesisTransaction << std::endl;

    return path.string();
}
