use std::env;
use std::path::PathBuf;

fn find_command(command_name: &str) -> Option<PathBuf> {
    let current_dir = std::env::current_dir().unwrap();
    let mut search_dirs: Vec<PathBuf> = vec![current_dir];

    // Add parent directory
    search_dirs.push(current_dir.parent().unwrap());

    // Add directories from PATH environment variable
    let path = env::var("PATH").unwrap();
    let paths: Vec<&str> = path.split(":").collect();

    for path_str in paths {
        let path_buf = PathBuf::from(path_str);
        search_dirs.push(path_buf);
    }

    for dir in &search_dirs {
        let executable_path = dir.join(command_name);
        if executable_path.is_file() {
            return Some(executable_path);
        }
    }

    None
}
