use std::os::raw::c_int;
use std::os::raw::c_uint;
use std::ptr;
use openssl::message::MessageDigest;
use openssl::md::Md5;

fn md5_hash_and_manipulate(input: &[u8], output: &mut [u8; 16]) -> u64 {
    let mut context = Md5::new().unwrap();
    context.update(input).unwrap();
    context.finalize().unwrap();

    let mut hash = [0; 16];
    context.result().copy_into(&mut hash);

    let mut final_output = [0; 8];
    for i in 0..8 {
        final_output[i] = hash[i] as u64 | (hash[i+8] as u64 << 32);
    }

    unsafe {
        ptr::copy_nonoverlapping(final_output.as_ptr(), output.as_mut_ptr(), 8);
    }

    0
}

fn rust_function(input: &[u8], output: &mut [u8; 16]) -> u64 {
    let result = md5_hash_and_manipulate(input, output);
    result
}
