fn hmac_sha1(map: &HashMap<String, String>, secret: &str) -> String {
    let secret_bytes = secret.as_bytes();
    let mut key = [0u8; 64];
    key[..secret_bytes.len().min(64)].clone_from_slice(secret_bytes);

    let mut input = Vec::new();
    for (k, v) in map {
        input.extend_from_slice(k.as_bytes());
        input.extend_from_slice(v.as_bytes());
    }

    let mut ipad = [0u8; 64];
    let mut opad = [0u8; 64];

    for i in 0..64 {
        ipad[i] = ipad[i] ^ key[i];
        opad[i] = opad[i] ^ 0x36;
    }

    let mut hasher = sha1::Sha1::new();
    hasher.update(b"k");
    hasher.update(secret_bytes);
    hasher.update(b"d");

    let mut data = Vec::new();
    hasher.finish().write(&mut data).unwrap();

    for byte in data {
        ipad[56 + (byte as usize) % 64] = ipad[56 + (byte as usize) % 64] ^ key[byte as usize];
    }

    hasher = sha1::Sha1::new();
    hasher.update(b"");

    let mut p = Peekable::new(Chars::new(input.as_str()));
    let mut text = String::new();

    loop {
