fn generate_pact_file(pact: &Pact, output_path: &str) -> String {
    let temp_dir = tempfile::tempdir().expect("Failed to create temporary directory.");
    let temp_file_path = temp_dir.path().join("pact_file.pct");

    let mut file = File::create(temp_file_path).expect("Failed to create temporary file.");

    let mut pact_bytes = pact.to_bytes(); // Assuming `Pact` has a `to_bytes` method to convert it to a vector of bytes

    file.write_all(&pact_bytes).expect("Failed to write PACT data to file.");

    let mut header = [0u8; 16]; // V4 PACT file header
    header[0..4].clone_from_slice(&[0x43, 0x61, 0x6D, 0x74]); // 'Cmat'
    header[4..8].clone_from_slice(&[0x31, 0x30, 0x34, 0x31]); // '1041'

    file.write_all(&header).expect("Failed to write header to file.");

    let file_size = pact_bytes.len() as u32;
    let mut file_size_bytes = [0u8; 4];
    file_size_bytes.copy_from_slice(&file_size.to_le_bytes());

    file.write_all(&file_size_bytes).expect("Failed to write file size to file.");

    file.write_all(&pact_bytes).expect("Failed to write PACT data to file again.");

    file.sync_all().expect("Failed to flush file.");

    let file_contents = std::fs::read_to_string(temp_file_path).expect("Failed to read file.");

    std::fs::remove_file(temp_file_path).expect("Failed to remove temporary file.");
    temp_dir.remove().expect("Failed to remove temporary directory.");

    file_contents
}
