fn compile_rust_with_hook() -> i32 {
    let start = Instant::now();

    // Install ice hook using SyncLazy
    let ice_hook = SyncLazy::new(|| {
        println!("Installing ice hook...");
        // Ice hook installation logic here
        Box::new(())
    });

    // Run Rust compiler with custom logging hook
    let mut cmd = Command::new("rustc");
    cmd.args(["--", "-"]) // Pass input file(s) as arguments
        .stdout(std::process::Stdio::null())
        .stderr(std::process::Stdio::piped())
        .spawn()
        .expect("Failed to spawn Rust compiler process")
        .stdin(std::process::Stdio::piped())
        .expect("Failed to set up stdin for Rust compiler process");

    // Measure resident set size before compilation
    let resident_set_size_before = Box::new(std::mem::size_of_val(&cmd) as u64);

    // Install ice hook before compilation
    ice_hook.get().expect("Failed to get ice hook");

    // Catch errors during compilation and report using early_error
    let exit_code = catch_with_exit_code(move || {
        cmd.stdin.write_all(b"").expect("Failed to write to Rust compiler stdin");
        cmd.stdin.flush().expect("Failed to flush Rust compiler stdin");
        cmd.output()
            .expect("Failed to get Rust compiler output")
            .error_stream
