            .for_each(|byte| print!("{}", byte as char))
            .expect("Failed to print Rust compiler error stream");
        cmd.wait().expect("Failed to wait for Rust compiler process to finish");
        EarlyExit::new(cmd.status().code().unwrap_or(1))
    });

    // Measure resident set size after compilation
    let resident_set_size_after = Box::new(std::mem::size_of_val(&cmd) as u64);

    let elapsed = Instant::now().duration_since(start).as_millis();

    println!(
        "Compilation completed with exit code: {:?}\nResident set size before compilation: {:?} bytes\nResident set size after compilation: {:?} bytes\nCompilation took {:?} ms",
