fn create_wallet(config_value: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
    let wallet_dir = Path::new(&config_value).to_owned();
    let wallet_dir_path = wallet_dir.join(format!("{}", config_value));

    // Remove existing directory if it exists
    if let Some(error) = File::remove(wallet_dir_path) {
        if error.kind() == ErrorKind::NotFound {
            // Directory does not exist, continue
        } else {
            return Err(box_err!("Failed to remove existing directory: {}", error));
        }
    }

    // Create new directory
    if let Err(error) = std::fs::create_dir_all(&wallet_dir_path) {
        return Err(box_err!("Failed to create directory: {}", error));
    }

    let private_key_file = wallet_dir_path.join("private_key.txt");

    // Remove existing file if it exists
    if let Some(error) = File::remove(private_key_file) {
        if error.kind() == ErrorKind::NotFound {
            // File does not exist, continue
        } else {
            // Failed to remove existing file, return error
            return Err(box_err!("Failed to remove existing file: {}", error));
