use std::collections::HashMap;
use std::sync::Arc as ArcSync;
use std::ptr;
use std::mem;
use std::cell::RefCell;

type CommandPool = RefCell<HashMap<usize, Vec<Arc<Cmd>>>>;
type AnswerPool = RefCell<HashMap<usize, Vec<Arc<Answer>>>>;
type ClientDataPool = RefCell<HashMap<usize, Arc<ClientData>>>;

struct ClientData {
    connection: Option<Box<dyn Send + Sync + 'static + std::io::Read + std::io::Write>>,
    id: usize,
}

struct Cmd {
    id: usize,
    data: Option<Box<dyn Send + Sync + 'static>>,
}

struct Answer {
    id: usize,
    data: Option<Box<dyn Send + Sync + 'static>>,
}

struct PoolData {
    buffer_size: usize,
    command_pool: CommandPool,
    answer_pool: AnswerPool,
    client_data_pool: ClientDataPool,
    closed_clients: Arc<Mutex<Vec<usize>>>,
}

impl PoolData {
    fn new(buffer_size: usize) -> Self {
        PoolData {
            buffer_size,
            command_pool: RefCell::new(HashMap::new()),
            answer_pool: RefCell::new(HashMap::new()),
            client_data_pool: RefCell::new(HashMap::new()),
            closed_clients: Arc::new(Mutex::new(Vec::new())),
        }
    }
}

impl Drop for PoolData {
    fn drop(&mut self) {
        for id in self.closed_clients.lock().iter() {
            let _ = self.command_pool.borrow_mut().remove(id);
            let _ = self.answer_pool.borrow_mut().remove(id);
            let _ = self.client_data_pool.borrow_mut().remove(id);
        }
    }
}

impl PoolData {
    fn get_command_pool(&self) -> &CommandPool {
        &self.command_pool
    }

    fn get_answer_pool(&self) -> &AnswerPool {
        &self.answer_pool
    }

    fn get_client_data_pool(&self) -> &ClientDataPool {
        &self.client_data_pool
    }

    fn get_closed_clients(&self) -> &Arc<Mutex<Vec<usize>>> {
        &self.closed_clients
    }
}

impl PoolData {
    fn create(buffer_size: usize) -> Arc<PoolData> {
        let pool_data = PoolData::new(buffer_size);
        Arc::new(pool_data)
    }
}
