fn fold_header(input: &str) -> String {
    let mut header = input.to_owned(); // Create a mutable string from the input
    let mut line_length = 0;

    for (i in (0..header.len()).rev()) {
        if i == 0 {
            if line_length + header[i..].len() > 72 {
                header.truncate(i);
                break;
            }
            line_length += header[i..].len() + 1; // Add 1 for the space between words
        } else if header[i] == ' ' {
            if line_length + header[i..].len() > 72 {
                header.truncate(i + 1);
                break;
            }
            line_length += header[i..].len() + 1;
        }
    }

    header
}
