use std::collections::HashMap;
use std::str::FromStr;

struct HeaderValue { value: String }
impl FromStr for HeaderValue { type_name = "HeaderValue"; fn from_str(s: &str) -> Result<Self, ()> { Ok(HeaderValue { value: s.to_owned() }) } }

struct Header { name: String, value: Option<HeaderValue> }
impl Header {
    fn new(name: &str, value: Option<&str>) -> Self {
        Header {
            name: name.to_owned(),
            value: value.map(HeaderValue::from_str),
        }
    }
}

struct Headers { inner: HashMap<String, Header> }
impl Headers {
    fn insert_raw(&mut self, name: String, value: String) {
        self.inner.insert(name, Header { name, value: Some(HeaderValue { value }) });
    }

    fn as_str(&self) -> String {
        let mut headers = String::new();
        for (name, header) in self.inner.iter() {
            headers.push_str(&format!("{}: {}\r\n", name, header.value.as_ref().unwrap().value));
        }
        headers
    }
}

fn create_header(input: &str) -> Headers {
    let mut headers = Headers { inner: HashMap::new() };
    let header_name = "X-Custom-Header".to_owned();
    headers.insert_raw(header_name, input.to_owned());
    headers
}

fn main() {
    let input = "example_value";
    let headers = create_header(input);
    println!("{}", headers.as_str());
}
