use reqwest::Client;
use std::fs::File;
use std::io::Read;

pub fn custom_reqwest_client(user_agent: &str, cert_path: &str) -> Client {
    let mut client = Client::new();

    client = client.user_agent(user_agent);
    client = client.danger_accept_invalid_certs(true);

    let cert_file = File::open(cert_path).expect("Failed to open certificate file");
    let mut cert_bytes = Vec::new();
    cert_file.read_to_end(&mut cert_bytes).expect("Failed to read certificate file");

    client = client.ssl_no_validate()
        .ssl_ca_certificate(cert_bytes.as_ref())
        .build()
        .expect("Failed to build SSL config");

    client = client.danger_disable_body_decompression(true);
    client = client.connection_timeout(std::time::Duration::from_secs(5));

    client.set_global_connector(move |connector| {
        connector.clone().build_ connector.set_send_timeout(std::time::Duration::from_secs(5)) });

    client = client.default_headers(reqwest::header::HeaderMap::new()
        .insert(reqwest::header::CONNECTION, "close".parse().unwrap()));

    client
}
