use std::env;
use std::process::Command;

fn open_file(path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let browser = env::var("BROWSER").ok();
    let browsers = vec!["xdg-open", "firefox", "x-www-browser"];

    if let Some(ref browser_str) = browser {
        let cmd = Command::new(browser_str)?;
        cmd.arg(path)?;
        cmd.output()?;
        Ok(())
    } else {
        for browser in browsers {
            let cmd = Command::new(browser)?;
            cmd.arg(path)?;
            match cmd.output() {
                Ok(_) => return Ok(()),
                Err(_) => continue,
            }
        }
        Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            "Could not find a valid browser to open the file",
        )))?)
    }
}
