pub fn secure_connection(host: &str, port: u16, key_file: Option<&str>, cert_file: Option<&str>, disable_validation: bool, ca_certs: Option<&str>, nodelay: bool) -> Result<SslStream<TcpStream>, Box<dyn std::error::Error>> {
    let context_builder = SslContextBuilder::new("tls")?;

    if disable_validation {
        context_builder.load_verify_locations(false)?;
        context_builder.set_verify(VerifyMode::None);
    } else {
        let ca_cert = match ca_certs {
            Some(path) => Certificate::from_pem_file(path)?,
            None => return Err(Box::new(ssl::Error::NoCertificates)),
        };
        context_builder.add_certs(X509Cert::from_pem(&ca_cert.certificate())?, X509KeyPair::from_pem(key_file.unwrap(), &ca_cert.private_key())?)?;
    }

    let mut sock = match TcpStream::connect((host, port)) {
        Ok(socket) => socket,
        Err(error) => return Err(Box::new(error)),
    };

    let ssl_stream = match context_builder.build_stream(&mut sock) {
        Ok(stream) => stream,
        Err(error) => return Err(Box::new(error)),
    };

    if let Some(key_file) = key_file {
        match ssl_stream.key_manager().private_key() {
            Some(key) => match X509KeyPair::from_pem(key_file, key) {
                Ok(_) => {},
                Err(error) => return Err(Box::new(error)),
            },
            None => return Err(Box::new(ssl::Error::PrivateKeyMissing)),
        }
    }

    if let Some(cert_file) = cert_file {
        match X509Cert::from_pem_file(cert_file) {
            Ok(cert) => match ssl_stream.client_auth(cert, None) {
                Ok(_) => {},
                Err(error) => return Err(Box::new(error)),
            },
            Err(error) => return Err(Box::new(error)),
        }
    }

    if nodelay {
        sock.set_nodelay(true).unwrap();
        ssl_stream.set_nodelay(true).unwrap();
    }

    Ok(ssl_stream)
}
