fn command_from_str(command: &str, flavor: Option<&str>, is_windows: bool) -> Command {
    let cmd = CString::new(command).unwrap();
    let mut args = Vec::new();

    if flavor.is_some() {
        args.push(CString::new(flavor.unwrap()).unwrap());
        args.push(CString::new(command).unwrap());
    } else {
        args.push(CString::new(command).unwrap());
    }

    if is_windows {
        let cmd_str = OsStrExt::into_vec(cmd.as_bytes()).collect::<Vec<u8>>();
        let mut cmd_buf = Vec::with_capacity(cmd_str.len() + args.len() * 2);
        cmd_buf.extend_from_slice(&cmd_str);

        for arg in &args {
            let arg_bytes = arg.as_bytes();
            cmd_buf.extend_from_slice(&[b'^', b'%']);
            cmd_buf.extend_from_slice(arg_bytes);
            cmd_buf.extend_from_slice(&[b' ']);
        }

        cmd_buf.push(0);
        let cmd = Command::new("/c").arg(CString::new(std::ffi::CStr::from_bytes(cmd_buf.as_ptr()).to_str().unwrap()).unwrap());
        cmd
    } else {
        Command::new(command)
    }
}
